// argc - A bash CLI framework and command runner
// Version 1.23.0

use std::env;
use std::process;

mod parser;
mod command;
mod eval;
mod help;
mod build;
mod export;
mod completion;
mod mangen;
mod runner;

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() < 2 {
        // Look for Argcfile.sh and run it
        if let Err(e) = runner::run_argcfile(&args) {
            eprintln!("{}", e);
            process::exit(1);
        }
        return;
    }

    let result = match args[1].as_str() {
        "--argc-eval" => {
            if args.len() < 3 {
                eprintln!("Usage: argc --argc-eval <SCRIPT> <ARGS>...");
                process::exit(1);
            }
            eval::argc_eval(&args[2], &args[3..])
        }
        "--argc-export" => {
            if args.len() < 3 {
                eprintln!("Usage: argc --argc-export <SCRIPT> [OUTPATH]");
                process::exit(1);
            }
            let outpath = args.get(3).map(|s| s.as_str());
            export::argc_export(&args[2], outpath)
        }
        "--argc-build" => {
            if args.len() < 3 {
                eprintln!("Usage: argc --argc-build <SCRIPT> [OUTPATH]");
                process::exit(1);
            }
            let outpath = args.get(3).map(|s| s.as_str());
            build::argc_build(&args[2], outpath)
        }
        "--argc-mangen" => {
            if args.len() < 4 {
                eprintln!("Usage: argc --argc-mangen <SCRIPT> <OUTDIR>");
                process::exit(1);
            }
            mangen::argc_mangen(&args[2], &args[3])
        }
        "--argc-completions" => {
            if args.len() < 3 {
                eprintln!("Usage: argc --argc-completions <SHELL> [CMDS]...");
                process::exit(1);
            }
            let cmds: Vec<&str> = args[3..].iter().map(|s| s.as_str()).collect();
            completion::argc_completions(&args[2], &cmds)
        }
        "--argc-compgen" => {
            if args.len() < 5 {
                eprintln!("Usage: argc --argc-compgen <SHELL> <FILE> <ARGS>...");
                process::exit(1);
            }
            let comp_args: Vec<&str> = args[4..].iter().map(|s| s.as_str()).collect();
            completion::argc_compgen(&args[2], &args[3], &comp_args)
        }
        "--argc-create" => {
            let recipes: Vec<&str> = args[2..].iter().map(|s| s.as_str()).collect();
            runner::argc_create(&recipes)
        }
        "--argc-run" => {
            if args.len() < 3 {
                eprintln!("Usage: argc --argc-run <SCRIPT> <ARGS>...");
                process::exit(1);
            }
            runner::argc_run(&args[2], &args[3..])
        }
        "--argc-parallel" => {
            if args.len() < 3 {
                eprintln!("Usage: argc --argc-parallel <SCRIPT> <ARGS>...");
                process::exit(1);
            }
            runner::argc_parallel(&args[2], &args[3..])
        }
        "--argc-script-path" => {
            runner::argc_script_path()
        }
        "--argc-shell-path" => {
            runner::argc_shell_path()
        }
        "--argc-help" => {
            print_help();
            Ok(())
        }
        "--argc-version" => {
            println!("argc 1.23.0");
            Ok(())
        }
        _ => {
            // Try to run as Argcfile command
            if let Err(e) = runner::run_argcfile(&args) {
                eprintln!("{}", e);
                process::exit(1);
            }
            return;
        }
    };

    if let Err(e) = result {
        eprintln!("{}", e);
        process::exit(1);
    }
}

fn print_help() {
    print!("A bash cli framework, also a bash-based command runner - https://github.com/sigoden/argc

USAGE:
    argc --argc-eval <FILE> <ARGS~>            Use `eval \"$(argc --argc-eval \"$0\" \"$@\")\"`
    argc --argc-create <RECIPES~>              Create a boilerplate argcfile
    argc --argc-run <FILE> <ARGS~>             Run an argc-based script
    argc --argc-build <FILE> <OUTPATH?>        Generate bashscript without argc dependency
    argc --argc-mangen <FILE> <OUTDIR>         Generate man pages
    argc --argc-completions <SHELL> <CMDS>     Generate shell completion scripts
    argc --argc-compgen <SHELL> <FILE> <ARGS>  Generate completion candidates
    argc --argc-export <FILE>                  Export command line definitions as json
    argc --argc-parallel <FILE> <ARGS~>        Run functions in parallel
    argc --argc-script-path                    Print current argcfile path
    argc --argc-shell-path                     Print current shell path
    argc --argc-help                           Print help information
    argc --argc-version                        Print version information

");
}
RUST_EOF

