pub fn parse_script(content: &str, script_name: &str) -> Command {
    let lines: Vec<&str> = content.lines().collect();
    let mut root_cmd = Command {
        name: script_name.to_string(),
        describe: String::new(),
        long_describe: String::new(),
        version: None,
        aliases: vec![],
        flags_options: vec![],
        positionals: vec![],
        envs: vec![],
        subcommands: vec![],
        is_subcommand: false,
        metadata: vec![],
        command_fn: None,
    };

    // Add default --help and --version to root command
    // (will be done later in build_command)

    let mut current_cmd: Option<PendingCommand> = None;
    let mut root_pending = PendingCommand::new();
    let mut in_comment_block = true;

    let mut i = 0;
    while i < lines.len() {
        let line = lines[i];
        let trimmed = line.trim();

        if let Some(tag_line) = extract_tag(trimmed) {
            in_comment_block = true;
            // Parse the tag
            if let Some((tag, rest)) = parse_tag_line(tag_line) {
                // Collect continuation lines (comment lines that don't start with @)
                let mut full_rest = rest.to_string();
                let mut continuation_lines = Vec::new();
                let mut j = i + 1;
                while j < lines.len() {
                    let next = lines[j].trim();
                    if let Some(inner) = extract_comment_text(next) {
                        if !inner.trim_start().starts_with('@') {
                            continuation_lines.push(inner.to_string());
                            j += 1;
                        } else {
                            break;
                        }
                    } else {
                        break;
                    }
                }
                // Don't advance i here - each line is processed by itself

                match tag {
                    "describe" => {
                        if let Some(ref mut cc) = current_cmd {
                            cc.describe = full_rest.trim().to_string();
                            cc.long_describe = continuation_lines.join("\n");
                        } else {
                            root_pending.describe = full_rest.trim().to_string();
                            root_pending.long_describe = continuation_lines.join("\n");
                        }
                    }
                    "cmd" => {
                        // Save current_cmd to appropriate place
                        if let Some(cc) = current_cmd.take() {
                            let mut sub = build_command_from_pending(cc);
                            sub.is_subcommand = true;
                            root_cmd.subcommands.push(sub);
                        }
                        let mut new_cmd = PendingCommand::new();
                        new_cmd.describe = full_rest.trim().to_string();
                        new_cmd.long_describe = continuation_lines.join("\n");
                        current_cmd = Some(new_cmd);
                    }
                    "alias" => {
                        let aliases: Vec<String> = full_rest.split_whitespace()
                            .map(|s| s.to_string())
                            .collect();
                        if let Some(ref mut cc) = current_cmd {
                            cc.aliases.extend(aliases);
                        }
                    }
                    "arg" => {
                        let pos = parse_positional(&full_rest, &continuation_lines);
                        if let Some(ref mut cc) = current_cmd {
                            cc.positionals.push(pos);
                        } else {
                            root_pending.positionals.push(pos);
                        }
                    }
                    "option" => {
                        let fo = parse_flag_option(&full_rest, &continuation_lines, false);
                        if let Some(ref mut cc) = current_cmd {
                            cc.flags_options.push(fo);
                        } else {
                            root_pending.flags_options.push(fo);
                        }
                    }
                    "flag" => {
                        let fo = parse_flag_option(&full_rest, &continuation_lines, true);
                        if let Some(ref mut cc) = current_cmd {
                            cc.flags_options.push(fo);
                        } else {
                            root_pending.flags_options.push(fo);
                        }
                    }
                    "env" => {
                        let env = parse_env_def(&full_rest, &continuation_lines);
                        if let Some(ref mut cc) = current_cmd {
                            cc.envs.push(env);
                        } else {
                            root_pending.envs.push(env);
                        }
                    }
                    "meta" => {
                        let meta = parse_meta(&full_rest);
                        if let Some(ref mut cc) = current_cmd {
                            cc.metadata.push(meta);
                        } else {
                            root_pending.metadata.push(meta);
                        }
                    }
                    _ => {}
                }
            }
        } else if !trimmed.is_empty() && !trimmed.starts_with('#') {
            in_comment_block = false;
            // Check if this is a function definition
            if let Some(func_name) = extract_function_name(trimmed) {
                if let Some(ref mut cc) = current_cmd {
                    if cc.fn_name.is_none() {
                        cc.fn_name = Some(func_name);
                    }
                }
            }
        }

        i += 1;
    }

    // Save last pending command
    if let Some(cc) = current_cmd {
        let mut sub = build_command_from_pending(cc);
        sub.is_subcommand = true;
        root_cmd.subcommands.push(sub);
    }

    // Apply root pending
    root_cmd.describe = root_pending.describe;
    root_cmd.long_describe = root_pending.long_describe;
    root_cmd.flags_options = root_pending.flags_options;
    root_cmd.positionals = root_pending.positionals;
    root_cmd.envs = root_pending.envs;
    root_cmd.metadata = root_pending.metadata;

    // Extract version from metadata
    for meta in &root_cmd.metadata {
        if meta.name == "version" {
            root_cmd.version = Some(meta.value.clone());
        }
    }

    // Process metadata for subcommands
    process_metadata(&mut root_cmd);

    // Add help/version flag options
    add_builtin_flags(&mut root_cmd);

    root_cmd
}

struct PendingCommand {
    describe: String,
    long_describe: String,
    aliases: Vec<String>,
    flags_options: Vec<FlagOption>,
    positionals: Vec<Positional>,
    envs: Vec<EnvDef>,
    metadata: Vec<MetaTag>,
    fn_name: Option<String>,
}

impl PendingCommand {
    fn new() -> Self {
        PendingCommand {
            describe: String::new(),
            long_describe: String::new(),
            aliases: vec![],
            flags_options: vec![],
            positionals: vec![],
            envs: vec![],
            metadata: vec![],
            fn_name: None,
        }
    }
}

fn build_command_from_pending(pending: PendingCommand) -> Command {
    let fn_name = pending.fn_name.clone();
    let cmd_name = fn_name.as_deref().unwrap_or("").replace("::", " ").replace('_', "-");
    // Normalize: function name uses :: for nesting, _ for hyphens
    Command {
        name: fn_name_to_cmd_name(pending.fn_name.as_deref().unwrap_or("")),
        describe: pending.describe,
        long_describe: pending.long_describe,
        version: None,
        aliases: pending.aliases,
        flags_options: pending.flags_options,
        positionals: pending.positionals,
        envs: pending.envs,
        subcommands: vec![],
        is_subcommand: true,
        metadata: pending.metadata,
        command_fn: pending.fn_name,
    }
}

fn fn_name_to_cmd_name(fn_name: &str) -> String {
    // "builder::ls" -> "builder ls" but for subcommand naming
    // For function like "builder" -> "builder"
    // Function like "cmd_arg" -> "cmd_arg" (keep underscores in display)
    // Actually: look at examples - fn "download" -> cmd "download", fn "cmd_alias" -> cmd "cmd_alias" 
    fn_name.to_string()
}

fn extract_tag(line: &str) -> Option<&str> {
    let line = line.trim();
    if line.starts_with("# @") {
        Some(&line[2..])  // Return "@tag rest"
    } else {
        None
    }
}

fn extract_comment_text(line: &str) -> Option<&str> {
    let trimmed = line.trim();
    if trimmed.starts_with("# ") {
        Some(&trimmed[2..])
    } else if trimmed == "#" {
        Some("")
    } else if trimmed.starts_with('#') {
        // Handle "#text" without space (though unusual)
        Some(&trimmed[1..])
    } else {
        None
    }
}

fn parse_tag_line(s: &str) -> Option<(&str, &str)> {
    // s starts with "@tag"
    let s = s.trim_start_matches('@');
    let (tag, rest) = if let Some(pos) = s.find(|c: char| c.is_whitespace()) {
        (&s[..pos], s[pos..].trim_start())
    } else {
        (s, "")
    };
    Some((tag, rest))
}

fn extract_function_name(line: &str) -> Option<String> {
    // Matches: "funcname()" or "funcname() {" or "function funcname" etc.
    let line = line.trim();

    // Pattern: identifier() or identifier () or identifier()  {
    if let Some(paren_pos) = line.find('(') {
        let name_part = line[..paren_pos].trim();
        if !name_part.is_empty() && is_valid_func_name(name_part) {
            let after = line[paren_pos+1..].trim();
            if after.starts_with(')') {
                return Some(name_part.to_string());
            }
        }
    }

    // Pattern: "function name"
    if line.starts_with("function ") {
        let rest = line[9..].trim();
        let name = rest.split_whitespace().next().unwrap_or("").trim_end_matches(|c| c == '(' || c == ')' || c == '{');
        if !name.is_empty() && is_valid_func_name(name) {
            return Some(name.to_string());
        }
    }

    None
}

fn is_valid_func_name(s: &str) -> bool {
    if s.is_empty() { return false; }
    s.chars().all(|c| c.is_alphanumeric() || c == '_' || c == '-' || c == ':')
}

fn parse_positional(rest: &str, continuation: &[String]) -> Positional {
    let rest = rest.trim();

    // Parse: name[modifier][choices] notation? description
    // Examples:
    // "val" - simple optional
    // "val!" - required
    // "val*" - multi optional
    // "val+" - multi required
    // "val=xyz" - with default
    // "val=`fn`" - with default fn
    // "val[x|y|z]" - with choices
    // "val[=x|y|z]" - with choices+default
    // "val*[x|y|z]" - multi with choices
    // "val[`fn`]" - choice from fn
    // "val[?`fn`]" - choice from fn without validation
    // "val*,[`fn`]" - multi with comma-sep and choice fn
    // "val~" - terminaled (capture all)
    // "val <NOTATION>" - with explicit notation

    let (name_part, rest_part) = split_name_and_rest(rest);

    let (id, required, multiple, terminated, delimiter, modifier_default, modifier_choice) = 
        parse_positional_modifiers(&name_part);

    // Parse notation and description from rest_part
    let (notation_override, describe_text, describe_continuation) = 
        parse_notation_and_describe(&rest_part, continuation);

    let notation = if let Some(n) = notation_override {
        n
    } else {
        id.to_uppercase()
    };

    let describe = build_describe(&describe_text, &describe_continuation);

    Positional {
        id: id.clone(),
        notation,
        describe,
        required,
        multiple,
        delimiter,
        terminated,
        default: modifier_default,
        choice: modifier_choice,
        env: None,
    }
}

fn parse_positional_modifiers(s: &str) -> (String, bool, bool, bool, Option<char>, Option<DefaultValue>, Option<ChoiceValue>) {
    let mut required = false;
    let mut multiple = false;
    let mut terminated = false;
    let mut delimiter: Option<char> = None;
    let mut default: Option<DefaultValue> = None;
    let mut choice: Option<ChoiceValue> = None;

    // Check for env binding suffix ($$ or $VARNAME) - strip it
    // Actually env binding is separate, handled elsewhere

    // Parse the name part step by step
    // First extract choices if present
    let (base, choice_part) = if let Some(bracket_pos) = s.find('[') {
        (&s[..bracket_pos], Some(&s[bracket_pos..]))
    } else {
        (s, None)
    };

    // Parse choice part
    if let Some(cp) = choice_part {
        choice = parse_choice_part(cp);
    }

    // Parse base part for modifiers
    let (name, base_rest) = parse_name_modifiers(base);

    // base_rest can contain: !, *, +, ~, =value, =`fn`, ,
    let mut remaining = base_rest.as_str();
    let mut comma_sep = false;

    while !remaining.is_empty() {
        match remaining.chars().next().unwrap() {
            '!' => { required = true; remaining = &remaining[1..]; }
            '*' => { multiple = true; remaining = &remaining[1..]; }
            '+' => { required = true; multiple = true; remaining = &remaining[1..]; }
            '~' => { terminated = true; remaining = &remaining[1..]; }
            ',' => { 
                delimiter = Some(',');
                comma_sep = true;
                remaining = &remaining[1..]; 
            }
            '=' => {
                let val_part = &remaining[1..];
                // Check for choices in bracket (already parsed above)
                if val_part.starts_with('`') {
                    let end = val_part[1..].find('`').map(|p| p + 2).unwrap_or(val_part.len());
                    let fn_name = &val_part[1..end-1];
                    default = Some(DefaultValue::Fn(fn_name.to_string()));
                    remaining = &val_part[end..];
                } else {
                    // Value until end or bracket
                    let val_end = val_part.find('[').unwrap_or(val_part.len());
                    let val = &val_part[..val_end];
                    default = Some(DefaultValue::Value(val.to_string()));
                    remaining = &val_part[val_end..];
                }
            }
            _ => break,
        }
    }

    // Check if default comes from choice (like [=x|y|z])
    if let Some(ChoiceValue::Values(ref vals)) = choice {
        // If there's no default yet, check if choice has default (starts with =)
        // This is handled in parse_choice_part
    }

    (name, required, multiple, terminated, delimiter, default, choice)
}

fn parse_name_modifiers(s: &str) -> (String, String) {
    // Extract just the name (alphanumeric + _ + - + .)
    let name_end = s.find(|c: char| !c.is_alphanumeric() && c != '_' && c != '-' && c != '.')
        .unwrap_or(s.len());
    let name = s[..name_end].to_string();
    let rest = s[name_end..].to_string();
    (name, rest)
}

fn parse_choice_part(s: &str) -> Option<ChoiceValue> {
    // s looks like "[x|y|z]" or "[=x|y|z]" or "[`fn`]" or "[?`fn`]" or "[`fn`]" with comma
    if !s.starts_with('[') { return None; }
    let inner_end = s.rfind(']').unwrap_or(s.len() - 1);
    let inner = &s[1..inner_end];

    if inner.starts_with('`') || inner.starts_with("?`") {
        // Choice from function
        let skip_check = inner.starts_with('?');
        let fn_part = if skip_check { &inner[1..] } else { inner };
        let fn_name = fn_part.trim_matches('`');
        Some(ChoiceValue::Fn(fn_name.to_string(), !skip_check))
    } else if inner.starts_with('=') {
        // Choices with default
        let choices_str = &inner[1..];
        let choices: Vec<String> = choices_str.split('|').map(|s| s.to_string()).collect();
        Some(ChoiceValue::Values(choices))
    } else {
        // Just choices
        let choices: Vec<String> = inner.split('|').map(|s| s.to_string()).collect();
        Some(ChoiceValue::Values(choices))
    }
}

fn split_name_and_rest(s: &str) -> (String, String) {
    // Split "name_part description_part"
    // The name_part includes the name and all its modifiers (!, *, +, ~, =val, [choices])
    // But NOT the $ENV binding

    // Find where the "name+modifiers" ends
    // This is complex - we need to handle brackets, backticks, etc.

    let mut i = 0;
    let chars: Vec<char> = s.chars().collect();
    let len = chars.len();

    // Skip past the name itself (alphanumeric + _ + - + .)
    while i < len && (chars[i].is_alphanumeric() || chars[i] == '_' || chars[i] == '-' || chars[i] == '.') {
        i += 1;
    }

    // Skip modifiers: !, *, +, ~, comma
    while i < len && matches!(chars[i], '!' | '*' | '+' | '~' | ',') {
        i += 1;
    }

    // Skip =value or =`fn`
    if i < len && chars[i] == '=' {
        i += 1;
        if i < len && chars[i] == '`' {
            i += 1;
            while i < len && chars[i] != '`' { i += 1; }
            if i < len { i += 1; } // skip closing `
        } else {
            // Skip value until whitespace or [
            while i < len && chars[i] != ' ' && chars[i] != '\t' && chars[i] != '[' {
                i += 1;
            }
        }
    }

    // Skip [choices] or [`fn`] or [?`fn`]
    if i < len && chars[i] == '[' {
        let mut depth = 1;
        i += 1;
        while i < len && depth > 0 {
            if chars[i] == '[' { depth += 1; }
            if chars[i] == ']' { depth -= 1; }
            i += 1;
        }
    }

    // Skip $ binding
    if i < len && chars[i] == '$' {
        i += 1;
        if i < len && chars[i] == '$' {
            i += 1;
        } else {
            while i < len && (chars[i].is_alphanumeric() || chars[i] == '_') {
                i += 1;
            }
        }
    }

    let name_part: String = chars[..i].iter().collect();
    let rest_part: String = chars[i..].iter().collect();

    (name_part.trim().to_string(), rest_part.trim().to_string())
}

fn parse_notation_and_describe(s: &str, continuation: &[String]) -> (Option<String>, String, Vec<String>) {
    let s = s.trim();

    // Check for notation like <FILE> or <PATH>
    if s.starts_with('<') {
        if let Some(end) = s.find('>') {
            let notation = s[1..end].to_string();
            let describe = s[end+1..].trim().to_string();
            return (Some(notation), describe, continuation.to_vec());
        }
    }

    // Check for $ENV binding
    let (s, env_binding) = extract_env_binding(s);

    (None, s.to_string(), continuation.to_vec())
}

fn extract_env_binding(s: &str) -> (&str, Option<String>) {
    // Check if s ends with $$ or $VARNAME
    let s = s.trim();
    if let Some(dollar_pos) = s.rfind('$') {
        let env_part = &s[dollar_pos..];
        if env_part == "$$" {
            return (&s[..dollar_pos].trim_end(), Some("$$".to_string()));
        } else if env_part.starts_with('$') {
            let env_name = &env_part[1..];
            if env_name.chars().all(|c| c.is_alphanumeric() || c == '_') {
                return (&s[..dollar_pos].trim_end(), Some(env_name.to_string()));
            }
        }
    }
    (s, None)
}

fn build_describe(text: &str, continuation: &[String]) -> String {
    if continuation.is_empty() {
        text.trim().to_string()
    } else {
        let mut result = text.trim().to_string();
        for line in continuation {
            result.push('\n');
            result.push_str(line.trim());
        }
        result
    }
}

fn parse_flag_option(rest: &str, continuation: &[String], is_flag: bool) -> FlagOption {
    // Parse option/flag definition
    // Examples:
    // "-b --ob short"
    // "--oc! required"
    // "--od* multi-occurs"
    // "--oe+ required + multi-occurs"
    // "--of*, multi-occurs + comma-separated"
    // "--ona <PATH> value notation"
    // "--oda=a default"
    // "--oca[a|b] choice"
    // "-X-*[`_choice_fn`] prefixed"
    // "--follow:[a|b] assigned + choice"

    let rest = rest.trim();

    // Collect all parts up to the description
    // Parts are: optional short + long name + modifiers
    let (long_name, short_name, modifiers, rest_after) = parse_option_names_and_modifiers(rest, is_flag);

    let id = compute_option_id(&long_name);

    // Parse the rest for notations and description
    let (notations, num_args, multi_val, describe, describe_continuation, env_binding) = 
        parse_option_rest(&rest_after, continuation, is_flag, &modifiers);

    // Parse modifiers
    let (required, multiple_occurs, delimiter, terminated, assigned, prefixed) = 
        parse_option_modifiers_str(&modifiers);

    // Compute final num_args
    let (final_min, final_max) = if is_flag {
        (0usize, 0usize)
    } else {
        compute_num_args(&notations, num_args, multiple_occurs)
    };

    // Parse default and choice from the name part
    let (default_val, choice_val) = parse_option_default_and_choice(&modifiers);

    let actual_env = if let Some(env) = env_binding {
        if env == "$$" {
            // Use the option id (uppercase) as env name
            let name = long_name.as_deref().or(short_name.as_deref()).unwrap_or("");
            let stripped = strip_option_prefix(name);
            Some(stripped.to_uppercase().replace('-', "_"))
        } else {
            Some(env)
        }
    } else {
        None
    };

    // Handle sign prefix for plus options
    let sign = get_option_sign(&long_name);

    FlagOption {
        id,
        long_name,
        short_name,
        describe: build_describe(&describe, &describe_continuation),
        is_flag,
        notations,
        required,
        multiple_values: multi_val,
        multiple_occurs,
        num_args: (final_min, final_max),
        delimiter,
        terminated,
        prefixed,
        assigned,
        default: default_val,
        choice: choice_val,
        env: actual_env,
        inherited: false,
    }
}

fn get_option_sign(name: &Option<String>) -> &'static str {
    match name {
        Some(n) if n.starts_with('+') => "+",
        _ => "-",
    }
}

fn strip_option_prefix(name: &str) -> &str {
    if name.starts_with("--") {
        &name[2..]
    } else if name.starts_with('-') {
        &name[1..]
    } else if name.starts_with('+') {
        &name[1..]
    } else {
        name
    }
}

fn compute_option_id(long_name: &Option<String>) -> String {
    match long_name {
        Some(name) => {
            let stripped = if name.starts_with("--") {
                &name[2..]
            } else if name.starts_with('-') {
                &name[1..]
            } else if name.starts_with('+') {
                &name[1..]
            } else {
                name.as_str()
            };

            let base = if name.starts_with('+') {
                format!("plus_{}", stripped)
            } else {
                stripped.to_string()
            };

            base.replace('-', "_").replace('.', "_")
        }
        None => String::new(),
    }
}

fn parse_option_names_and_modifiers(s: &str, is_flag: bool) -> (Option<String>, Option<String>, String, String) {
    // Parse:  [-short] [long_name][modifiers] [description]
    // Also handle single-hyphen long names like: -fa, -fb
    // And plus-sign names: +oa, +b +ob

    let tokens: Vec<&str> = tokenize_option_line(s);

    let mut short: Option<String> = None;
    let mut long: Option<String> = None;
    let mut modifiers = String::new();
    let mut desc_start = 0;

    let mut i = 0;
    while i < tokens.len() {
        let token = tokens[i];

        if is_option_like(token) {
            // Extract name part and modifiers
            let (name, mods) = split_option_name_modifiers(token);

            if long.is_none() {
                // First option-like token could be long name
                if is_short_option(&name) && long.is_none() && short.is_none() {
                    // Could be short name if next is also an option
                    if i + 1 < tokens.len() && is_option_like_stripped(tokens[i+1]) {
                        short = Some(name);
                        modifiers = mods;
                    } else {
                        long = Some(name);
                        modifiers = mods;
                    }
                } else {
                    long = Some(name);
                    modifiers = mods;
                }
            } else if short.is_none() {
                // This is a short name
                short = Some(name);
                modifiers = mods;
            } else {
                desc_start = i;
                break;
            }
        } else {
            desc_start = i;
            break;
        }

        i += 1;
    }

    // Remaining tokens form the description
    let desc = tokens[desc_start..].join(" ");

    (long, short, modifiers, desc)
}

fn tokenize_option_line(s: &str) -> Vec<&str> {
    // Simple tokenization by whitespace, but keep together option names with their modifiers
    s.split_whitespace().collect()
}

fn is_option_like(s: &str) -> bool {
    let base = s.split(|c: char| !c.is_alphanumeric() && c != '-' && c != '_' && c != '+')
        .next().unwrap_or("");
    s.starts_with('-') || s.starts_with('+')
}

fn is_option_like_stripped(s: &str) -> bool {
    s.starts_with('-') || s.starts_with('+')
}

fn is_short_option(name: &str) -> bool {
    // A "short" option in argc terms:
    // - starts with - and has 1-2 chars: -a, -b
    // - starts with + and has 1-2 chars: +a, +b
    // But we need to distinguish - single char after single hyphen
    if name.starts_with("--") { return false; }
    if name.starts_with('-') {
        let rest = &name[1..];
        // Single char or plus char
        rest.chars().count() == 1
    } else if name.starts_with('+') {
        let rest = &name[1..];
        rest.chars().count() == 1
    } else {
        false
    }
}

fn split_option_name_modifiers(s: &str) -> (String, String) {
    // Given something like "--oc!" or "--od*" or "--oxa~" or "--of*,"
    // Split into ("--oc", "!")

    // Find where the name ends and modifiers begin
    // Name chars: alphanumeric, -, _, .
    // After prefix (-- or - or +), name continues until !, *, +, ~, =, [, :, ,

    let mut i = 0;
    let chars: Vec<char> = s.chars().collect();

    // Skip prefix
    if i < chars.len() && chars[i] == '-' {
        i += 1;
        if i < chars.len() && chars[i] == '-' {
            i += 1;
        }
    } else if i < chars.len() && chars[i] == '+' {
        i += 1;
    }

    // Skip name chars
    while i < chars.len() && (chars[i].is_alphanumeric() || chars[i] == '-' || chars[i] == '_' || chars[i] == '.') {
        i += 1;
    }

    let name: String = chars[..i].iter().collect();
    let modifiers: String = chars[i..].iter().collect();

    (name, modifiers)
}

fn parse_option_modifiers_str(mods: &str) -> (bool, bool, Option<char>, bool, bool, bool) {
    let mut required = false;
    let mut multiple_occurs = false;
    let mut delimiter: Option<char> = None;
    let mut terminated = false;
    let mut assigned = false;
    let mut prefixed = false;

    let mut i = 0;
    let chars: Vec<char> = mods.chars().collect();

    while i < chars.len() {
        match chars[i] {
            '!' => { required = true; i += 1; }
            '*' => { multiple_occurs = true; i += 1; }
            '+' if i == 0 || chars[i-1] != '-' => { 
                required = true; 
                multiple_occurs = true; 
                i += 1; 
            }
            '~' => { terminated = true; i += 1; }
            ',' => { delimiter = Some(','); i += 1; }
            ':' => { assigned = true; i += 1; }
            '-' if i == 0 => { prefixed = true; i += 1; }
            '=' => {
                // Default value - skip it  
                i += 1;
                if i < chars.len() && chars[i] == '`' {
                    i += 1;
                    while i < chars.len() && chars[i] != '`' { i += 1; }
                    i += 1;
                } else {
                    while i < chars.len() && chars[i] != '[' { i += 1; }
                }
            }
            '[' => {
                // Choice/default - skip to matching ]
                let mut depth = 1;
                i += 1;
                while i < chars.len() && depth > 0 {
                    if chars[i] == '[' { depth += 1; }
                    if chars[i] == ']' { depth -= 1; }
                    i += 1;
                }
            }
            _ => { i += 1; }
        }
    }

    (required, multiple_occurs, delimiter, terminated, assigned, prefixed)
}

fn parse_option_default_and_choice(mods: &str) -> (Option<DefaultValue>, Option<ChoiceValue>) {
    let mut default: Option<DefaultValue> = None;
    let mut choice: Option<ChoiceValue> = None;

    // Check for =value or =`fn`
    if let Some(eq_pos) = mods.find('=') {
        let val_part = &mods[eq_pos+1..];
        // But only if not inside [...]
        if !mods[..eq_pos].contains('[') {
            if val_part.starts_with('`') {
                let end = val_part[1..].find('`').map(|p| p + 2).unwrap_or(val_part.len());
                let fn_name = &val_part[1..end.min(val_part.len())-1];
                if !fn_name.is_empty() {
                    default = Some(DefaultValue::Fn(fn_name.to_string()));
                }
            } else {
                let val_end = val_part.find('[').unwrap_or(val_part.len());
                let val = val_part[..val_end].trim();
                if !val.is_empty() {
                    default = Some(DefaultValue::Value(val.to_string()));
                }
            }
        }
    }

    // Check for [choices] or [`fn`]
    if let Some(bracket_pos) = mods.find('[') {
        let bracket_part = &mods[bracket_pos..];
        choice = parse_choice_part(bracket_part);

        // If choice is Values with = prefix, extract default
        if let Some(ChoiceValue::Values(ref vals)) = choice {
            let inner_end = bracket_part.rfind(']').unwrap_or(bracket_part.len() - 1);
            let inner = &bracket_part[1..inner_end];
            if inner.starts_with('=') {
                // First value is the default
                if let Some(first) = vals.first() {
                    default = Some(DefaultValue::Value(first.clone()));
                }
            }
        }
    }

    (default, choice)
}

fn parse_option_rest(s: &str, continuation: &[String], is_flag: bool, mods: &str) -> (Vec<String>, Option<(usize, usize)>, bool, String, Vec<String>, Option<String>) {
    let s = s.trim();

    // Check for env binding at start
    let (s, env) = extract_leading_env_binding(s);

    // Parse notations like <FILE>, <FILE>..., <FILE+>
    let mut notations = Vec::new();
    let mut remaining = s.trim();
    let mut multi_val = false;
    let mut num_args_override: Option<(usize, usize)> = None;

    while remaining.starts_with('<') {
        if let Some(end) = remaining.find('>') {
            let notation = remaining[1..end].to_string();

            // Check for modifier in notation: VALUE* VALUE+ VALUE?
            if notation.ends_with('*') {
                notations.push(notation[..notation.len()-1].to_string());
                multi_val = true;
                // zero or more values
            } else if notation.ends_with('+') {
                notations.push(notation[..notation.len()-1].to_string());
                multi_val = true;
                // one or more required
            } else if notation.ends_with('?') {
                notations.push(notation[..notation.len()-1].to_string());
                // zero or one
            } else if notation.ends_with("...") {
                // ... is part of the name (e.g. FILE+)
                notations.push(notation.trim_end_matches("...").to_string() + "+");
                multi_val = true;
            } else {
                notations.push(notation);
            }
            remaining = remaining[end+1..].trim();
        } else {
            break;
        }
    }

    let describe = remaining.to_string();
    let desc_continuation = continuation.to_vec();

    (notations, num_args_override, multi_val, describe, desc_continuation, env)
}

fn extract_leading_env_binding(s: &str) -> (&str, Option<String>) {
    let s = s.trim();
    if s.starts_with("$$") {
        // Actually we look for $$ at the end  
    } else if s.starts_with('$') {
        // Could be $ENV binding
    }
    // Let's look for $$ or $ENV at the END
    extract_env_binding(s)
}

fn compute_num_args(notations: &[String], override_val: Option<(usize, usize)>, multi_occurs: bool) -> (usize, usize) {
    if let Some(ov) = override_val {
        return ov;
    }

    if notations.is_empty() {
        return (1, 1);
    }

    // Check last notation for + modifier
    let last = notations.last().unwrap();
    if last.ends_with('+') {
        // One or more
        return (notations.len(), 32767);
    }

    (notations.len(), notations.len())
}

fn parse_env_def(rest: &str, continuation: &[String]) -> EnvDef {
    let rest = rest.trim();

    // Parse: VARNAME[modifiers] description
    // Examples:
    // "TEST_EA optional"
    // "TEST_EB! required"
    // "TEST_EDA=a default"
    // "TEST_ECA[a|b] choice"

    let (name_part, rest_part) = split_name_and_rest(rest);
    let (id, required, _, _, _, default, choice) = parse_positional_modifiers(&name_part);

    let describe = build_describe(rest_part.trim(), &continuation.to_vec());

    EnvDef {
        id,
        describe,
        required,
        default,
        choice,
        inherited: false,
    }
}

fn parse_meta(rest: &str) -> MetaTag {
    let rest = rest.trim();
    let (name, value) = if let Some(pos) = rest.find(|c: char| c.is_whitespace()) {
        (&rest[..pos], rest[pos..].trim())
    } else {
        (rest, "")
    };
    MetaTag {
        name: name.to_string(),
        value: value.to_string(),
    }
}

fn process_metadata(cmd: &mut Command) {
    // Process @meta tags at root level
    let mut inherit_flag_options = false;
    let mut combine_shorts = false;
    let mut dotenv = false;
    let mut default_subcommand: Option<String> = None;

    for meta in &cmd.metadata {
        match meta.name.as_str() {
            "inherit-flag-options" => inherit_flag_options = true,
            "combine-shorts" => combine_shorts = true,
            "dotenv" => dotenv = true,
            "version" => {
                cmd.version = Some(meta.value.clone());
            }
            _ => {}
        }
    }

    if inherit_flag_options {
        // Copy root flags/options to all subcommands
        let root_flags = cmd.flags_options.clone();
        for sub in &mut cmd.subcommands {
            let mut inherited: Vec<FlagOption> = root_flags.iter().map(|f| {
                let mut f = f.clone();
                f.inherited = true;
                f
            }).collect();
            // Don't add if already present
            for f in &sub.flags_options {
                inherited.retain(|i| i.id != f.id);
            }
            sub.flags_options = inherited.into_iter().chain(sub.flags_options.drain(..)).collect();
        }
    }
}

fn add_builtin_flags(cmd: &mut Command) {
    // Determine the sign used (- or +)
    let uses_plus = cmd.flags_options.iter().any(|f| {
        f.long_name.as_deref().map(|n| n.starts_with('+')).unwrap_or(false)
    });

    let uses_single_hyphen = !cmd.flags_options.is_empty() && 
        cmd.flags_options.iter().all(|f| {
            let ln = f.long_name.as_deref().unwrap_or("");
            !ln.starts_with("--")
        });

    // Build help flag
    let help_flag = make_help_flag(uses_single_hyphen, uses_plus, &cmd.subcommands, cmd);
    let has_help = cmd.flags_options.iter().any(|f| f.id == "help");
    if !has_help {
        cmd.flags_options.push(help_flag);
    }

    // Build version flag (only for root command or if has @meta version)
    let has_version = cmd.flags_options.iter().any(|f| f.id == "version");
    if !has_version && !cmd.is_subcommand {
        let version_flag = make_version_flag();
        cmd.flags_options.push(version_flag);
    }

    // Process subcommands recursively
    for sub in &mut cmd.subcommands {
        add_builtin_flags(sub);
    }
}

fn make_help_flag(single_hyphen: bool, plus: bool, subcommands: &[Command], cmd: &Command) -> FlagOption {
    let (long_name, short_name, describe) = if single_hyphen {
        (Some("-help".to_string()), Some("-h".to_string()), if !subcommands.is_empty() { "" } else { "" }.to_string())
    } else if plus {
        (Some("-help".to_string()), Some("-h".to_string()), "Print help".to_string())
    } else {
        (Some("--help".to_string()), Some("-h".to_string()), 
            if !cmd.flags_options.is_empty() || !cmd.positionals.is_empty() || !subcommands.is_empty() {
                "Print help".to_string()
            } else {
                String::new()
            })
    };

    FlagOption {
        id: "help".to_string(),
        long_name,
        short_name,
        describe,
        is_flag: true,
        notations: vec![],
        required: false,
        multiple_values: false,
        multiple_occurs: false,
        num_args: (0, 0),
        delimiter: None,
        terminated: false,
        prefixed: false,
        assigned: false,
        default: None,
        choice: None,
        env: None,
        inherited: false,
    }
}

fn make_version_flag() -> FlagOption {
    FlagOption {
        id: "version".to_string(),
        long_name: Some("--version".to_string()),
        short_name: Some("-V".to_string()),
        describe: String::new(),
        is_flag: true,
        notations: vec![],
        required: false,
        multiple_values: false,
        multiple_occurs: false,
        num_args: (0, 0),
        delimiter: None,
        terminated: false,
        prefixed: false,
        assigned: false,
        default: None,
        choice: None,
        env: None,
        inherited: false,
    }
}
