// Command data structures for argc

#[derive(Debug, Clone)]
pub struct Command {
    pub name: String,
    pub describe: String,
    pub version: Option<String>,
    pub aliases: Vec<String>,
    pub flag_options: Vec<FlagOption>,
    pub positionals: Vec<Positional>,
    pub envs: Vec<EnvDef>,
    pub subcommands: Vec<Command>,
    pub metadata: MetaData,
    pub command_fn: Option<String>,
}

#[derive(Debug, Clone, Default)]
pub struct MetaData {
    pub inherit_flag_options: bool,
    pub combine_shorts: bool,
    pub dotenv: Option<String>,  // None = no dotenv, Some("") = default .env, Some("file") = specific file
    pub require_tools: Vec<String>,
    pub default_subcommand: Option<String>,
    pub symbol: Option<String>,
    pub version: Option<String>,
    pub raw: Vec<(String, String)>,  // Raw metadata entries
}

#[derive(Debug, Clone)]
pub struct FlagOption {
    pub id: String,
    pub long_name: Option<String>,
    pub short_name: Option<String>,
    pub describe: String,
    pub is_flag: bool,
    pub notations: Vec<String>,
    pub required: bool,
    pub multiple_values: bool,
    pub multiple_occurs: bool,
    pub num_args: (usize, usize),
    pub delimiter: Option<char>,
    pub terminated: bool,
    pub prefixed: bool,
    pub assigned: bool,
    pub default: Option<DefaultValue>,
    pub choice: Option<ChoiceValue>,
    pub env: Option<String>,
    pub inherited: bool,
}

#[derive(Debug, Clone)]
pub struct Positional {
    pub id: String,
    pub notation: String,
    pub describe: String,
    pub required: bool,
    pub multiple: bool,
    pub delimiter: Option<char>,
    pub terminated: bool,
    pub default: Option<DefaultValue>,
    pub choice: Option<ChoiceValue>,
    pub env: Option<String>,
}

#[derive(Debug, Clone)]
pub struct EnvDef {
    pub id: String,
    pub describe: String,
    pub required: bool,
    pub default: Option<DefaultValue>,
    pub choice: Option<ChoiceValue>,
    pub inherited: bool,
}

#[derive(Debug, Clone, PartialEq)]
pub enum DefaultValue {
    Value(String),
    Fn(String),
}

#[derive(Debug, Clone)]
pub enum ChoiceValue {
    Values(Vec<String>),
    Fn(String, bool),  // (fn_name, validate)
}

impl Command {
    pub fn new(name: &str) -> Self {
        Command {
            name: name.to_string(),
            describe: String::new(),
            version: None,
            aliases: vec![],
            flag_options: vec![],
            positionals: vec![],
            envs: vec![],
            subcommands: vec![],
            metadata: MetaData::default(),
            command_fn: None,
        }
    }

    /// Find a subcommand by name (including aliases)
    pub fn find_subcommand(&self, name: &str) -> Option<&Command> {
        self.subcommands.iter().find(|cmd| {
            cmd.name == name || cmd.aliases.iter().any(|a| a == name)
        })
    }

    /// Get the main sign used for options (- or +)  
    pub fn option_sign(&self) -> &'static str {
        for fo in &self.flag_options {
            if let Some(ln) = &fo.long_name {
                if ln.starts_with('+') {
                    return "+";
                }
            }
        }
        "-"
    }

    /// Check if this command uses single-hyphen long names (like -fa instead of --fa)
    pub fn uses_single_hyphen(&self) -> bool {
        let user_fos: Vec<_> = self.flag_options.iter()
            .filter(|fo| !matches!(fo.id.as_str(), "help" | "version"))
            .collect();
        if user_fos.is_empty() { return false; }
        user_fos.iter().all(|fo| {
            let ln = fo.long_name.as_deref().unwrap_or("");
            !ln.starts_with("--") && !ln.starts_with('+')
        })
    }

    /// Check if any user-defined flag/option has a describe (for help text)
    pub fn any_user_option_has_describe(&self) -> bool {
        self.flag_options.iter()
            .filter(|fo| !matches!(fo.id.as_str(), "help" | "version"))
            .any(|fo| !fo.describe.is_empty())
        || self.positionals.iter().any(|p| !p.describe.is_empty())
        || self.envs.iter().any(|e| !e.describe.is_empty())
    }

    /// Get variable name for a flag/option
    pub fn var_name(id: &str) -> String {
        format!("argc_{}", id.replace('-', "_").replace('.', "_"))
    }

    /// Get variable name for positional
    pub fn pos_var_name(id: &str) -> String {
        // Replace non-alphanumeric with _ but handle "..."
        let result = id.replace("...", "___")
            .replace('-', "_")
            .replace('.', "_");
        format!("argc_{}", result)
    }

    /// Check if command has a "main" function (no subcommands or has both)
    pub fn has_main_fn(&self) -> bool {
        // A command has a "main" function if it doesn't require subcommands
        // i.e., it can run without a subcommand
        self.command_fn.as_deref() == Some("main") ||
        (self.subcommands.is_empty() && self.command_fn.is_some())
    }
}

impl FlagOption {
    /// Get the "render name" for error messages
    pub fn render_name(&self) -> String {
        if let Some(ln) = &self.long_name {
            if self.is_flag || self.notations.is_empty() {
                ln.clone()
            } else {
                let notation = if self.multiple_occurs || self.num_args.1 > 1 {
                    let n = if self.assigned {
                        format!("=<{}>", self.notations.first().unwrap_or(&"VALUE".to_string()))
                    } else if self.num_args.1 >= 32767 {
                        format!(" <{}~>", self.notations.first().unwrap_or(&"VALUE".to_string()))
                    } else if self.notations.len() == 1 {
                        let suffix = if self.required { "..." } else { "..." };
                        format!(" <{}{}>", self.notations[0], if self.required { "..." } else { "..." })
                    } else {
                        format!(" {}", self.notations.iter().map(|n| format!("<{}>", n)).collect::<Vec<_>>().join(" "))
                    };
                    notation
                } else {
                    format!(" <{}>", self.notations.first().unwrap_or(&"VALUE".to_string()))
                };
                format!("{}{}", ln, notation)
            }
        } else {
            String::new()
        }
    }

    /// Get the sign prefix (- or +)
    pub fn sign(&self) -> &'static str {
        match self.long_name.as_deref() {
            Some(n) if n.starts_with('+') => "+",
            _ => "-",
        }
    }
}
