                        format!("=<{}>", self.notations.first().unwrap_or(&"VALUE".to_string()))
                    } else if self.num_args.1 >= 32767 {
                        format!(" <{}~>", self.notations.first().unwrap_or(&"VALUE".to_string()))
                    } else if self.notations.len() == 1 {
                        let suffix = if self.required { "..." } else { "..." };
                        format!(" <{}{}>", self.notations[0], if self.required { "..." } else { "..." })
                    } else {
                        format!(" {}", self.notations.iter().map(|n| format!("<{}>", n)).collect::<Vec<_>>().join(" "))
                    };
                    notation
                } else {
                    format!(" <{}>", self.notations.first().unwrap_or(&"VALUE".to_string()))
                };
                format!("{}{}", ln, notation)
            }
        } else {
            String::new()
        }
    }

    /// Get the sign prefix (- or +)
    pub fn sign(&self) -> &'static str {
        match self.long_name.as_deref() {
            Some(n) if n.starts_with('+') => "+",
            _ => "-",
        }
    }
}
