                }
                "cmd" => {
                    // Save current pending command
                    if let Some(cc) = current_pending.take() {
                        if let Some(cmd) = build_subcommand(cc) {
                            root.subcommands.push(cmd);
                        }
                    }
                    let mut new_pending = PendingCommand::new();
                    new_pending.describe = tag_rest.trim().to_string();
                    new_pending.long_describe = continuation.join("\n");
                    current_pending = Some(new_pending);
                }
                "alias" => {
                    let aliases: Vec<String> = tag_rest.split_whitespace()
                        .map(|s| s.to_string())
                        .collect();
                    if let Some(ref mut cc) = current_pending {
                        cc.aliases.extend(aliases);
                    }
                }
                "arg" => {
                    let pos = parse_positional_line(tag_rest, &continuation);
                    if let Some(ref mut cc) = current_pending {
                        cc.positionals.push(pos);
                    } else {
                        root_pending.positionals.push(pos);
                    }
                }
                "option" => {
                    let fo = parse_option_line(tag_rest, &continuation, false);
                    if let Some(ref mut cc) = current_pending {
                        cc.flag_options.push(fo);
                    } else {
                        root_pending.flag_options.push(fo);
                    }
                }
                "flag" => {
                    let fo = parse_option_line(tag_rest, &continuation, true);
                    if let Some(ref mut cc) = current_pending {
                        cc.flag_options.push(fo);
                    } else {
                        root_pending.flag_options.push(fo);
                    }
                }
                "env" => {
                    let env = parse_env_line(tag_rest, &continuation);
                    if let Some(ref mut cc) = current_pending {
                        cc.envs.push(env);
                    } else {
                        root_pending.envs.push(env);
                    }
                }
                "meta" => {
                    let (meta_name, meta_val) = split_meta(tag_rest);
                    if let Some(ref mut cc) = current_pending {
                        apply_meta_to_pending(cc, meta_name, meta_val);
                    } else {
                        apply_meta_to_root_pending(&mut root_pending, meta_name, meta_val);
                    }
                }
                _ => {}
            }
        } else if !trimmed.is_empty() && !trimmed.starts_with('#') {
            // Non-comment, non-empty line - check for function definition
            if let Some(fn_name) = extract_function_name(trimmed) {
                if let Some(ref mut cc) = current_pending {
                    if cc.fn_name.is_none() {
                        cc.fn_name = Some(fn_name);
                    }
                } else if root.command_fn.is_none() {
                    // This is the "main" function or root command function
                    if fn_name == "main" || fn_name == "_argc_before" || fn_name == "_argc_after" {
                        if fn_name == "main" {
                            root.command_fn = Some(fn_name);
                        }
                    } else if !fn_name.starts_with('_') {
                        // Could be main function for root command
                        // But only if it's not a subcommand function
                        // We need to check - if we haven't seen any @cmd yet and this is a non-underscore function
                        // we don't set it here because it might be any function
                    }
                }
            }
        }

        i += 1;
    }

    // Save last pending command
    if let Some(cc) = current_pending {
        if let Some(cmd) = build_subcommand(cc) {
            root.subcommands.push(cmd);
        }
    }

    // Apply root pending to root command
    root.describe = root_pending.describe;
    if !root_pending.long_describe.is_empty() {
        if !root.describe.is_empty() {
            root.describe = format!("{}\n\n{}", root.describe, root_pending.long_describe);
        } else {
            root.describe = root_pending.long_describe;
        }
    }
    root.flag_options = root_pending.flag_options;
    root.positionals = root_pending.positionals;
    root.envs = root_pending.envs;
    root.metadata = root_pending.metadata;

    // Extract version from metadata
    if let Some(v) = &root.metadata.version {
        root.version = Some(v.clone());
    }

    // Handle nested subcommands (:: separator)
    organize_nested_commands(&mut root);

    // Apply metadata effects
    apply_metadata(&mut root);

    // Add automatic aliases (underscore -> hyphen)
    add_auto_aliases(&mut root);

    // Add builtin flags (help, version)
    add_builtin_flags(&mut root);

    root
}

fn organize_nested_commands(root: &mut Command) {
    // Move commands with :: in their fn_name to nested positions
    // e.g., "builder::ls" should be under "builder" subcommand

    let mut to_remove = Vec::new();
    let mut nested_cmds: Vec<(Vec<String>, Command)> = Vec::new();

    for (idx, cmd) in root.subcommands.iter().enumerate() {
        if let Some(fn_name) = &cmd.command_fn {
            let parts: Vec<&str> = fn_name.split("::").collect();
            if parts.len() > 1 {
                // This is a nested command
                let path: Vec<String> = parts[..parts.len()-1].iter().map(|s| s.to_string()).collect();
                to_remove.push(idx);
                nested_cmds.push((path, cmd.clone()));
            }
        }
    }

    // Remove nested commands from root (in reverse order)
    for idx in to_remove.iter().rev() {
        root.subcommands.remove(*idx);
    }

    // Insert them into the right place
    for (path, mut cmd) in nested_cmds {
        // cmd.name is the last part of the path
        let last_part = path.last().unwrap();
        let parent_path = &path[..path.len()-1];

        // Find the cmd name from the fn_name
        if let Some(fn_name) = &cmd.command_fn {
            let parts: Vec<&str> = fn_name.split("::").collect();
            let cmd_part = parts.last().unwrap();
            cmd.name = cmd_part.to_string();
        }

        // Find parent in root or nested
        if parent_path.is_empty() {
            // This shouldn't happen since we checked parts.len() > 1
        } else if parent_path.len() == 1 {
            // Direct child of root
            let parent_name = parent_path[0].as_str();
            if let Some(parent) = root.subcommands.iter_mut().find(|c| c.command_fn.as_deref() == Some(parent_name)) {
                parent.subcommands.push(cmd);
            } else {
                // Error: parent not found
                // This will be caught later
                eprintln!("Error: {}(line ?) lack of parent command", 
                    cmd.command_fn.as_deref().unwrap_or(""));
            }
        } else {
            // Deeper nesting
            find_and_insert(root, parent_path, cmd);
        }
    }
}

fn find_and_insert(parent: &mut Command, path: &[String], cmd: Command) {
    if path.is_empty() {
        parent.subcommands.push(cmd);
        return;
    }
    let target_fn = &path[0];
    if let Some(child) = parent.subcommands.iter_mut().find(|c| c.command_fn.as_deref() == Some(target_fn.as_str())) {
        find_and_insert(child, &path[1..], cmd);
    } else {
        // Error
        eprintln!("error: {}(?) lack of parent command", 
            cmd.command_fn.as_deref().unwrap_or(""));
    }
}

fn apply_metadata(root: &mut Command) {
    // inherit-flag-options: copy root flags/options to all subcommands
    if root.metadata.inherit_flag_options {
        let root_flags = root.flag_options.clone();
        inherit_flags_to_subcommands(&mut root.subcommands, &root_flags);
    }

    // combine-shorts is inherited by subcommands
    if root.metadata.combine_shorts {
        set_combine_shorts_recursive(&mut root.subcommands);
    }
}

fn inherit_flags_to_subcommands(subcommands: &mut Vec<Command>, flags: &[FlagOption]) {
    for sub in subcommands.iter_mut() {
        // Add inherited flags that aren't already present
        let mut to_prepend: Vec<FlagOption> = Vec::new();
        for flag in flags {
            // Don't inherit help/version
            if matches!(flag.id.as_str(), "help" | "version") {
                continue;
            }
            // Don't add if already defined in subcommand
            if !sub.flag_options.iter().any(|f| f.id == flag.id) {
                let mut inherited = flag.clone();
                inherited.inherited = true;
                to_prepend.push(inherited);
            }
        }
        // Prepend inherited flags to subcommand's flags  
        let existing = std::mem::replace(&mut sub.flag_options, to_prepend);
        sub.flag_options.extend(existing);

        // Recurse into sub-subcommands
        inherit_flags_to_subcommands(&mut sub.subcommands, flags);
    }
}

fn set_combine_shorts_recursive(subcommands: &mut Vec<Command>) {
    for sub in subcommands.iter_mut() {
        sub.metadata.combine_shorts = true;
        set_combine_shorts_recursive(&mut sub.subcommands);
    }
}

fn add_auto_aliases(cmd: &mut Command) {
    for sub in &mut cmd.subcommands {
        // Auto-alias: if name contains underscore, add hyphenated version
        let hyphenated = sub.name.replace('_', "-");
        if hyphenated != sub.name && !sub.aliases.contains(&hyphenated) {
            sub.aliases.push(hyphenated);
        }
        add_auto_aliases(sub);
    }
}

fn add_builtin_flags(cmd: &mut Command) {
    // Determine what style to use for help flag based on existing options
    let uses_single_hyphen = cmd.uses_single_hyphen_long();
    let uses_plus = cmd.uses_plus_options();

    let any_has_describe = cmd.flag_options.iter()
        .filter(|fo| !matches!(fo.id.as_str(), "help" | "version"))
        .any(|fo| !fo.describe.is_empty())
        || cmd.positionals.iter().any(|p| !p.describe.is_empty())
        || cmd.envs.iter().any(|e| !e.describe.is_empty());

    let help_describe = if any_has_describe { "Print help".to_string() } else { String::new() };
    let version_describe = if any_has_describe { "Print version".to_string() } else { String::new() };

    // Build help flag
    let (help_long, help_short) = if uses_single_hyphen || uses_plus {
        (Some("-help".to_string()), Some("-h".to_string()))
    } else {
        (Some("--help".to_string()), Some("-h".to_string()))
    };

    if !cmd.flag_options.iter().any(|f| f.id == "help") {
        cmd.flag_options.push(FlagOption {
            id: "help".to_string(),
            long_name: help_long,
            short_name: help_short,
            describe: help_describe,
            is_flag: true,
            notations: vec![],
            required: false,
            multiple_values: false,
            multiple_occurs: false,
            num_args: (0, 0),
            delimiter: None,
            terminated: false,
            prefixed: false,
            assigned: false,
            default: None,
            choice: None,
            env: None,
            inherited: false,
        });
    }

    // Version flag (only for root command)
    if !cmd.flag_options.iter().any(|f| f.id == "version") {
        cmd.flag_options.push(FlagOption {
            id: "version".to_string(),
            long_name: Some("--version".to_string()),
            short_name: Some("-V".to_string()),
            describe: version_describe,
            is_flag: true,
            notations: vec![],
            required: false,
            multiple_values: false,
            multiple_occurs: false,
            num_args: (0, 0),
            delimiter: None,
            terminated: false,
            prefixed: false,
            assigned: false,
            default: None,
            choice: None,
            env: None,
            inherited: false,
        });
    }

    // Process subcommands
    for sub in &mut cmd.subcommands {
        add_builtin_flags_sub(sub);
    }
}

fn add_builtin_flags_sub(cmd: &mut Command) {
    let uses_single_hyphen = cmd.uses_single_hyphen_long();
    let uses_plus = cmd.uses_plus_options();

    let any_has_describe = cmd.flag_options.iter()
        .filter(|fo| !matches!(fo.id.as_str(), "help" | "version"))
        .any(|fo| !fo.describe.is_empty())
        || cmd.positionals.iter().any(|p| !p.describe.is_empty())
        || cmd.envs.iter().any(|e| !e.describe.is_empty());

    let help_describe = if any_has_describe { "Print help".to_string() } else { String::new() };

    let (help_long, help_short) = if uses_single_hyphen || uses_plus {
        (Some("-help".to_string()), Some("-h".to_string()))
    } else {
        (Some("--help".to_string()), Some("-h".to_string()))
    };

    if !cmd.flag_options.iter().any(|f| f.id == "help") {
        cmd.flag_options.push(FlagOption {
            id: "help".to_string(),
            long_name: help_long,
            short_name: help_short,
            describe: help_describe,
            is_flag: true,
            notations: vec![],
            required: false,
            multiple_values: false,
            multiple_occurs: false,
            num_args: (0, 0),
            delimiter: None,
            terminated: false,
            prefixed: false,
            assigned: false,
            default: None,
            choice: None,
            env: None,
            inherited: false,
        });
    }

    for sub in &mut cmd.subcommands {
        add_builtin_flags_sub(sub);
    }
}

impl Command {
    fn uses_single_hyphen_long(&self) -> bool {
        let user_fos: Vec<_> = self.flag_options.iter()
            .filter(|fo| !matches!(fo.id.as_str(), "help" | "version"))
            .collect();
        if user_fos.is_empty() { return false; }
        let any_with_ln = user_fos.iter().any(|fo| fo.long_name.is_some());
        if !any_with_ln { return false; }
        user_fos.iter().filter(|fo| fo.long_name.is_some()).all(|fo| {
            let ln = fo.long_name.as_deref().unwrap_or("");
            !ln.starts_with("--") && !ln.starts_with('+')
        })
    }

    fn uses_plus_options(&self) -> bool {
        let user_fos: Vec<_> = self.flag_options.iter()
            .filter(|fo| !matches!(fo.id.as_str(), "help" | "version"))
            .collect();
        if user_fos.is_empty() { return false; }
        let any_with_ln = user_fos.iter().any(|fo| fo.long_name.is_some());
        if !any_with_ln { return false; }
        // If ALL long names start with + and none with -, uses plus
        // But if mixed, don't set plus mode
        let plus_count = user_fos.iter().filter(|fo| {
            fo.long_name.as_deref().map(|n| n.starts_with('+')).unwrap_or(false)
        }).count();
        let minus_count = user_fos.iter().filter(|fo| {
            fo.long_name.as_deref().map(|n| n.starts_with('-')).unwrap_or(false)
        }).count();
        plus_count > 0 && minus_count == 0
    }
}

// Helper structs for building commands
struct PendingCommand {
    describe: String,
    long_describe: String,
    aliases: Vec<String>,
    flag_options: Vec<FlagOption>,
    positionals: Vec<Positional>,
    envs: Vec<EnvDef>,
    metadata: MetaData,
    fn_name: Option<String>,
}

impl PendingCommand {
    fn new() -> Self {
        PendingCommand {
            describe: String::new(),
            long_describe: String::new(),
            aliases: vec![],
            flag_options: vec![],
            positionals: vec![],
            envs: vec![],
            metadata: MetaData::default(),
            fn_name: None,
        }
    }
}

fn build_subcommand(pending: PendingCommand) -> Option<Command> {
    let fn_name = pending.fn_name.as_deref()?;

    // Get command name from function name (last part after ::)
    let parts: Vec<&str> = fn_name.split("::").collect();
    let cmd_name = parts.last().unwrap_or(&fn_name);

    let full_describe = if !pending.long_describe.is_empty() {
        if !pending.describe.is_empty() {
            format!("{}\n\n{}", pending.describe, pending.long_describe)
        } else {
            pending.long_describe
        }
    } else {
        pending.describe
    };

    let mut cmd = Command {
        name: cmd_name.to_string(),
        describe: full_describe,
        version: None,
        aliases: pending.aliases,
        flag_options: pending.flag_options,
        positionals: pending.positionals,
        envs: pending.envs,
        subcommands: vec![],
        metadata: pending.metadata,
        command_fn: Some(fn_name.to_string()),
    };

    Some(cmd)
}

fn extract_tag_line(line: &str) -> Option<&str> {
    // Line starts with "# @tag"
    let line = line.trim();
    if line.starts_with("# @") {
        Some(line[2..].trim_start())  // Return "@tag rest..."
    } else {
        None
    }
}

fn is_continuation_line(line: &str) -> Option<&str> {
    // A continuation line is a comment that doesn't start with @
    let line = line.trim();
    if line == "#" {
        return Some("");
    }
    if line.starts_with("# ") {
        let content = &line[2..];
        if !content.trim_start().starts_with('@') {
            return Some(content);
        }
    }
    None
}

fn split_tag_name(s: &str) -> (&str, &str) {
    // s looks like "@tag rest" or "@tag"
    let s = s.trim_start_matches('@');
    if let Some(pos) = s.find(|c: char| c.is_whitespace()) {
        (&s[..pos], &s[pos..])
    } else {
        (s, "")
    }
}

fn split_meta(s: &str) -> (&str, &str) {
    let s = s.trim();
    if let Some(pos) = s.find(|c: char| c.is_whitespace()) {
        (&s[..pos], s[pos..].trim())
    } else {
        (s, "")
    }
}

fn apply_meta_to_pending(pending: &mut PendingCommand, name: &str, value: &str) {
    pending.metadata.raw.push((name.to_string(), value.to_string()));
    match name {
        "default-subcommand" => {
            pending.metadata.default_subcommand = Some(String::new());
        }
        "require-tools" => {
            let tools: Vec<String> = value.split(',')
                .map(|s| s.trim().to_string())
                .filter(|s| !s.is_empty())
                .collect();
            pending.metadata.require_tools.extend(tools);
        }
        _ => {}
    }
}

fn apply_meta_to_root_pending(pending: &mut PendingCommand, name: &str, value: &str) {
    pending.metadata.raw.push((name.to_string(), value.to_string()));
    match name {
        "inherit-flag-options" => {
            pending.metadata.inherit_flag_options = true;
        }
        "combine-shorts" => {
            pending.metadata.combine_shorts = true;
        }
        "dotenv" => {
            pending.metadata.dotenv = if value.is_empty() {
                Some(String::new())  // Default .env
            } else {
                Some(value.to_string())
            };
        }
        "version" => {
            pending.metadata.version = Some(value.to_string());
        }
        "require-tools" => {
            let tools: Vec<String> = value.split(',')
                .map(|s| s.trim().to_string())
                .filter(|s| !s.is_empty())
                .collect();
            pending.metadata.require_tools.extend(tools);
        }
        "symbol" => {
            pending.metadata.symbol = Some(value.to_string());
        }
        _ => {}
    }
}

pub fn extract_function_name(line: &str) -> Option<String> {
    let line = line.trim();

    // Pattern 1: "funcname()" at start
    if let Some(paren_pos) = line.find('(') {
        let name_part = line[..paren_pos].trim();
        if !name_part.is_empty() && is_valid_fn_name(name_part) {
            let after = line[paren_pos..].trim_start_matches('(').trim();
            if after.starts_with(')') || after.starts_with(" )") || after.is_empty() {
                return Some(name_part.to_string());
            }
        }
    }

    None
}

fn is_valid_fn_name(s: &str) -> bool {
    if s.is_empty() { return false; }
    // Function names can contain alphanumeric, _, -, and :: (for nested)
    s.chars().all(|c| c.is_alphanumeric() || c == '_' || c == '-' || c == ':')
        && !s.starts_with('-')
        && !s.starts_with(':')
}

// Parse @arg line
fn parse_positional_line(rest: &str, continuation: &[String]) -> Positional {
    let rest = rest.trim();

    // Tokenize: name_with_modifiers [env_binding] [notation] [description]
    let (name_modifiers, after_name) = extract_pos_name_modifiers(rest);

    // Parse env binding and notation from after_name
    let (notation_override, env_binding, describe_text) = parse_pos_after_name(&after_name, continuation);

    // Parse name modifiers
    let (id, required, multiple, terminated, delimiter, default_val, choice_val) = 
        parse_name_modifiers_full(&name_modifiers);

    // Determine env var name
    let env = if let Some(eb) = env_binding {
        if eb == "$$" {
            Some(id.to_uppercase().replace('-', "_").replace('.', "_"))
        } else {
            Some(eb)
        }
    } else {
        None
    };

    let notation = if let Some(n) = notation_override {
        n
    } else {
        // Generate notation from id
        id.to_uppercase().replace("___", "...")
    };

    let describe = combine_describe(&describe_text, continuation);

    Positional {
        id,
        notation,
        describe,
        required,
        multiple,
        delimiter,
        terminated,
        default: default_val,
        choice: choice_val,
        env,
    }
}

fn extract_pos_name_modifiers(s: &str) -> (String, String) {
    // Extract the name+modifiers part up to first whitespace (ignoring brackets/backticks)
    let mut i = 0;
    let chars: Vec<char> = s.chars().collect();
    let len = chars.len();

    // Skip alphanumeric name chars
    while i < len && (chars[i].is_alphanumeric() || chars[i] == '_' || chars[i] == '-' || chars[i] == '.') {
        i += 1;
    }

    // Skip modifiers: !, *, +, ~, comma, =..., [...]
    while i < len {
        match chars[i] {
            '!' | '*' | '+' | '~' | ',' => { i += 1; }
            '=' => {
                i += 1;
                if i < len && chars[i] == '`' {
                    i += 1;
                    while i < len && chars[i] != '`' { i += 1; }
                    if i < len { i += 1; }
                } else {
                    while i < len && chars[i] != '[' && chars[i] != ' ' && chars[i] != '\t' {
                        i += 1;
                    }
                }
            }
            '[' => {
                let mut depth = 1;
                i += 1;
                while i < len && depth > 0 {
                    if chars[i] == '[' { depth += 1; }
                    if chars[i] == ']' { depth -= 1; }
                    i += 1;
                }
            }
            '$' => {
                // Env binding
                i += 1;
                if i < len && chars[i] == '$' {
                    i += 1;
                } else {
                    while i < len && (chars[i].is_alphanumeric() || chars[i] == '_') {
                        i += 1;
                    }
                }
            }
            _ => break,
        }
    }

    let name_part: String = chars[..i].iter().collect();
    let rest: String = chars[i..].iter().collect();
    (name_part.trim().to_string(), rest.trim().to_string())
}

fn parse_pos_after_name(s: &str, _continuation: &[String]) -> (Option<String>, Option<String>, String) {
    let s = s.trim();
    let mut notation = None;
    let mut env = None;
    let mut desc_start = s;

    // Check for $$ or $ENV before <NOTATION>
    let mut remaining = s;

    // Could be: "$$ <NOTATION> description" or "<NOTATION> description" or "$ENV description" or "description"
    if remaining.starts_with("$$") {
        env = Some("$$".to_string());
        remaining = remaining[2..].trim();
    } else if remaining.starts_with('$') {
        let end = remaining[1..].find(|c: char| !c.is_alphanumeric() && c != '_')
            .map(|p| p + 1)
            .unwrap_or(remaining.len());
        env = Some(remaining[1..end].to_string());
        remaining = remaining[end..].trim();
    }

    // Check for <NOTATION>
    if remaining.starts_with('<') {
        if let Some(end) = remaining.find('>') {
            notation = Some(remaining[1..end].to_string());
            remaining = remaining[end+1..].trim();
        }
    }

    // Check for env after notation
    if env.is_none() {
        if remaining.starts_with("$$") {
            env = Some("$$".to_string());
            remaining = remaining[2..].trim();
        } else if remaining.starts_with('$') {
            let end = remaining[1..].find(|c: char| !c.is_alphanumeric() && c != '_')
                .map(|p| p + 1)
                .unwrap_or(remaining.len());
            env = Some(remaining[1..end].to_string());
            remaining = remaining[end..].trim();
        }
    }

    (notation, env, remaining.to_string())
}

fn parse_name_modifiers_full(s: &str) -> (String, bool, bool, bool, Option<char>, Option<DefaultValue>, Option<ChoiceValue>) {
    // Parse: name[!|*|+|~][,][=val][=`fn`][choices]
    let mut i = 0;
    let chars: Vec<char> = s.chars().collect();
    let len = chars.len();

    // Extract name
    let name_start = i;
    while i < len && (chars[i].is_alphanumeric() || chars[i] == '_' || chars[i] == '-' || chars[i] == '.') {
        i += 1;
    }
    let name = chars[name_start..i].iter().collect::<String>();

    let mut required = false;
    let mut multiple = false;
    let mut terminated = false;
    let mut delimiter: Option<char> = None;
    let mut default_val: Option<DefaultValue> = None;
    let mut choice_val: Option<ChoiceValue> = None;

    // Skip env binding prefix if present
    // Parse modifiers
    while i < len {
        match chars[i] {
            '!' => { required = true; i += 1; }
            '*' => { multiple = true; i += 1; }
            '+' => { required = true; multiple = true; i += 1; }
            '~' => { terminated = true; multiple = true; i += 1; }
            ',' => { delimiter = Some(','); i += 1; }
            '=' => {
                i += 1;
                if i < len && chars[i] == '`' {
                    // Function default
                    i += 1;
                    let fn_start = i;
                    while i < len && chars[i] != '`' { i += 1; }
                    let fn_name: String = chars[fn_start..i].iter().collect();
                    if i < len { i += 1; }
                    default_val = Some(DefaultValue::Fn(fn_name));
                } else {
                    // Value default
                    let val_start = i;
                    while i < len && chars[i] != '[' && chars[i] != '$' {
                        i += 1;
                    }
                    let val: String = chars[val_start..i].iter().collect();
                    if !val.is_empty() {
                        default_val = Some(DefaultValue::Value(val));
                    }
                }
            }
            '[' => {
                // Choices
                let bracket_start = i;
                let mut depth = 1;
                i += 1;
                while i < len && depth > 0 {
                    if chars[i] == '[' { depth += 1; }
                    if chars[i] == ']' { depth -= 1; }
                    i += 1;
                }
                let bracket: String = chars[bracket_start..i].iter().collect();
                choice_val = parse_choice_bracket(&bracket);

                // If choice has = default, extract it
                if let Some(ChoiceValue::Values(ref vals)) = choice_val {
                    let inner = &bracket[1..bracket.len()-1];
                    if inner.starts_with('=') && default_val.is_none() {
                        if let Some(first) = vals.first() {
                            default_val = Some(DefaultValue::Value(first.clone()));
                        }
                    }
                }
            }
            '$' => {
                // Env binding - skip
                i += 1;
                if i < len && chars[i] == '$' {
                    i += 1;
                } else {
                    while i < len && (chars[i].is_alphanumeric() || chars[i] == '_') {
                        i += 1;
                    }
                }
            }
            _ => { i += 1; }
        }
    }

    (name, required, multiple, terminated, delimiter, default_val, choice_val)
}

fn parse_choice_bracket(s: &str) -> Option<ChoiceValue> {
    if !s.starts_with('[') { return None; }
    let end = s.rfind(']').unwrap_or(s.len() - 1);
    let inner = &s[1..end];

    if inner.starts_with('?') {
        // Skip validation
        let fn_part = inner[1..].trim_matches('`');
        return Some(ChoiceValue::Fn(fn_part.to_string(), false));
    }

    if inner.starts_with('`') {
        // Choice from function
        let fn_name = inner.trim_matches('`');
        return Some(ChoiceValue::Fn(fn_name.to_string(), true));
    }

    if inner.starts_with('=') {
        // Choices with default (first is default)
        let choices: Vec<String> = inner[1..].split('|').map(|s| s.to_string()).collect();
        return Some(ChoiceValue::Values(choices));
    }

    // Regular choices
    let choices: Vec<String> = inner.split('|').map(|s| s.to_string()).collect();
    Some(ChoiceValue::Values(choices))
}

fn combine_describe(text: &str, _continuation: &[String]) -> String {
    text.trim().to_string()
}

// Parse @option or @flag line
fn parse_option_line(rest: &str, continuation: &[String], is_flag: bool) -> FlagOption {
    let rest = rest.trim();

    // Parse the option definition: [-short] [long_name][modifiers] [notations] [env] [description]
    parse_option_definition(rest, continuation, is_flag)
}

fn parse_option_definition(s: &str, continuation: &[String], is_flag: bool) -> FlagOption {
    // Tokenize into parts
    let mut parts = Vec::new();
    let mut current = String::new();
    let mut in_bracket = 0i32;

    for ch in s.chars() {
        match ch {
            '[' | '(' => { in_bracket += 1; current.push(ch); }
            ']' | ')' => { in_bracket -= 1; current.push(ch); }
            ' ' | '\t' if in_bracket == 0 => {
                if !current.is_empty() {
                    parts.push(current.clone());
                    current.clear();
                }
            }
            _ => { current.push(ch); }
        }
    }
    if !current.is_empty() {
        parts.push(current);
    }

    // Now parse parts
    let mut long_name: Option<String> = None;
    let mut short_name: Option<String> = None;
    let mut modifiers = String::new();
    let mut desc_parts = Vec::new();
    let mut notations: Vec<String> = Vec::new();
    let mut env_binding: Option<String> = None;
    let mut idx = 0;

    while idx < parts.len() {
        let part = &parts[idx];

        if part.starts_with('-') || part.starts_with('+') {
            // Option name - extract name and modifiers
            let (name, mods) = split_option_name_mods(part);

            if long_name.is_none() {
                // Check if this looks like a "short" option
                let stripped = strip_prefix(&name);
                if is_short_single(stripped) && idx + 1 < parts.len() {
                    let next = &parts[idx + 1];
                    if (next.starts_with('-') || next.starts_with('+')) && !next.starts_with("--") {
                        // This IS a short option, next is the long
                        short_name = Some(name);
                        modifiers = mods;
                        idx += 1;
                        continue;
                    } else if next.starts_with("--") || next.starts_with('+') {
                        // This is short, next is long
                        short_name = Some(name);
                        idx += 1;
                        if idx < parts.len() {
                            let (ln, lm) = split_option_name_mods(&parts[idx]);
                            long_name = Some(ln);
                            modifiers = lm;
                        }
                        idx += 1;
                        continue;
                    }
                }
                long_name = Some(name);
                modifiers = mods;
            } else if short_name.is_none() {
                short_name = Some(name);
                if !mods.is_empty() {
                    modifiers = mods;
                }
            } else {
                desc_parts.push(part.clone());
            }
        } else if part.starts_with('<') && !is_flag {
            // Notation
            if let Some(end) = part.find('>') {
                let n = part[1..end].to_string();
                notations.push(n);
            }
        } else if part.starts_with("$$") {
            env_binding = Some("$$".to_string());
        } else if part.starts_with('$') {
            let env_name = part[1..].to_string();
            if !env_name.is_empty() {
                env_binding = Some(env_name);
            }
        } else {
            desc_parts.push(part.clone());
        }
        idx += 1;
    }

    // Combine description from desc_parts and continuation
    let base_desc = desc_parts.join(" ").trim().to_string();
    let full_desc = if continuation.is_empty() {
        base_desc
    } else {
        let cont = continuation.join("\n");
        if base_desc.is_empty() {
            cont
        } else {
            format!("{}\n{}", base_desc, cont)
        }
    };

    // Parse modifiers
    let (required, multiple_occurs, delimiter, terminated, assigned, prefixed) = 
        parse_modifiers(&modifiers);

    // Parse default and choice from modifiers
    let (default_val, choice_val) = parse_default_and_choice(&modifiers);

    // Determine num_args based on is_flag and notations
    let (num_args, multiple_values) = if is_flag {
        ((0usize, 0usize), false)
    } else {
        compute_option_num_args(&notations, &modifiers)
    };

    // Compute ID
    let id = if let Some(ref ln) = long_name {
        option_name_to_id(ln)
    } else if let Some(ref sn) = short_name {
        option_name_to_id(sn)
    } else {
        String::new()
    };

    // Compute env
    let env = if let Some(eb) = env_binding {
        if eb == "$$" {
            let name_for_env = long_name.as_deref().or(short_name.as_deref()).unwrap_or("");
            let stripped = strip_prefix(name_for_env);
            Some(stripped.to_uppercase().replace('-', "_").replace('.', "_"))
        } else {
            Some(eb)
        }
    } else {
        None
    };

    FlagOption {
        id,
        long_name,
        short_name,
        describe: full_desc,
        is_flag,
        notations,
        required,
        multiple_values,
        multiple_occurs,
        num_args,
        delimiter,
        terminated,
        prefixed,
        assigned,
        default: default_val,
        choice: choice_val,
        env,
        inherited: false,
    }
}

fn strip_prefix(s: &str) -> &str {
    if s.starts_with("--") {
        &s[2..]
    } else if s.starts_with('-') || s.starts_with('+') {
        &s[1..]
    } else {
        s
    }
}

fn is_short_single(stripped: &str) -> bool {
    stripped.len() == 1
}

fn split_option_name_mods(s: &str) -> (String, String) {
    // Split "name" from "modifiers" where name includes the - prefix
    // Modifiers are: !, *, +, ~, ,, =val, [choices], :
    let mut i = 0;
    let chars: Vec<char> = s.chars().collect();
    let len = chars.len();

    // Skip prefix (-, --, +)
    if i < len && (chars[i] == '-' || chars[i] == '+') {
        i += 1;
        if i < len && chars[i] == '-' {
            i += 1;
        }
    }

    // Skip name chars (alphanumeric, -, _, .)
    while i < len && (chars[i].is_alphanumeric() || chars[i] == '-' || chars[i] == '_' || chars[i] == '.') {
        i += 1;
    }

    let name: String = chars[..i].iter().collect();
    let mods: String = chars[i..].iter().collect();

    (name, mods)
}

fn parse_modifiers(mods: &str) -> (bool, bool, Option<char>, bool, bool, bool) {
    let mut required = false;
    let mut multiple_occurs = false;
    let mut delimiter: Option<char> = None;
    let mut terminated = false;
    let mut assigned = false;
    let mut prefixed = false;

    let mut i = 0;
    let chars: Vec<char> = mods.chars().collect();
    let len = chars.len();

    while i < len {
        match chars[i] {
            '!' => { required = true; i += 1; }
            '*' => { multiple_occurs = true; i += 1; }
            '+' => { required = true; multiple_occurs = true; i += 1; }
            '~' => { terminated = true; i += 1; }
            ',' => { delimiter = Some(','); i += 1; }
            ':' => { assigned = true; i += 1; }
            '-' => { prefixed = true; i += 1; }
            '=' => {
                i += 1;
                if i < len && chars[i] == '`' {
                    i += 1;
                    while i < len && chars[i] != '`' { i += 1; }
                    if i < len { i += 1; }
                } else {
                    while i < len && chars[i] != '[' { i += 1; }
                }
            }
            '[' => {
                let mut depth = 1;
                i += 1;
                while i < len && depth > 0 {
                    if chars[i] == '[' { depth += 1; }
                    if chars[i] == ']' { depth -= 1; }
                    i += 1;
                }
            }
            _ => { i += 1; }
        }
    }

    (required, multiple_occurs, delimiter, terminated, assigned, prefixed)
}

fn parse_default_and_choice(mods: &str) -> (Option<DefaultValue>, Option<ChoiceValue>) {
    let mut default_val: Option<DefaultValue> = None;
    let mut choice_val: Option<ChoiceValue> = None;

    let mut i = 0;
    let chars: Vec<char> = mods.chars().collect();
    let len = chars.len();

    while i < len {
        match chars[i] {
            '=' if i == 0 || (i > 0 && !matches!(chars[i-1], '+' | '*')) => {
                i += 1;
                if i < len && chars[i] == '`' {
                    i += 1;
                    let start = i;
                    while i < len && chars[i] != '`' { i += 1; }
                    let fn_name: String = chars[start..i].iter().collect();
                    if i < len { i += 1; }
                    default_val = Some(DefaultValue::Fn(fn_name));
                } else {
                    let start = i;
                    while i < len && chars[i] != '[' {
                        i += 1;
                    }
                    let val: String = chars[start..i].iter().collect();
                    if !val.is_empty() {
                        default_val = Some(DefaultValue::Value(val));
                    }
                }
            }
            '[' => {
                let bracket_start = i;
                let mut depth = 1;
                i += 1;
                while i < len && depth > 0 {
                    if chars[i] == '[' { depth += 1; }
                    if chars[i] == ']' { depth -= 1; }
                    i += 1;
                }
                let bracket: String = chars[bracket_start..i].iter().collect();
                choice_val = parse_choice_bracket(&bracket);

                if let Some(ChoiceValue::Values(ref vals)) = choice_val {
                    let inner = &bracket[1..bracket.len()-1];
                    if inner.starts_with('=') && default_val.is_none() {
                        if let Some(first) = vals.first() {
                            default_val = Some(DefaultValue::Value(first.clone()));
                        }
                    }
                }
            }
            _ => { i += 1; }
        }
    }

    (default_val, choice_val)
}

fn compute_option_num_args(notations: &[String], mods: &str) -> ((usize, usize), bool) {
    // Terminated (~) takes 1..32767
    let is_terminated = mods.contains('~');

    if is_terminated {
        return ((1, 32767), true);
    }

    if notations.is_empty() {
        return ((1, 1), false);
    }

    // Check the last notation for modifiers like FILE+
    let last = notations.last().unwrap();
    if last.ends_with('+') {
        // unlimited from notation length to max
        let min = notations.len();
        return ((min, 32767), true);
    }

    let count = notations.len();
    (( count, count ), count > 1)
}

fn option_name_to_id(name: &str) -> String {
    let stripped = strip_prefix(name);
    let base = if name.starts_with('+') {
        format!("plus_{}", stripped)
    } else {
        stripped.to_string()
    };
    base.replace('-', "_").replace('.', "_")
}

// Parse @env line
fn parse_env_line(rest: &str, continuation: &[String]) -> EnvDef {
    let rest = rest.trim();

    let (name_mods, describe_text) = extract_pos_name_modifiers(rest);
    let (id, required, _, _, _, default_val, choice_val) = parse_name_modifiers_full(&name_mods);

    let describe = combine_describe(&describe_text, continuation);

    EnvDef {
        id,
        describe,
        required,
        default: default_val,
        choice: choice_val,
        inherited: false,
    }
}
PARSEREOF

