// Generate bash eval output for --argc-eval

use std::collections::HashMap;
use std::fs;
use std::path::Path;
use crate::command::*;
use crate::parser;
use crate::utils;

pub fn argc_eval(script_path: &str, args: &[String]) -> Result<(), String> {
    // Read and parse the script
    let content = fs::read_to_string(script_path)
        .map_err(|e| format!("Error reading {}: {}", script_path, e))?;

    // Get script name (basename without .sh)
    let script_name = Path::new(script_path)
        .file_stem()
        .and_then(|s| s.to_str())
        .unwrap_or(script_path);

    let cmd = parser::parse_script(&content, script_name);

    // Parse the arguments against the command structure
    let all_args: Vec<String> = {
        let mut v = vec![script_name.to_string()];
        v.extend_from_slice(args);
        v
    };

    match parse_and_eval(&cmd, &all_args, &content) {
        Ok(output) => {
            print!("{}", output);
            Ok(())
        }
        Err(e) => {
            // Output as bash eval error
            print_error(&e);
            Ok(())
        }
    }
}

fn print_error(msg: &str) {
    println!("command cat >&2 <<-'EOF' \n{}\nEOF\nexit 1", msg);
}

fn print_help_output(help: &str) {
    println!("command cat >&2 <<-'EOF' \n{}\nEOF\nexit 0", help);
}

struct ParseState<'a> {
    cmd: &'a Command,
    all_args: Vec<String>,
    script_name: &'a str,
    // Variable assignments
    vars: HashMap<String, VarValue>,
    // Positional args accumulated
    positionals: Vec<String>,
    // Function to call
    fn_to_call: Option<String>,
    // Dash separator position
    dash_pos: Option<usize>,
    // Required tools
    require_tools: Vec<String>,
    // Env setup code
    env_setup: Vec<String>,
}

#[derive(Clone, Debug)]
enum VarValue {
    Scalar(String),
    Array(Vec<String>),
}

fn parse_and_eval(root: &Command, all_args: &[String], content: &str) -> Result<String, String> {
    // Start parsing from root
    let script_name = &all_args[0];

    let result = parse_command(root, all_args, 1, content)?;

    Ok(result)
}

struct ParseResult {
    vars: Vec<(String, VarValue)>,
    fn_to_call: Option<String>,
    positionals: Vec<String>,
    require_tools: Vec<String>,
    env_setup: Vec<String>,
    dotenv_file: Option<String>,
}

fn parse_command(
    cmd: &Command,
    all_args: &[String],
    start_idx: usize,
    content: &str,
) -> Result<String, String> {
    let mut result = ParseResult {
        vars: vec![],
        fn_to_call: None,
        positionals: vec![],
        require_tools: cmd.metadata.require_tools.clone(),
        env_setup: vec![],
        dotenv_file: None,
    };

    // Check for dotenv
    if let Some(ref dotenv) = cmd.metadata.dotenv {
        let env_file = if dotenv.is_empty() { ".env".to_string() } else { dotenv.clone() };
        result.dotenv_file = Some(env_file);
    }

    // Parse arguments
    parse_args_for_cmd(cmd, all_args, start_idx, content, &mut result)?;

    // Generate output
    generate_eval_output(cmd, all_args, &result)
}

fn parse_args_for_cmd(
    cmd: &Command,
    all_args: &[String],
    start_idx: usize,
    content: &str,
    result: &mut ParseResult,
) -> Result<(), String> {
    // If command has subcommands, parse the subcommand
    if !cmd.subcommands.is_empty() {
        parse_with_subcommands(cmd, all_args, start_idx, content, result)?;
    } else {
        // No subcommands - parse flags/options/positionals directly
        parse_leaf_command(cmd, all_args, start_idx, content, result)?;
    }

    Ok(())
}

fn parse_with_subcommands(
    cmd: &Command,
    all_args: &[String],
    start_idx: usize,
    content: &str,
    result: &mut ParseResult,
) -> Result<(), String> {
    let cmd_name = &all_args[0];
    let mut idx = start_idx;
    let len = all_args.len();

    // Determine sign for options
    let sign = cmd.option_sign();
    let combine_shorts = cmd.metadata.combine_shorts;

    // Check for default subcommand
    let default_subcmd = cmd.subcommands.iter().find(|s| s.metadata.default_subcommand.is_some());

    while idx < len {
        let arg = &all_args[idx];

        if arg == "--" {
            // End of options
            let dash_pos = result.positionals.len();
            result.positionals.extend(all_args[idx+1..].iter().cloned());
            idx = len;
            break;
        }

        // Check for help/version
        if is_help_flag(arg, cmd) {
            let help_text = crate::help::generate_help(cmd, all_args, 0);
            print_help_output(&help_text);
            std::process::exit(0);
        }

        if is_version_flag(arg, cmd) {
            let version = cmd.version.as_deref().unwrap_or("0.0.0");
            println!("command cat >&2 <<-'EOF' \n{} {}\nEOF\nexit 0", cmd_name, version);
            std::process::exit(0);
        }

        // Check for root-level flags/options (for inherit-flag-options scenario)
        if try_parse_flag_option(cmd, arg, all_args, &mut idx, result)? {
            continue;
        }

        // Check for subcommand
        let subcmd_name = arg.as_str();
        if let Some(subcmd) = find_subcmd(cmd, subcmd_name) {
            // Found subcommand - recurse into it
            let subcmd_clone = subcmd.clone();
            return parse_subcommand(&subcmd_clone, all_args, idx + 1, content, result);
        }

        // Check for "help" subcommand
        if subcmd_name == "help" {
            let help_arg = all_args.get(idx + 1).map(|s| s.as_str()).unwrap_or("");
            if help_arg.is_empty() {
                let help_text = crate::help::generate_help(cmd, all_args, 0);
                print_help_output(&help_text);
                std::process::exit(0);
            } else if let Some(sub) = find_subcmd(cmd, help_arg) {
                let sub_clone = sub.clone();
                let help_text = crate::help::generate_help(&sub_clone, all_args, 0);
                print_help_output(&help_text);
                std::process::exit(0);
            } else {
                let subcmds = get_subcmd_names(cmd);
                return Err(format!("error: invalid value `{}` for `<command>`\n  [possible values: {}]",
                    help_arg, subcmds.join(", ")));
            }
        }

        // Unknown argument
        if let Some(default) = default_subcmd {
            // Use default subcommand
            let default_clone = default.clone();
            return parse_subcommand(&default_clone, all_args, idx, content, result);
        }

        if is_option_like(arg) {
            return Err(format!("error: `{}` requires a subcommand but '{}' is not one of them\n  [subcommands: {}]",
                cmd_name, arg, get_subcmd_names(cmd).join(", ")));
        } else {
            return Err(format!("error: `{}` requires a subcommand but '{}' is not one of them\n  [subcommands: {}]",
                cmd_name, arg, get_subcmd_names(cmd).join(", ")));
        }
    }

    // If we got here without finding a subcommand
    if result.fn_to_call.is_none() {
        if let Some(default) = default_subcmd {
            // Execute default subcommand with remaining positionals
            let default_fn = default.command_fn.clone();
            result.fn_to_call = default_fn;
            // Apply default subcommand's processing
            apply_command_defaults(&default.clone(), result);
        } else if let Some(ref main_fn) = cmd.command_fn {
            // Root command has a direct function (main)
            result.fn_to_call = Some(main_fn.clone());
            apply_command_defaults(cmd, result);
        } else {
            // Show help
            let help_text = crate::help::generate_help(cmd, all_args, 0);
            print_help_output(&help_text);
            std::process::exit(0);
        }
    }

    Ok(())
}

fn parse_subcommand(
    cmd: &Command,
    all_args: &[String],
    start_idx: usize,
    content: &str,
    result: &mut ParseResult,
) -> Result<(), String> {
    // Collect require_tools
    result.require_tools.extend(cmd.metadata.require_tools.clone());

    if !cmd.subcommands.is_empty() {
        parse_with_subcommands(cmd, all_args, start_idx, content, result)
    } else {
        parse_leaf_command(cmd, all_args, start_idx, content, result)
    }
}

fn parse_leaf_command(
    cmd: &Command,
    all_args: &[String],
    start_idx: usize,
    content: &str,
    result: &mut ParseResult,
) -> Result<(), String> {
    let cmd_name = &all_args[0];
    let mut idx = start_idx;
    let len = all_args.len();
    let sign = cmd.option_sign();
    let combine_shorts = cmd.metadata.combine_shorts;
    let has_pos_with_choices = cmd.positionals.iter().any(|p| p.choice.is_some());

    // Initialize option vars (for defaults)
    let mut option_set: HashMap<String, bool> = HashMap::new();

    while idx < len {
        let arg = &all_args[idx];

        if arg == "--" {
            let dash_pos = result.positionals.len();
            result.positionals.extend(all_args[idx+1..].iter().cloned());
            idx = len;
            break;
        }

        // Check help/version
        if is_help_flag(arg, cmd) {
            let help_text = crate::help::generate_help(cmd, all_args, 0);
            print_help_output(&help_text);
            std::process::exit(0);
        }

        // Check for "help" positional
        // This is only if there are no other positionals being processed

        if let Some(fo) = find_matching_flag_option(cmd, arg) {
            let fo_clone = fo.clone();
            parse_flag_option_value(&fo_clone, arg, all_args, &mut idx, result, &mut option_set, content)?;
        } else if is_option_like_for_cmd(arg, cmd) {
            // Unknown option
            let key = arg.split('=').next().unwrap_or(arg);
            return Err(format!("error: unexpected argument `{}` found", key));
        } else if combine_shorts && is_combined_short(arg, cmd) {
            // Handle combined shorts like -rf
            parse_combined_shorts(arg, all_args, &mut idx, cmd, result, &mut option_set, content)?;
        } else {
            // Positional argument
            result.positionals.push(arg.clone());
            idx += 1;
        }
    }

    // Set function name
    if let Some(ref fn_name) = cmd.command_fn {
        result.fn_to_call = Some(fn_name.clone());
    }

    // Apply defaults and validate
    apply_command_defaults(cmd, result);

    // Validate positionals
    validate_positionals(cmd, result)?;

    // Set positional variables
    set_positional_vars(cmd, result)?;

    // Validate env vars and add setup
    validate_and_setup_envs(cmd, result, content)?;

    // Check required options
    check_required_options(cmd, result)?;

    Ok(())
}

fn find_matching_flag_option<'a>(cmd: &'a Command, arg: &str) -> Option<&'a FlagOption> {
    let (key, _value) = if let Some(pos) = arg.find('=') {
        (&arg[..pos], Some(&arg[pos+1..]))
    } else {
        (arg, None)
    };

    cmd.flag_options.iter().find(|fo| {
        if fo.prefixed {
            // For prefixed options, check if arg starts with the option prefix
            let prefix = fo.long_name.as_deref().unwrap_or("");
            // Remove trailing - from prefix (the - in -X-)
            let base_prefix = prefix.trim_end_matches('-');
            arg.starts_with(base_prefix) && arg.len() > base_prefix.len()
        } else {
            let ln_match = fo.long_name.as_deref().map(|n| n == key).unwrap_or(false);
            let sn_match = fo.short_name.as_deref().map(|n| n == key).unwrap_or(false);
            ln_match || sn_match
        }
    })
}

fn parse_flag_option_value(
    fo: &FlagOption,
    arg: &str,
    all_args: &[String],
    idx: &mut usize,
    result: &mut ParseResult,
    option_set: &mut HashMap<String, bool>,
    content: &str,
) -> Result<(), String> {
    if fo.is_flag {
        // Flags don't take values
        if arg.contains('=') {
            let name = fo.long_name.as_deref().or(fo.short_name.as_deref()).unwrap_or("");
            return Err(format!("error: flag `{}` don't accept any value", name));
        }

        let var_name = format!("argc_{}", fo.id);
        if fo.multiple_occurs {
            // Increment counter
            let count = result.vars.iter().find(|(k, _)| k == &var_name)
                .and_then(|(_, v)| if let VarValue::Scalar(s) = v { s.parse::<u32>().ok() } else { None })
                .unwrap_or(0);
            result.vars.retain(|(k, _)| k != &var_name);
            result.vars.push((var_name, VarValue::Scalar((count + 1).to_string())));
        } else {
            // Check if already set
            if option_set.contains_key(&fo.id) {
                let name = fo.long_name.as_deref().or(fo.short_name.as_deref()).unwrap_or("");
                return Err(format!("error: the argument `{}` cannot be used multiple times", name));
            }
            option_set.insert(fo.id.clone(), true);
            result.vars.push((var_name, VarValue::Scalar("1".to_string())));
        }
        *idx += 1;
    } else if fo.assigned {
        // Assigned option: must use = syntax
        if !arg.contains('=') {
            let name = fo.long_name.as_deref().or(fo.short_name.as_deref()).unwrap_or("");
            return Err(format!("error: incorrect number of values for `{}`", 
                render_option_name(fo)));
        }
        let value = arg.splitn(2, '=').nth(1).unwrap_or("");

        // Validate choice
        validate_choice_value(fo, &[value], content)?;

        let var_name = format!("argc_{}", fo.id);
        result.vars.push((var_name, VarValue::Scalar(value.to_string())));
        *idx += 1;
    } else {
        // Regular option - collect values
        let values = collect_option_values(fo, arg, all_args, *idx)?;
        let n_consumed = values.len();

        // Validate choice
        validate_choice_value(fo, &values.iter().map(|s| s.as_str()).collect::<Vec<_>>(), content)?;

        let var_name = format!("argc_{}", fo.id);

        if fo.multiple_occurs || fo.multiple_values && fo.multiple_occurs {
            // Append to array
            let existing: Vec<String> = result.vars.iter()
                .find(|(k, _)| k == &var_name)
                .and_then(|(_, v)| if let VarValue::Array(a) = v { Some(a.clone()) } else { None })
                .unwrap_or_default();
            result.vars.retain(|(k, _)| k != &var_name);
            let mut new_arr = existing;
            new_arr.extend(values.iter().cloned());
            result.vars.push((var_name, VarValue::Array(new_arr)));
        } else if fo.num_args.1 > 1 || fo.multiple_values {
            // Multiple value option
            result.vars.push((var_name, VarValue::Array(values)));
        } else {
            // Single value
            if option_set.contains_key(&fo.id) {
                let name = fo.long_name.as_deref().or(fo.short_name.as_deref()).unwrap_or("");
                return Err(format!("error: the argument `{}` cannot be used multiple times", name));
            }
            option_set.insert(fo.id.clone(), true);
            let val = values.into_iter().next().unwrap_or_default();
            result.vars.push((var_name, VarValue::Scalar(val)));
        }

        *idx += 1 + n_consumed;
    }

    Ok(())
}

fn collect_option_values(fo: &FlagOption, arg: &str, all_args: &[String], idx: usize) -> Result<Vec<String>, String> {
    let (min, max) = fo.num_args;

    if arg.contains('=') {
        // Value is in the arg itself
        let value = arg.splitn(2, '=').nth(1).unwrap_or("");
        if min > 0 && value.is_empty() {
            let name = fo.long_name.as_deref().or(fo.short_name.as_deref()).unwrap_or("");
            return Err(format!("error: incorrect number of values for `{}`", render_option_name(fo)));
        }
        let mut values = vec![value.to_string()];
        // Handle delimiter
        if let Some(delim) = fo.delimiter {
            let split: Vec<String> = values[0].split(delim).map(|s| s.to_string()).collect();
            return Ok(split);
        }
        return Ok(values);
    }

    // Collect subsequent args
    let mut values = Vec::new();
    let mut next_idx = idx + 1;

    while next_idx < all_args.len() && values.len() < max {
        let next = &all_args[next_idx];

        // Stop if next looks like a flag/option (unless it's "--")
        if is_option_arg(next, fo.sign()) {
            if next.len() > 1 {
                break;
            }
        }

        values.push(next.clone());
        next_idx += 1;

        if !fo.multiple_values && !fo.terminated && min <= values.len() && max == values.len() {
            break;
        }
    }

    if values.len() < min {
        let name = render_option_name(fo);
        return Err(format!("error: incorrect number of values for `{}`", name));
    }

    // Handle delimiter
    if let Some(delim) = fo.delimiter {
        let mut split_values = Vec::new();
        for v in &values {
            split_values.extend(v.split(delim).map(|s| s.to_string()));
        }
        return Ok(split_values);
    }

    Ok(values)
}

fn render_option_name(fo: &FlagOption) -> String {
    let name = fo.long_name.as_deref().or(fo.short_name.as_deref()).unwrap_or("");
    if fo.is_flag || fo.notations.is_empty() {
        return name.to_string();
    }

    let notations_str = if fo.assigned {
        format!("={}", fo.notations.iter().map(|n| format!("<{}>", n)).collect::<Vec<_>>().join(" "))
    } else if fo.terminated {
        format!(" <{}~>", fo.notations.first().unwrap_or(&"VALUE".to_string()))
    } else if fo.multiple_occurs || fo.num_args.1 > 1 {
        if fo.required {
            format!(" <{}>...", fo.notations.first().unwrap_or(&"VALUE".to_string()))
        } else {
            format!(" [{}]...", fo.notations.first().unwrap_or(&"VALUE".to_string()))
        }
    } else {
        fo.notations.iter().map(|n| format!(" <{}>", n)).collect::<Vec<_>>().join("")
    };

    format!("{}{}", name, notations_str)
}

fn validate_choice_value(fo: &FlagOption, values: &[&str], content: &str) -> Result<(), String> {
    if let Some(ref choice) = fo.choice {
        match choice {
            ChoiceValue::Values(choices) => {
                for val in values {
                    if !choices.contains(&val.to_string()) {
                        let name = render_option_name(fo);
                        // Get notation for display
                        let notation = fo.notations.first().unwrap_or(&fo.id);
                        return Err(format!("error: invalid value `{}` for `<{}>`\n  [possible values: {}]",
                            val, notation, choices.join(", ")));
                    }
                }
            }
            ChoiceValue::Fn(fn_name, validate) => {
                if *validate {
                    // Run the function to get choices
                    let choices = run_choice_fn(fn_name, content)?;
                    for val in values {
                        if !choices.contains(&val.to_string()) {
                            let notation = fo.notations.first().unwrap_or(&fo.id);
                            return Err(format!("error: invalid value `{}` for `<{}>`\n  [possible values: {}]",
                                val, notation, choices.join(", ")));
                        }
                    }
                }
            }
        }
    }
    Ok(())
}

fn run_choice_fn(_fn_name: &str, _content: &str) -> Result<Vec<String>, String> {
    // In eval mode, we don't actually run functions - choices are validated at runtime
    // Return empty vec (validation deferred to bash)
    Ok(vec![])
}

fn apply_command_defaults(cmd: &Command, result: &mut ParseResult) {
    // Apply defaults for options not yet set
    for fo in &cmd.flag_options {
        if matches!(fo.id.as_str(), "help" | "version") { continue; }
        if fo.is_flag { continue; }

        let var_name = format!("argc_{}", fo.id);
        let already_set = result.vars.iter().any(|(k, _)| k == &var_name);

        if !already_set {
            if let Some(ref default) = fo.default {
                let val = match default {
                    DefaultValue::Value(v) => v.clone(),
                    DefaultValue::Fn(f) => format!("`{}`", f),
                };
                result.vars.push((var_name, VarValue::Scalar(val)));
            }
        }

        // Default from choice with = prefix
        if !already_set {
            if let Some(ChoiceValue::Values(ref choices)) = fo.choice {
                // Already handled in default
            }
        }
    }
}

fn validate_positionals(cmd: &Command, result: &mut ParseResult) -> Result<(), String> {
    // Check if required positionals are satisfied
    let pos_args = &result.positionals;
    let pos_defs = &cmd.positionals;

    if pos_defs.is_empty() { return Ok(()); }

    // For "help" positional shortcut
    if pos_args.len() == 1 && pos_args[0] == "help" {
        // This is handled elsewhere
    }

    Ok(())
}

fn set_positional_vars(cmd: &Command, result: &mut ParseResult) -> Result<(), String> {
    if cmd.positionals.is_empty() {
        // Check for unexpected positionals
        if !result.positionals.is_empty() {
            // If no positionals defined, might be OK if there's no error check
            // But typically, unexpected args are errors
        }
        return Ok(());
    }

    let pos_defs = &cmd.positionals;
    let pos_args = &result.positionals;

    // Match positionals to definitions
    let matches = match_positionals(pos_defs, pos_args)?;

    for (i, pos_def) in pos_defs.iter().enumerate() {
        if let Some((start, count)) = matches.get(i).and_then(|m| *m) {
            let var_name = format!("argc_{}", pos_def.id.replace("...", "___").replace('-', "_").replace('.', "_"));

            if pos_def.multiple {
                let values: Vec<String> = pos_args[start..start+count].to_vec();
                // Handle delimiter
                let values = if let Some(delim) = pos_def.delimiter {
                    values.iter().flat_map(|v| v.split(delim).map(|s| s.to_string())).collect()
                } else {
                    values
                };
                result.vars.push((var_name, VarValue::Array(values)));
            } else {
                let val = pos_args.get(start).cloned().unwrap_or_default();
                result.vars.push((var_name, VarValue::Scalar(val)));
            }
        } else {
            // Not provided
            if pos_def.required {
                let notation = &pos_def.notation;
                return Err(format!("error: the following required arguments were not provided:\n  <{}>", notation));
            }
            // Apply default if present
            if let Some(ref default) = pos_def.default {
                let var_name = format!("argc_{}", pos_def.id.replace("...", "___").replace('-', "_").replace('.', "_"));
                let val = match default {
                    DefaultValue::Value(v) => v.clone(),
                    DefaultValue::Fn(f) => format!("`{}`", f),
                };
                result.vars.push((var_name, VarValue::Scalar(val)));
            }
        }
    }

    // Check for unexpected positionals  
    if let Some((extra_start, extra_count)) = matches.get(pos_defs.len()).and_then(|m| *m) {
        if extra_count > 0 {
            let extra_val = &pos_args[extra_start];
            return Err(format!("error: unexpected argument `{}` found", extra_val));
        }
    }

    Ok(())
}

fn match_positionals(
    defs: &[Positional],
    args: &[String],
) -> Result<Vec<Option<(usize, usize)>>, String> {
    let n_defs = defs.len();
    let n_args = args.len();

    let mut result: Vec<Option<(usize, usize)>> = vec![None; n_defs + 1]; // +1 for overflow

    if n_args == 0 {
        return Ok(result);
    }

    // Check if any defs are "multiple"
    let has_multi = defs.iter().any(|d| d.multiple);

    if !has_multi {
        // Simple 1-to-1 matching
        for (i, def) in defs.iter().enumerate() {
            if i < n_args {
                result[i] = Some((i, 1));
            }
        }
        if n_args > n_defs {
            result[n_defs] = Some((n_defs, n_args - n_defs));
        }
        return Ok(result);
    }

    // Complex matching with multiple positionals
    // Strategy: from left to right, assign minimum required, then fill from right to left for multi

    let mut arg_idx = 0;

    for (def_idx, def) in defs.iter().enumerate() {
        if def.multiple {
            // How many remaining defs need arguments?
            let remaining_required: usize = defs[def_idx+1..].iter()
                .filter(|d| d.required || !d.multiple)
                .count();

            let available = n_args.saturating_sub(arg_idx);
            let to_take = if available > remaining_required {
                available - remaining_required
            } else {
                if def.required { 1 } else { 0 }
            };

            // Ensure minimum 1 for required multi
            let actual_take = if def.required && to_take == 0 { 0 } else { to_take };

            if actual_take > 0 {
                result[def_idx] = Some((arg_idx, actual_take));
                arg_idx += actual_take;
            }
        } else {
            if arg_idx < n_args {
                result[def_idx] = Some((arg_idx, 1));
                arg_idx += 1;
            }
        }
    }

    if arg_idx < n_args {
        result[n_defs] = Some((arg_idx, n_args - arg_idx));
    }

    Ok(result)
}

fn validate_and_setup_envs(cmd: &Command, result: &mut ParseResult, content: &str) -> Result<(), String> {
    let mut missing_envs = Vec::new();
    let mut env_setup = Vec::new();

    for env_def in &cmd.envs {
        let val = std::env::var(&env_def.id).ok();

        match &val {
            None => {
                if let Some(ref default) = env_def.default {
                    // Set default
                    let default_val = match default {
                        DefaultValue::Value(v) => format!("export {}={}", env_def.id, v),
                        DefaultValue::Fn(f) => format!("export {}=\"$({})\"", env_def.id, f),
                    };
                    env_setup.push(default_val);
                } else if env_def.required {
                    missing_envs.push(env_def.id.clone());
                }
            }
            Some(v) => {
                // Validate choice if present
                if let Some(ref choice) = env_def.choice {
                    match choice {
                        ChoiceValue::Values(choices) => {
                            // Validate at eval time - we output code to do it
                        }
                        _ => {}
                    }
                }
            }
        }
    }

    if !missing_envs.is_empty() {
        let envs_list: Vec<String> = missing_envs.iter().map(|e| format!("  {}", e)).collect();
        return Err(format!("error: the following required environments were not provided:\n{}", envs_list.join("\n")));
    }

    result.env_setup.extend(env_setup);

    Ok(())
}

fn check_required_options(cmd: &Command, result: &mut ParseResult) -> Result<(), String> {
    let mut missing = Vec::new();

    for fo in &cmd.flag_options {
        if !fo.required { continue; }
        if matches!(fo.id.as_str(), "help" | "version") { continue; }

        let var_name = format!("argc_{}", fo.id);
        let is_set = result.vars.iter().any(|(k, _)| k == &var_name);

        if !is_set {
            missing.push(render_option_name(fo));
        }
    }

    if !missing.is_empty() {
        let items: Vec<String> = missing.iter().map(|n| format!("  {}", n)).collect();
        return Err(format!("error: the following required arguments were not provided:\n{}", items.join("\n")));
    }

    Ok(())
}

fn generate_eval_output(cmd: &Command, all_args: &[String], result: &ParseResult) -> Result<String, String> {
    let mut output = String::new();

    // Generate variable assignments string
    let mut assignments = String::new();

    // Add all variables
    for (name, val) in &result.vars {
        let assign = match val {
            VarValue::Scalar(s) => {
                let quoted = utils::shell_quote(s);
                format!("{}={};", name, quoted)
            }
            VarValue::Array(arr) => {
                let items: Vec<String> = arr.iter().map(|s| utils::shell_quote(s)).collect();
                format!("{}=( {} );", name, items.join(" "))
            }
        };
        assignments.push_str(&assign);
    }

    // Add argc__args
    let args_quoted: Vec<String> = all_args.iter().map(|s| utils::shell_quote(s)).collect();
    assignments.push_str(&format!("argc__args=( {} );", args_quoted.join(" ")));

    // Add argc__fn if set
    if let Some(ref fn_name) = result.fn_to_call {
        assignments.push_str(&format!("argc__fn={};", fn_name));
    }

    // Add argc__positionals
    if result.positionals.is_empty() {
        assignments.push_str("argc__positionals=(  );");
    } else {
        let pos_quoted: Vec<String> = result.positionals.iter().map(|s| utils::shell_quote(s)).collect();
        assignments.push_str(&format!("argc__positionals=( {} );", pos_quoted.join(" ")));
    }

    // Base64 encode
    use base64::Engine;
    let encoded = base64::engine::general_purpose::STANDARD_NO_PAD.encode(assignments.as_bytes());
    output.push_str(&format!("export ARGC_VARS={}\n", encoded));

    // Add require_tools function if needed
    if !result.require_tools.is_empty() {
        output.push_str("\n_argc_require_tools() {\n    local tool missing_tools=()\n    for tool in \"$@\"; do\n        if ! command -v \"$tool\" >/dev/null 2>&1; then\n            missing_tools+=(\"$tool\")\n        fi\n    done\n    if [[ \"${#missing_tools[@]}\" -gt 0 ]]; then\n        echo \"error: missing tools: ${missing_tools[*]}\" >&2\n        exit 1\n    fi\n}\n");
        output.push_str(&format!("_argc_require_tools {}\n", result.require_tools.join(" ")));
        output.push('\n');
    }

    // Add dotenv loading if needed
    if let Some(ref dotenv_file) = result.dotenv_file {
        output.push_str(&generate_dotenv_loader(dotenv_file));
    }

    // Add env setup
    for env_line in &result.env_setup {
        output.push_str(env_line);
        output.push('\n');
    }

    // Add all variable assignments as printed lines
    for (name, val) in &result.vars {
        match val {
            VarValue::Scalar(s) => {
                let quoted = utils::shell_quote(s);
                output.push_str(&format!("{}={}\n", name, quoted));
            }
            VarValue::Array(arr) => {
                let items: Vec<String> = arr.iter().map(|s| utils::shell_quote(s)).collect();
                output.push_str(&format!("{}=( {} )\n", name, items.join(" ")));
            }
        }
    }

    // Print argc__args
    let args_quoted: Vec<String> = all_args.iter().map(|s| utils::shell_quote(s)).collect();
    output.push_str(&format!("argc__args=( {} )\n", args_quoted.join(" ")));

    // Print argc__fn if set
    if let Some(ref fn_name) = result.fn_to_call {
        output.push_str(&format!("argc__fn={}\n", fn_name));
    }

    // Print argc__positionals
    if result.positionals.is_empty() {
        output.push_str("argc__positionals=(  )\n");
    } else {
        let pos_quoted: Vec<String> = result.positionals.iter().map(|s| utils::shell_quote(s)).collect();
        output.push_str(&format!("argc__positionals=( {} )\n", pos_quoted.join(" ")));
    }

    // Print function call
    if let Some(ref fn_name) = result.fn_to_call {
        let pos_args: Vec<String> = result.positionals.iter().map(|s| utils::shell_quote(s)).collect();
        if pos_args.is_empty() {
            output.push_str(&format!("{}\n", fn_name));
        } else {
            output.push_str(&format!("{} {}\n", fn_name, pos_args.join(" ")));
        }
    }

    Ok(output)
}

fn generate_dotenv_loader(env_file: &str) -> String {
    format!("_argc_load_dotenv() {{\n    local env_file=\"$1\" env_vars=\"\"\n    if [[ -f \"$env_file\" ]]; then\n        while IFS='=' read -r key value; do\n            if [[ \"$key\" == $'#'* ]] || [[ -z \"$key\" ]]; then\n                continue\n            fi\n            if [[ -z \"${{!key+x}}\" ]]; then\n                env_vars=\"$env_vars $key=$value\"\n            fi\n        done < <(cat \"$env_file\"; echo \"\")\n        if [[ -n \"$env_vars\" ]]; then\n            eval \"export $env_vars\"\n        fi\n    fi\n}}\n_argc_load_dotenv {}\n", env_file)
}

// Helper functions

fn is_help_flag(arg: &str, cmd: &Command) -> bool {
    cmd.flag_options.iter().find(|f| f.id == "help").map(|f| {
        let key = arg.split('=').next().unwrap_or(arg);
        f.long_name.as_deref() == Some(key) || 
        f.short_name.as_deref() == Some(key) ||
        (cmd.uses_single_hyphen_long() && (key == "-h" || key == "-help"))
    }).unwrap_or(false)
}

fn is_version_flag(arg: &str, cmd: &Command) -> bool {
    cmd.flag_options.iter().find(|f| f.id == "version").map(|f| {
        let key = arg.split('=').next().unwrap_or(arg);
        f.long_name.as_deref() == Some(key) || f.short_name.as_deref() == Some(key)
    }).unwrap_or(false)
}

fn find_subcmd<'a>(cmd: &'a Command, name: &str) -> Option<&'a Command> {
    cmd.subcommands.iter().find(|s| s.name == name || s.aliases.iter().any(|a| a == name))
}

fn get_subcmd_names(cmd: &Command) -> Vec<String> {
    cmd.subcommands.iter().flat_map(|s| {
        let mut names = vec![s.name.clone()];
        names.extend(s.aliases.iter().cloned());
        names
    }).collect()
}

fn is_option_like(arg: &str) -> bool {
    (arg.starts_with('-') || arg.starts_with('+')) && arg.len() > 1
}

fn is_option_like_for_cmd(arg: &str, cmd: &Command) -> bool {
    let key = arg.split('=').next().unwrap_or(arg);
    let sign = cmd.option_sign();

    if sign == "+" {
        key.starts_with('+') && key.len() > 1
    } else {
        key.starts_with('-') && key.len() > 1 && !key.starts_with("---")
    }
}

fn is_option_arg(arg: &str, sign: &str) -> bool {
    if sign == "+" {
        arg.starts_with('+') && arg.len() > 1
    } else {
        arg.starts_with('-') && arg.len() > 1
    }
}

fn try_parse_flag_option(
    cmd: &Command,
    arg: &str,
    all_args: &[String],
    idx: &mut usize,
