    cmd: &Command,
    all_args: &[String],
    start_idx: usize,
    content: &str,
    result: &mut ParseResult,
) -> Result<(), String> {
    // If command has subcommands, parse the subcommand
    if !cmd.subcommands.is_empty() {
        parse_with_subcommands(cmd, all_args, start_idx, content, result)?;
    } else {
        // No subcommands - parse flags/options/positionals directly
