fn build_commands_section(subcommands: &[Command], width: usize) -> String {
    let max_name_len = subcommands.iter().map(|c| {
        let name_len = c.name.len();
        name_len
    }).max().unwrap_or(0);

    let mut lines = Vec::new();

    for cmd in subcommands {
        let mut name_str = cmd.name.clone();

        // Add aliases
        let mut extra_info = Vec::new();
        if !cmd.aliases.is_empty() {
            extra_info.push(format!("[aliases: {}]", cmd.aliases.join(", ")));
        }
        if cmd.metadata.default_subcommand.is_some() {
            extra_info.push("[default]".to_string());
        }

        let desc = if !cmd.describe.is_empty() {
            let first_line = cmd.describe.lines().next().unwrap_or("");
            if !extra_info.is_empty() {
                format!("{} {}", first_line, extra_info.join(" "))
            } else {
                first_line.to_string()
            }
        } else if !extra_info.is_empty() {
            extra_info.join(" ")
        } else {
            String::new()
        };

        if desc.is_empty() {
            lines.push(format!("  {}", name_str));
        } else {
            let col_width = max_name_len;
            let padding = " ".repeat(col_width - name_str.len() + 2);
            let indent = 2 + col_width + 2;

            let desc_wrapped = if width > indent {
                wrap_text_with_indent(&desc, width, indent)
            } else {
                desc.clone()
            };

            if desc_wrapped.contains('\n') {
                let first = desc_wrapped.lines().next().unwrap_or("");
                let rest: Vec<&str> = desc_wrapped.lines().skip(1).collect();
                lines.push(format!("  {}{}{}", name_str, padding, first));
                for r in rest {
                    lines.push(r.to_string());
                }
            } else {
                lines.push(format!("  {}{}{}", name_str, padding, desc_wrapped));
            }
        }
    }

    lines.join("\n")
}

fn wrap_text(text: &str, width: usize, _indent: usize) -> String {
    if text.len() <= width {
        return text.to_string();
    }

    let mut result = Vec::new();
    for line in text.lines() {
        if line.len() <= width {
            result.push(line.to_string());
        } else {
            let wrapped = wrap_single_line(line, width);
            result.extend(wrapped);
        }
    }
    result.join("\n")
}

fn wrap_text_with_indent(text: &str, width: usize, indent: usize) -> String {
    let available = if width > indent { width - indent } else { width };
    let indent_str = " ".repeat(indent);

    let mut result = Vec::new();
    let is_first_line = true;

    for (i, line) in text.lines().enumerate() {
        if line.len() <= available {
            if i == 0 {
                result.push(line.to_string());
