    all_args.first().cloned().unwrap_or_default()
}

fn build_usage_line(cmd: &Command, cmd_path: &str, width: usize) -> String {
    let mut parts = Vec::new();
    parts.push(cmd_path.to_string());

    // Required inherited flags/options
    let required_opts: Vec<_> = cmd.flag_options.iter()
        .filter(|f| f.required && !f.is_flag)
        .collect();

    // If has subcommands
    if !cmd.subcommands.is_empty() {
        // Optional options  
        let has_opts = cmd.flag_options.iter().any(|f| !matches!(f.id.as_str(), "help" | "version"));
        if has_opts {
            parts.push("[OPTIONS]".to_string());
        }

        // Required options
        for fo in &required_opts {
            parts.push(render_required_option(fo));
        }

        parts.push("<COMMAND>".to_string());
    } else {
        // Leaf command
        let has_opts = cmd.flag_options.iter().any(|f| !matches!(f.id.as_str(), "help" | "version"));
        let has_required_opts = required_opts.len() > 0;

        if has_opts {
            if has_required_opts {
                parts.push("[OPTIONS]".to_string());
                for fo in &required_opts {
                    if !fo.is_flag {
                        parts.push(render_required_option(fo));
                    }
                }
            } else {
                parts.push("[OPTIONS]".to_string());
            }
        } else if has_required_opts {
            for fo in &required_opts {
                parts.push(render_required_option(fo));
            }
        }

