            }
        }
    }

    lines.join("\n")
}

fn render_option_display(fo: &FlagOption) -> String {
    // Build the option display string: "-s, --long" or "    --long" etc.
    let long = fo.long_name.as_deref().unwrap_or("");
    let short = fo.short_name.as_deref();

    let name_part = if let Some(s) = short {
        format!("{}, {}", s, long)
    } else {
