        parts.push("<COMMAND>".to_string());
    } else {
        // Leaf command
        let has_opts = cmd.flag_options.iter().any(|f| !matches!(f.id.as_str(), "help" | "version"));
        let has_required_opts = required_opts.len() > 0;

        if has_opts {
            if has_required_opts {
                parts.push("[OPTIONS]".to_string());
                for fo in &required_opts {
                    if !fo.is_flag {
                        parts.push(render_required_option(fo));
                    }
                }
            } else {
                parts.push("[OPTIONS]".to_string());
            }
        } else if has_required_opts {
            for fo in &required_opts {
                parts.push(render_required_option(fo));
            }
        }

        // Positionals
        for pos in &cmd.positionals {
            parts.push(render_positional_usage(pos));
        }
    }

    parts.join(" ")
}

fn render_required_option(fo: &FlagOption) -> String {
    let name = fo.long_name.as_deref().or(fo.short_name.as_deref()).unwrap_or("");
    if fo.multiple_occurs {
        let notation = fo.notations.first().unwrap_or(&fo.id);
        if fo.required {
            format!("{} <{}>...", name, notation)
        } else {
            format!("{} [{}]...", name, notation)
        }
    } else {
        let notation = fo.notations.first().unwrap_or(&fo.id);
        format!("{} <{}>", name, notation)
    }
}

fn render_positional_usage(pos: &Positional) -> String {
    let notation = &pos.notation;
    if pos.terminated {
        format!("[{}]...", notation)
    } else if pos.required && pos.multiple {
        format!("<{}>...", notation)
    } else if pos.required {
        format!("<{}>", notation)
    } else if pos.multiple {
        format!("[{}]...", notation)
    } else {
        format!("[{}]", notation)
    }
}

fn build_positionals_section(positionals: &[&Positional], width: usize) -> String {
    // Calculate max notation width for alignment
    let notations: Vec<String> = positionals.iter().map(|p| {
        if p.required {
            format!("<{}>", p.notation)
        } else {
            format!("[{}]", p.notation)
        }
    }).collect();

    let max_notation_len = notations.iter().map(|n| n.len()).max().unwrap_or(0);
    let col_width = max_notation_len.max(8);

    let mut lines = Vec::new();

    for (pos, notation) in positionals.iter().zip(notations.iter()) {
        if pos.describe.is_empty() {
            lines.push(format!("  {}", notation));
        } else {
            let indent = 2 + col_width + 2;
            let desc = if width > indent {
                wrap_text_with_indent(&pos.describe, width, indent)
            } else {
                pos.describe.clone()
            };

            if notation.len() + 2 < col_width + 4 {
                let padding = " ".repeat(col_width - notation.len() + 2);
                lines.push(format!("  {}{}{}", notation, padding, desc));
            } else {
                lines.push(format!("  {}", notation));
                lines.push(format!("  {}{}", " ".repeat(indent - 2), desc));
            }
        }
    }

    lines.join("\n")
}

fn build_options_section(flag_options: &[&FlagOption], width: usize) -> String {
    // Calculate maximum width of option "name" column for alignment
    let option_strs: Vec<String> = flag_options.iter().map(|fo| render_option_display(fo)).collect();
    let max_opt_len = option_strs.iter().map(|s| s.len()).max().unwrap_or(0);

    let mut lines = Vec::new();

    for (fo, opt_str) in flag_options.iter().zip(option_strs.iter()) {
        let describe = build_option_describe(fo);

        if describe.is_empty() {
            lines.push(format!("  {}", opt_str));
        } else {
            let col_min = max_opt_len + 2;
            let indent = 2 + col_min + 2;

            let padding = if opt_str.len() < col_min {
                " ".repeat(col_min - opt_str.len())
            } else {
                " ".to_string()
            };

            let desc_wrapped = if width > indent {
                wrap_text_with_indent(&describe, width, indent)
            } else {
                describe.clone()
            };

            // Check if line fits
            let full_line = format!("  {}{}{}", opt_str, padding, desc_wrapped.lines().next().unwrap_or(""));
            if full_line.len() <= width || width == 0 {
                if desc_wrapped.contains('\n') {
                    let first_line = desc_wrapped.lines().next().unwrap_or("");
                    let rest: Vec<&str> = desc_wrapped.lines().skip(1).collect();
                    lines.push(format!("  {}{}{}", opt_str, padding, first_line));
                    for rest_line in rest {
                        lines.push(rest_line.to_string());
                    }
                } else {
                    lines.push(format!("  {}{}{}", opt_str, padding, desc_wrapped));
                }
            } else {
                lines.push(format!("  {}", opt_str));
                lines.push(format!("  {}{}", " ".repeat(indent - 2), describe));
            }
        }
    }

    lines.join("\n")
}

fn render_option_display(fo: &FlagOption) -> String {
    // Build the option display string: "-s, --long" or "    --long" etc.
    let long = fo.long_name.as_deref().unwrap_or("");
    let short = fo.short_name.as_deref();

    let name_part = if let Some(s) = short {
        format!("{}, {}", s, long)
    } else {
        format!("    {}", long)
    };

    // Add notation
    let notations_str = if fo.is_flag {
        if fo.multiple_occurs {
            "...".to_string()
        } else {
            String::new()
        }
    } else if fo.assigned {
        let n = fo.notations.first().cloned().unwrap_or_else(|| "VALUE".to_string());
        format!("=<{}>", n)
    } else if fo.terminated {
        let n = fo.notations.first().cloned().unwrap_or_else(|| "VALUE".to_string());
        format!(" <{}~>", n)
    } else if fo.prefixed {
        if fo.multiple_occurs {
            let n = fo.notations.first().cloned().unwrap_or_else(|| "VALUE".to_string());
            format!(" [{}]...", n)
        } else {
            let n = fo.notations.first().cloned().unwrap_or_else(|| "VALUE".to_string());
            format!(" <{}>", n)
        }
    } else if fo.notations.is_empty() {
        String::new()
    } else if fo.multiple_occurs {
        let n = fo.notations.first().cloned().unwrap_or_else(|| "VALUE".to_string());
        if fo.required {
            format!(" <{}>...", n)
        } else {
            format!(" [{}]...", n)
        }
    } else if fo.notations.len() == 1 {
        let n = &fo.notations[0];
        format!(" <{}>", n)
    } else {
        let parts: Vec<String> = fo.notations.iter().map(|n| format!("<{}>", n)).collect();
        format!(" {}", parts.join(" "))
    };

    format!("{}{}", name_part, notations_str)
}

fn build_option_describe(fo: &FlagOption) -> String {
    let mut parts = Vec::new();

    let base = fo.describe.lines().next().unwrap_or("").to_string();
    if !base.is_empty() {
        parts.push(base);
    }

    // Add default
    if let Some(ref default) = fo.default {
        let dval = match default {
            DefaultValue::Value(v) => v.clone(),
            DefaultValue::Fn(_) => return parts.join(" "), // Don't show fn defaults
        };
        parts.push(format!("[default: {}]", dval));
    }

    // Add choice  
    if let Some(ChoiceValue::Values(ref choices)) = fo.choice {
        parts.push(format!("[possible values: {}]", choices.join(", ")));
    }

    // Add env
    if let Some(ref env) = fo.env {
        parts.push(format!("[env: {}]", env));
    }

    parts.join(" ")
}

fn build_envs_section(envs: &[EnvDef], width: usize) -> String {
    let max_len = envs.iter().map(|e| {
        let suffix = if e.required { "*" } else { "" };
        e.id.len() + suffix.len()
    }).max().unwrap_or(0);

    let mut lines = Vec::new();

    for env in envs {
        let suffix = if env.required { "*" } else { "" };
        let id_str = format!("{}{}", env.id, suffix);

        let mut desc_parts = vec![];
        if !env.describe.is_empty() {
            desc_parts.push(env.describe.clone());
        }

        if let Some(ref default) = env.default {
            match default {
                DefaultValue::Value(v) => desc_parts.push(format!("[default: {}]", v)),
                _ => {}
            }
        }

        if let Some(ChoiceValue::Values(ref choices)) = env.choice {
            desc_parts.push(format!("[possible values: {}]", choices.join(", ")));
        }

        let desc = desc_parts.join(" ");

        if desc.is_empty() {
            lines.push(format!("  {}", id_str));
        } else {
            let padding = " ".repeat(max_len - id_str.len() + 2);
            lines.push(format!("  {}{}{}", id_str, padding, desc));
        }
    }

    lines.join("\n")
}

fn build_commands_section(subcommands: &[Command], width: usize) -> String {
    let max_name_len = subcommands.iter().map(|c| {
        let name_len = c.name.len();
        name_len
    }).max().unwrap_or(0);

    let mut lines = Vec::new();

    for cmd in subcommands {
        let mut name_str = cmd.name.clone();

        // Add aliases
        let mut extra_info = Vec::new();
        if !cmd.aliases.is_empty() {
            extra_info.push(format!("[aliases: {}]", cmd.aliases.join(", ")));
        }
        if cmd.metadata.default_subcommand.is_some() {
            extra_info.push("[default]".to_string());
        }

        let desc = if !cmd.describe.is_empty() {
            let first_line = cmd.describe.lines().next().unwrap_or("");
            if !extra_info.is_empty() {
                format!("{} {}", first_line, extra_info.join(" "))
            } else {
                first_line.to_string()
            }
        } else if !extra_info.is_empty() {
            extra_info.join(" ")
        } else {
            String::new()
        };

        if desc.is_empty() {
            lines.push(format!("  {}", name_str));
        } else {
            let col_width = max_name_len;
            let padding = " ".repeat(col_width - name_str.len() + 2);
            let indent = 2 + col_width + 2;

            let desc_wrapped = if width > indent {
                wrap_text_with_indent(&desc, width, indent)
            } else {
                desc.clone()
            };

            if desc_wrapped.contains('\n') {
                let first = desc_wrapped.lines().next().unwrap_or("");
                let rest: Vec<&str> = desc_wrapped.lines().skip(1).collect();
                lines.push(format!("  {}{}{}", name_str, padding, first));
                for r in rest {
                    lines.push(r.to_string());
                }
            } else {
                lines.push(format!("  {}{}{}", name_str, padding, desc_wrapped));
            }
        }
    }

    lines.join("\n")
}

fn wrap_text(text: &str, width: usize, _indent: usize) -> String {
    if text.len() <= width {
        return text.to_string();
    }

    let mut result = Vec::new();
    for line in text.lines() {
        if line.len() <= width {
            result.push(line.to_string());
        } else {
            let wrapped = wrap_single_line(line, width);
            result.extend(wrapped);
        }
    }
    result.join("\n")
}

fn wrap_text_with_indent(text: &str, width: usize, indent: usize) -> String {
    let available = if width > indent { width - indent } else { width };
    let indent_str = " ".repeat(indent);

    let mut result = Vec::new();
    let is_first_line = true;

    for (i, line) in text.lines().enumerate() {
        if line.len() <= available {
            if i == 0 {
                result.push(line.to_string());
            } else {
                result.push(format!("{}{}", indent_str, line));
            }
        } else {
            let wrapped = wrap_single_line(line, available);
            for (j, wline) in wrapped.iter().enumerate() {
                if i == 0 && j == 0 {
                    result.push(wline.clone());
                } else {
                    result.push(format!("{}{}", indent_str, wline));
                }
            }
        }
    }

    result.join("\n")
}

fn wrap_single_line(line: &str, width: usize) -> Vec<String> {
    if line.len() <= width {
        return vec![line.to_string()];
    }

    let mut lines = Vec::new();
    let mut current = String::new();

    for word in line.split(' ') {
        if current.is_empty() {
            current = word.to_string();
        } else if current.len() + 1 + word.len() <= width {
            current.push(' ');
            current.push_str(word);
        } else {
            lines.push(current.clone());
            current = word.to_string();
        }
    }

    if !current.is_empty() {
        lines.push(current);
    }

    lines
}
