}

fn export_default_to_json(default: &Option<DefaultValue>) -> String {
    match default {
        None => "null".to_string(),
        Some(DefaultValue::Value(v)) => format!("{{\n      \"type\": \"Value\",\n      \"value\": {}\n    }}", json_str(v)),
        Some(DefaultValue::Fn(f)) => format!("{{\n      \"type\": \"Fn\",\n      \"value\": {}\n    }}", json_str(f)),
    }
}

fn export_choice_to_json(choice: &Option<ChoiceValue>) -> String {
    match choice {
        None => "null".to_string(),
        Some(ChoiceValue::Values(vals)) => {
            let v: Vec<String> = vals.iter().map(|v| json_str(v)).collect();
            format!("{{\n      \"type\": \"Values\",\n      \"data\": [{}]\n    }}", v.join(", "))
        }
        Some(ChoiceValue::Fn(f, validate)) => {
            format!("{{\n      \"type\": \"Fn\",\n      \"data\": [{}, {}]\n    }}", json_str(f), validate)
        }
    }
}

fn json_str(s: &str) -> String {
    let escaped = s.replace('\\', "\\\\")
        .replace('"', "\\\"")
        .replace('\n', "\\n")
        .replace('\r', "\\r")
        .replace('\t', "\\t");
    format!("\"{}\"", escaped)
}

fn serde_json_like() -> String {
    String::new()
}
