pub fn argc_export(script_path: &str, outpath: Option<&str>) -> Result<(), String> {
    let content = fs::read_to_string(script_path)
        .map_err(|e| format!("Error reading {}: {}", script_path, e))?;

    let script_name = Path::new(script_path)
        .file_stem()
        .and_then(|s| s.to_str())
        .unwrap_or(script_path);

    let cmd = parser::parse_script(&content, script_name);

    let json = export_command_to_json(&cmd, true);

    if let Some(out) = outpath {
        fs::write(out, &json).map_err(|e| format!("Error writing {}: {}", out, e))?;
    } else {
        println!("{}", json);
    }

    Ok(())
}

fn export_command_to_json(cmd: &Command, is_root: bool) -> String {
    let mut obj = serde_json_like();

    // Build JSON manually
    export_cmd_to_json_str(cmd, is_root, 0)
}

fn export_cmd_to_json_str(cmd: &Command, is_root: bool, indent: usize) -> String {
    let ind = "  ".repeat(indent);
    let ind2 = "  ".repeat(indent + 1);

    let mut parts = Vec::new();

    // name
    parts.push(format!("{}\"name\": {}", ind2, json_str(&cmd.name)));

    // describe
    parts.push(format!("{}\"describe\": {}", ind2, json_str(&cmd.describe)));

    // version
    let version = cmd.version.as_deref().map(|v| format!("\"{}\"", v)).unwrap_or("null".to_string());
    parts.push(format!("{}\"version\": {}", ind2, version));

    // aliases
    let aliases: Vec<String> = cmd.aliases.iter().map(|a| json_str(a)).collect();
    parts.push(format!("{}\"aliases\": [{}]", ind2, aliases.join(", ")));

    // flag_options
    let fo_strs: Vec<String> = cmd.flag_options.iter()
        .map(|fo| export_flag_option_to_json(fo, indent + 1))
        .collect();
    parts.push(format!("{}\"flag_options\": [\n{}\n{}]", 
        ind2,
        fo_strs.join(",\n"),
        ind2));

    // positionals
    let pos_strs: Vec<String> = cmd.positionals.iter()
        .map(|p| export_positional_to_json(p, indent + 1))
        .collect();
    parts.push(format!("{}\"positionals\": [{}{}{}]",
        ind2,
        if pos_strs.is_empty() { "" } else { "\n" },
        pos_strs.join(",\n"),
        if pos_strs.is_empty() { "" } else { &format!("\n{}", ind2) }
    ));

    // envs
    let env_strs: Vec<String> = cmd.envs.iter()
        .map(|e| export_env_to_json(e, indent + 1))
        .collect();
    parts.push(format!("{}\"envs\": [{}{}{}]",
        ind2,
        if env_strs.is_empty() { "" } else { "\n" },
        env_strs.join(",\n"),
        if env_strs.is_empty() { "" } else { &format!("\n{}", ind2) }
    ));

    // subcommands
    let sub_strs: Vec<String> = cmd.subcommands.iter()
        .map(|s| export_cmd_to_json_str(s, false, indent + 1))
        .collect();
    parts.push(format!("{}\"subcommands\": [{}{}{}]",
        ind2,
        if sub_strs.is_empty() { "" } else { "\n" },
        sub_strs.join(",\n"),
        if sub_strs.is_empty() { "" } else { &format!("\n{}", ind2) }
    ));

    // Add metadata flags
    if is_root {
        if cmd.metadata.dotenv.is_some() {
            let env_file = cmd.metadata.dotenv.as_deref().unwrap_or("");
            let ef = if env_file.is_empty() { ".env" } else { env_file };
            parts.push(format!("{}\"dotenv\": {}", ind2, json_str(ef)));
        }
        if cmd.metadata.combine_shorts {
            parts.push(format!("{}\"combine_shorts\": true", ind2));
        }
        if cmd.metadata.inherit_flag_options {
            parts.push(format!("{}\"inherit_flag_options\": true", ind2));
        }

        // metadata object
        let mut meta_parts = Vec::new();
        for (name, value) in &cmd.metadata.raw {
            let val = if value.is_empty() {
                "null".to_string()
            } else {
                json_str(value)
            };
            meta_parts.push(format!("{}\"{}\": {}", "    ".repeat(indent + 2), name, val));
        }
        if !meta_parts.is_empty() {
            parts.push(format!("{}\"metadata\": {{\n{}\n{}}}", 
                ind2,
                meta_parts.join(",\n"),
                ind2));
        }
    } else {
        if !cmd.metadata.raw.is_empty() {
            // For subcommands, only show relevant metadata
            let mut meta_parts = Vec::new();
            for (name, value) in &cmd.metadata.raw {
                let val = if value.is_empty() {
                    "null".to_string()
                } else {
                    json_str(value)
                };
                meta_parts.push(format!("{}\"{}\": {}", "    ".repeat(indent + 2), name, val));
            }
            parts.push(format!("{}\"metadata\": {{\n{}\n{}}}", 
                ind2,
                meta_parts.join(",\n"),
                ind2));
        }
    }

    // command_fn
    let fn_val = cmd.command_fn.as_deref().map(|f| json_str(f)).unwrap_or("null".to_string());
    parts.push(format!("{}\"command_fn\": {}", ind2, fn_val));

    format!("{}{{\n{}\n{}}}", ind, parts.join(",\n"), ind)
}

fn export_flag_option_to_json(fo: &FlagOption, indent: usize) -> String {
    let ind = "  ".repeat(indent);
    let ind2 = "  ".repeat(indent + 1);

    let mut parts = Vec::new();

    parts.push(format!("{}\"id\": {}", ind2, json_str(&fo.id)));

    let long = fo.long_name.as_deref().map(|n| json_str(n)).unwrap_or("null".to_string());
    parts.push(format!("{}\"long_name\": {}", ind2, long));

    let short = fo.short_name.as_deref().map(|n| json_str(n)).unwrap_or("null".to_string());
    parts.push(format!("{}\"short_name\": {}", ind2, short));

    parts.push(format!("{}\"describe\": {}", ind2, json_str(&fo.describe)));

    parts.push(format!("{}\"flag\": {}", ind2, fo.is_flag));

    let notations: Vec<String> = fo.notations.iter().map(|n| json_str(n)).collect();
    parts.push(format!("{}\"notations\": [{}]", ind2, notations.join(", ")));

    parts.push(format!("{}\"required\": {}", ind2, fo.required));
    parts.push(format!("{}\"multiple_values\": {}", ind2, fo.multiple_values));
    parts.push(format!("{}\"multiple_occurs\": {}", ind2, fo.multiple_occurs));
    parts.push(format!("{}\"num_args\": [\n{}{},\n{}{}\n{}]",
        ind2,
        ind2, "  ", fo.num_args.0,
        ind2, "  ", fo.num_args.1,
        ind2));

    let delim = fo.delimiter.map(|c| format!("\"{}\"", c)).unwrap_or("null".to_string());
    parts.push(format!("{}\"delimiter\": {}", ind2, delim));

    parts.push(format!("{}\"terminated\": {}", ind2, fo.terminated));
    parts.push(format!("{}\"prefixed\": {}", ind2, fo.prefixed));
    parts.push(format!("{}\"assigned\": {}", ind2, fo.assigned));

    let default = export_default_to_json(&fo.default);
    parts.push(format!("{}\"default\": {}", ind2, default));

    let choice = export_choice_to_json(&fo.choice);
    parts.push(format!("{}\"choice\": {}", ind2, choice));

    let env = fo.env.as_deref().map(|e| json_str(e)).unwrap_or("null".to_string());
    parts.push(format!("{}\"env\": {}", ind2, env));

    parts.push(format!("{}\"inherited\": {}", ind2, fo.inherited));

    format!("{}{{\n{}\n{}}}", ind, parts.join(",\n"), ind)
}

fn export_positional_to_json(pos: &Positional, indent: usize) -> String {
    let ind = "  ".repeat(indent);
    let ind2 = "  ".repeat(indent + 1);

    let mut parts = Vec::new();

    parts.push(format!("{}\"id\": {}", ind2, json_str(&pos.id)));
    parts.push(format!("{}\"describe\": {}", ind2, json_str(&pos.describe)));
    parts.push(format!("{}\"notation\": {}", ind2, json_str(&pos.notation)));
    parts.push(format!("{}\"required\": {}", ind2, pos.required));
    parts.push(format!("{}\"multiple\": {}", ind2, pos.multiple));

    let delim = pos.delimiter.map(|c| format!("\"{}\"", c)).unwrap_or("null".to_string());
    parts.push(format!("{}\"delimiter\": {}", ind2, delim));

