    parts.push(format!("{}\"default\": {}", ind2, default));

    let choice = export_choice_to_json(&pos.choice);
    parts.push(format!("{}\"choice\": {}", ind2, choice));

    let env = pos.env.as_deref().map(|e| json_str(e)).unwrap_or("null".to_string());
    parts.push(format!("{}\"env\": {}", ind2, env));

    format!("{}{{\n{}\n{}}}", ind, parts.join(",\n"), ind)
}

fn export_env_to_json(env: &EnvDef, indent: usize) -> String {
    let ind = "  ".repeat(indent);
    let ind2 = "  ".repeat(indent + 1);

    let mut parts = Vec::new();

    parts.push(format!("{}\"id\": {}", ind2, json_str(&env.id)));
    parts.push(format!("{}\"describe\": {}", ind2, json_str(&env.describe)));
    parts.push(format!("{}\"required\": {}", ind2, env.required));

    let default = export_default_to_json(&env.default);
    parts.push(format!("{}\"default\": {}", ind2, default));

    let choice = export_choice_to_json(&env.choice);
    parts.push(format!("{}\"choice\": {}", ind2, choice));

    parts.push(format!("{}\"inherited\": {}", ind2, env.inherited));

    format!("{}{{\n{}\n{}}}", ind, parts.join(",\n"), ind)
}

fn export_default_to_json(default: &Option<DefaultValue>) -> String {
    match default {
        None => "null".to_string(),
        Some(DefaultValue::Value(v)) => format!("{{\n      \"type\": \"Value\",\n      \"value\": {}\n    }}", json_str(v)),
        Some(DefaultValue::Fn(f)) => format!("{{\n      \"type\": \"Fn\",\n      \"value\": {}\n    }}", json_str(f)),
    }
}

fn export_choice_to_json(choice: &Option<ChoiceValue>) -> String {
    match choice {
        None => "null".to_string(),
        Some(ChoiceValue::Values(vals)) => {
            let v: Vec<String> = vals.iter().map(|v| json_str(v)).collect();
            format!("{{\n      \"type\": \"Values\",\n      \"data\": [{}]\n    }}", v.join(", "))
        }
        Some(ChoiceValue::Fn(f, validate)) => {
            format!("{{\n      \"type\": \"Fn\",\n      \"data\": [{}, {}]\n    }}", json_str(f), validate)
        }
    }
}

fn json_str(s: &str) -> String {
    let escaped = s.replace('\\', "\\\\")
        .replace('"', "\\\"")
        .replace('\n', "\\n")
        .replace('\r', "\\r")
        .replace('\t', "\\t");
    format!("\"{}\"", escaped)
}

fn serde_json_like() -> String {
    String::new()
}
