    }

    // Help subcommand
    code.push_str("        help)\n");
    code.push_str("            local help_arg=\"${argc__args[$((_argc_index + 1))]:-}\"\n");
    code.push_str("            case \"$help_arg\" in\n");
    for sub in &cmd.subcommands {
        let patterns: Vec<String> = std::iter::once(sub.name.clone())
            .chain(sub.aliases.iter().cloned())
            .collect();
        code.push_str(&format!("            {})\n                _argc_usage_{}\n                ;;\n", 
            patterns.join(" | "), sub.name));
    }
    code.push_str("            \"\")\n                _argc_usage\n                ;;\n");
    code.push_str("            *)\n                _argc_die \"error: invalid value \\`$help_arg\\` for \\`<command>\\`\"$'\\n'\"  [possible values: $_argc_subcmds]\"\n                ;;\n");
    code.push_str("            esac\n");
    code.push_str("            ;;\n");

    // Default
    if cmd.subcommands.is_empty() {
        code.push_str("        *)\n            argc__positionals+=(\"$_argc_item\")\n            _argc_index=$((_argc_index + 1))\n            ;;\n");
    } else {
        code.push_str(&format!("        *)\n            _argc_die \"error: \\`{}\\` requires a subcommand but one was not provided\"$'\\n'\"  [subcommands: $_argc_subcmds]\"\n            ;;\n", cmd.name));
    }

    code.push_str("        esac\n");
    code.push_str("    done\n");
    code.push_str("    if [[ -n \"${_argc_action:-}\" ]]; then\n");
    code.push_str("        $_argc_action\n");
    code.push_str("    else\n");

    if let Some(ref fn_name) = cmd.command_fn {
        code.push_str(&format!("        argc__fn={}\n", fn_name));
    } else if !cmd.subcommands.is_empty() {
        code.push_str("        _argc_usage\n");
    }

    code.push_str("    fi\n");
    code.push_str("}\n\n");

    // Generate parse functions for subcommands
    for sub in &cmd.subcommands {
        code.push_str(&generate_subcmd_parse_fn(sub, cmd.name.as_str()));
    }

    code
}

fn generate_subcmd_parse_fn(cmd: &crate::command::Command, parent_name: &str) -> String {
    let mut code = String::new();
    let fn_name = &cmd.name;

    code.push_str(&format!("_argc_parse_{fn_name}() {{\n"));
    code.push_str("    local _argc_key _argc_action\n");
    code.push_str("    local _argc_subcmds=\"\"\n");

    code.push_str("    while [[ $_argc_index -lt $_argc_len ]]; do\n");
    code.push_str("        _argc_item=\"${argc__args[_argc_index]}\"\n");
    code.push_str("        _argc_key=\"${_argc_item%%=*}\"\n");
    code.push_str("        case \"$_argc_key\" in\n");

    // Help
    code.push_str(&format!("        --help | -help | -h)\n            _argc_usage_{fn_name}\n            ;;\n"));

    // Dash separator
    code.push_str("        --)\n");
    code.push_str("            _argc_dash=\"${#argc__positionals[@]}\"\n");
    code.push_str("            argc__positionals+=(\"${argc__args[@]:$((_argc_index + 1))}\")\n");
    code.push_str("            _argc_index=$_argc_len\n");
    code.push_str("            break\n");
    code.push_str("            ;;\n");

    // Options/flags
    for fo in &cmd.flag_options {
        if matches!(fo.id.as_str(), "help" | "version") { continue; }
        code.push_str(&generate_option_case(fo));
    }

    // Default
    code.push_str("        *)\n");
    code.push_str("            if _argc_maybe_flag_option \"-\" \"$_argc_item\"; then\n");
    code.push_str("                _argc_die \"error: unexpected argument \\`$_argc_key\\` found\"\n");
    code.push_str("            fi\n");
    code.push_str("            argc__positionals+=(\"$_argc_item\")\n");
    code.push_str("            _argc_index=$((_argc_index + 1))\n");
    code.push_str("            ;;\n");

    code.push_str("        esac\n");
    code.push_str("    done\n");

    // Post-parse: defaults, validation, etc.
    code.push_str("    if [[ -n \"${_argc_action:-}\" ]]; then\n");
    code.push_str("        $_argc_action\n");
    code.push_str("    else\n");

    if let Some(ref fn_name_str) = cmd.command_fn {
        code.push_str(&format!("        argc__fn={fn_name_str}\n"));
        code.push_str("        if [[ \"${argc__positionals[0]:-}\" == \"help\" ]] && [[ \"${#argc__positionals[@]}\" -eq 1 ]]; then\n");
        code.push_str(&format!("            _argc_usage_{fn_name}\n"));
        code.push_str("        fi\n");

        // Add defaults
        for fo in &cmd.flag_options {
            if matches!(fo.id.as_str(), "help" | "version") { continue; }
            if fo.is_flag { continue; }
            if let Some(ref default) = fo.default {
                let var = format!("argc_{}", fo.id);
                match default {
                    crate::command::DefaultValue::Value(v) => {
                        code.push_str(&format!("        if [[ -z \"${{{var}:-}}\" ]]; then\n"));
                        code.push_str(&format!("            {var}={v}\n"));
                        code.push_str("        fi\n");
                    }
                    crate::command::DefaultValue::Fn(f) => {
                        code.push_str(&format!("        if [[ -z \"${{{var}:-}}\" ]]; then\n"));
                        code.push_str(&format!("            {var}=\"$({f})\"\n"));
                        code.push_str("        fi\n");
                    }
                }
            }
        }

        // Handle positionals
        if !cmd.positionals.is_empty() {
            let multi_params: Vec<_> = cmd.positionals.iter().map(|p| if p.multiple { "1" } else { "0" }).collect();
            code.push_str(&format!("        _argc_match_positionals {}\n", multi_params.join(" ")));

            for (i, pos) in cmd.positionals.iter().enumerate() {
                let var = format!("argc_{}", pos.id.replace("...", "___").replace('-', "_").replace('.', "_"));
                code.push_str(&format!("        local values_index values_size\n"));
                code.push_str(&format!("        IFS=: read -r values_index values_size <<<\"${{_argc_match_positionals_values[{}]:-}}\"\n", i));
                code.push_str("        if [[ -n \"$values_index\" ]]; then\n");
                if pos.multiple {
                    code.push_str(&format!("            {var}=(\"${{argc__positionals[@]:$values_index:$values_size}}\")\n"));
                } else {
                    code.push_str(&format!("            {var}=\"${{argc__positionals[values_index]}}\"\n"));
                }
                code.push_str("        else\n");
                if pos.required {
                    let notation = &pos.notation;
                    code.push_str(&format!("            _argc_die \"error: the required environments \\`<{notation}>\\` were not provided\"\n"));
                }
                code.push_str("        fi\n");
            }
        }

        // Required options
        let required_fos: Vec<_> = cmd.flag_options.iter()
            .filter(|f| f.required && !matches!(f.id.as_str(), "help" | "version"))
            .collect();
        if !required_fos.is_empty() {
            let items: Vec<String> = required_fos.iter().map(|f| {
                let var = format!("argc_{}", f.id);
                let render = render_option_name_for_build(f);
                format!("'{var}:{render}'")
            }).collect();
            code.push_str(&format!("        _argc_required_flag_options+=({}\n)\n", items.join(" ")));
        }
    }

    code.push_str("    fi\n");
    code.push_str("}\n\n");

    code
}

fn render_option_name_for_build(fo: &crate::command::FlagOption) -> String {
    let name = fo.long_name.as_deref().or(fo.short_name.as_deref()).unwrap_or("");
    if fo.is_flag || fo.notations.is_empty() {
        return name.to_string();
    }
    let n = fo.notations.first().unwrap();
    if fo.multiple_occurs {
        if fo.required {
            format!("{} <{}>...", name, n)
        } else {
            format!("{} [{}]...", name, n)
        }
    } else {
        format!("{} <{}>", name, n)
    }
}

fn generate_option_case(fo: &crate::command::FlagOption) -> String {
    let mut code = String::new();

    let long = fo.long_name.as_deref().unwrap_or("");
    let short = fo.short_name.as_deref();

    let patterns = if let Some(s) = short {
        format!("{} | {}", long, s)
    } else {
        long.to_string()
    };

    code.push_str(&format!("        {})\n", patterns));

    let var = format!("argc_{}", fo.id);

    if fo.is_flag {
        code.push_str("            if [[ \"$_argc_item\" == *=* ]]; then\n");
        code.push_str(&format!("                _argc_die \"error: flag \\`{}\\` don't accept any value\"\n", long));
        code.push_str("            fi\n");
        code.push_str("            _argc_index=$((_argc_index + 1))\n");

        if fo.multiple_occurs {
            code.push_str(&format!("            if [[ -n \"${{{var}:-}}\" ]]; then\n"));
            code.push_str(&format!("                {var}=$(({var} + 1))\n"));
            code.push_str("            else\n");
            code.push_str(&format!("                {var}=1\n"));
            code.push_str("            fi\n");
        } else {
            code.push_str(&format!("            if [[ -n \"${{{var}:-}}\" ]]; then\n"));
            code.push_str(&format!("                _argc_die \"error: the argument \\`{}\\` cannot be used multiple times\"\n", long));
            code.push_str("            else\n");
            code.push_str(&format!("                {var}=1\n"));
            code.push_str("            fi\n");
        }
    } else {
        let notation = render_option_name_for_build(fo);
        let (min, max) = fo.num_args;
        let sign = fo.sign();
        let delim = fo.delimiter.map(|c| c.to_string()).unwrap_or_default();

        code.push_str(&format!("            _argc_take_args \"{}\" {} {} \"{}\" \"{}\"\n", notation, min, max, sign, delim));
        code.push_str("            _argc_index=$((_argc_index + _argc_take_args_len + 1))\n");

        if fo.multiple_occurs {
            code.push_str(&format!("            {var}+=(\"${{_argc_take_args_values[@]}}\")\n"));
        } else {
            code.push_str(&format!("            if [[ -z \"${{{var}:-}}\" ]]; then\n"));
            code.push_str(&format!("                {var}=\"${{_argc_take_args_values[0]:-}}\"\n"));
            code.push_str("            else\n");
            code.push_str(&format!("                _argc_die \"error: the argument \\`{}\\` cannot be used multiple times\"\n", long));
            code.push_str("            fi\n");
        }
    }

    code.push_str("            ;;\n");
    code
}

fn generate_helper_fns(cmd: &crate::command::Command) -> String {
    let has_choices = has_choices_recursive(cmd);
    let has_dotenv = cmd.metadata.dotenv.is_some();

    let mut code = String::new();

    // _argc_take_args
    code.push_str(TAKE_ARGS_FN);

    // _argc_match_positionals (only if needed)
    if has_any_positionals(cmd) {
        code.push_str(MATCH_POSITIONALS_FN);
    }

    // _argc_validate_choices (only if needed)
    if has_choices {
        code.push_str(VALIDATE_CHOICES_FN);
    }

    // _argc_maybe_flag_option
    code.push_str(MAYBE_FLAG_OPTION_FN);

    // _argc_require_params
    code.push_str(REQUIRE_PARAMS_FN);

    // _argc_load_dotenv
    if has_dotenv {
        code.push_str(LOAD_DOTENV_FN);
    }

    // _argc_die
    code.push_str(DIE_FN);

    code
}

fn has_choices_recursive(cmd: &crate::command::Command) -> bool {
    cmd.flag_options.iter().any(|f| f.choice.is_some())
        || cmd.positionals.iter().any(|p| p.choice.is_some())
        || cmd.subcommands.iter().any(|s| has_choices_recursive(s))
}

fn has_any_positionals(cmd: &crate::command::Command) -> bool {
    !cmd.positionals.is_empty()
        || cmd.subcommands.iter().any(|s| has_any_positionals(s))
}

const TAKE_ARGS_FN: &str = r#"_argc_take_args() {
    _argc_take_args_values=()
    _argc_take_args_len=0
    local param="$1" min="$2" max="$3" signs="$4" delimiter="$5"
    if [[ "$min" -eq 0 ]] && [[ "$max" -eq 0 ]]; then
        return
    fi
    local _argc_take_index=$((_argc_index + 1)) _argc_take_value
    if [[ "$_argc_item" == *=* ]]; then
        _argc_take_args_values=("${_argc_item##*=}")
    else
        while [[ $_argc_take_index -lt $_argc_len ]]; do
            _argc_take_value="${argc__args[_argc_take_index]}"
            if _argc_maybe_flag_option "$signs" "$_argc_take_value"; then
                if [[ "${#_argc_take_value}" -gt 1 ]]; then
                    break
                fi
            fi
            _argc_take_args_values+=("$_argc_take_value")
            _argc_take_args_len=$((_argc_take_args_len + 1))
            if [[ "$_argc_take_args_len" -ge "$max" ]]; then
                break
            fi
            _argc_take_index=$((_argc_take_index + 1))
        done
    fi
    if [[ "${#_argc_take_args_values[@]}" -lt "$min" ]]; then
        _argc_die "error: incorrect number of values for \`$param\`"
    fi
    if [[ -n "$delimiter" ]] && [[ "${#_argc_take_args_values[@]}" -gt 0 ]]; then
        local item values arr=()
        for item in "${_argc_take_args_values[@]}"; do
            IFS="$delimiter" read -r -a values <<<"$item"
            arr+=("${values[@]}")
        done
        _argc_take_args_values=("${arr[@]}")
    fi
}

"#;

const MATCH_POSITIONALS_FN: &str = r#"_argc_match_positionals() {
    _argc_match_positionals_values=()
    _argc_match_positionals_len=0
    local params=("$@")
    local args_len="${#argc__positionals[@]}"
    if [[ $args_len -eq 0 ]]; then
        return
    fi
    local params_len=$# arg_index=0 param_index=0
    while [[ $param_index -lt $params_len && $arg_index -lt $args_len ]]; do
        local takes=0
        if [[ "${params[param_index]}" -eq 1 ]]; then
            if [[ $param_index -eq 0 ]] &&
                [[ ${_argc_dash:-} -gt 0 ]] &&
                [[ $params_len -eq 2 ]] &&
                [[ "${params[$((param_index + 1))]}" -eq 1 ]] \
                ; then
                takes=${_argc_dash:-}
            else
                local arg_diff=$((args_len - arg_index)) param_diff=$((params_len - param_index))
                if [[ $arg_diff -gt $param_diff ]]; then
                    takes=$((arg_diff - param_diff + 1))
                else
                    takes=1
                fi
            fi
        else
            takes=1
        fi
        _argc_match_positionals_values+=("$arg_index:$takes")
        arg_index=$((arg_index + takes))
        param_index=$((param_index + 1))
    done
    if [[ $arg_index -lt $args_len ]]; then
        _argc_match_positionals_values+=("$arg_index:$((args_len - arg_index))")
    fi
    _argc_match_positionals_len=${#_argc_match_positionals_values[@]}
    if [[ $params_len -gt 0 ]] && [[ $_argc_match_positionals_len -gt $params_len ]]; then
        local index="${_argc_match_positionals_values[params_len]%%:*}"
        _argc_die "error: unexpected argument \`${argc__positionals[index]}\` found"
    fi
}

"#;

const VALIDATE_CHOICES_FN: &str = r#"_argc_validate_choices() {
    local render_name="$1" raw_choices="$2" choices item choice concated_choices=""
    while IFS= read -r line; do
        choices+=("$line")
    done <<<"$raw_choices"
    for choice in "${choices[@]}"; do
        if [[ -z "$concated_choices" ]]; then
            concated_choices="$choice"
        else
            concated_choices="$concated_choices, $choice"
        fi
    done
    for item in "${@:3}"; do
        local pass=0 choice
        for choice in "${choices[@]}"; do
            if [[ "$item" == "$choice" ]]; then
                pass=1
            fi
        done
        if [[ $pass -ne 1 ]]; then
            _argc_die "error: invalid value \`$item\` for $render_name"$'\n'"  [possible values: $concated_choices]"
        fi
    done
}

"#;

const MAYBE_FLAG_OPTION_FN: &str = r#"_argc_maybe_flag_option() {
    local signs="$1" arg="$2"
    if [[ -z "$signs" ]]; then
        return 1
    fi
    local cond=false
    if [[ "$signs" == *"+"* ]]; then
        if [[ "$arg" =~ ^\+[^+].* ]]; then
            cond=true
        fi
    elif [[ "$arg" == -* ]]; then
        if (( ${#arg} < 3 )) || [[ ! "$arg" =~ ^---..* ]]; then
            cond=true
        fi
    fi
    if [[ "$cond" == "false" ]]; then
        return 1
    fi
    local value="${arg%%=*}"
    if [[ "$value" =~ [[:space:]] ]]; then
        return 1
    fi
    return 0
}

"#;

const REQUIRE_PARAMS_FN: &str = r#"_argc_require_params() {
    local message="$1" missed_envs="" item name render_name
    for item in "${@:2}"; do
        name="${item%%:*}"
        render_name="${item##*:}"
        if [[ -z "${!name:-}" ]]; then
            missed_envs="$missed_envs"$'\n'"  $render_name"
        fi
    done
    if [[ -n "${missed_envs}" ]]; then
        _argc_die "$message$missed_envs"
    fi
}

"#;

const LOAD_DOTENV_FN: &str = r#"_argc_load_dotenv() {
    local env_file="$1" env_vars=""
    if [[ -f "$env_file" ]]; then
        while IFS='=' read -r key value; do
            if [[ "$key" == $'#'* ]] || [[ -z "$key" ]]; then
                continue
            fi
            if [[ -z "${!key+x}" ]]; then
                env_vars="$env_vars $key=$value"
            fi
        done < <(cat "$env_file"; echo "")
        if [[ -n "$env_vars" ]]; then
            eval "export $env_vars"
        fi
    fi
}

"#;

const DIE_FN: &str = r#"_argc_die() {
    if [[ $# -eq 0 ]]; then
        cat
    else
        echo "$*" >&2
    fi
    exit 1
}

"#;
EOF
