fn generate_bash_completions(cmds: &str) -> String {
    format!(r#"_argc_completer() {{
    declare -a _argc_completer_words
    _argc_completer_parse_line

    export COMP_WORDBREAKS
    while IFS=$'\n' read -r line; do
        COMPREPLY+=( "$line" )
    done < <(argc --argc-compgen bash "" "${{_argc_completer_words[@]}}" 2>/dev/null)
}}

_argc_completer_parse_line() {{
    local line len i char prev_char word unbalance
    line="${{COMP_LINE:0:$COMP_POINT}}"
    len="${{#line}}"

    for ((i=0; i<len; i++)); do
        char="${{line:i:1}}"
        if [[ -n "$unbalance" ]]; then
            word="$word$char"
            if [[  "$unbalance" == "$char" ]]; then
                unbalance=""
            fi
        elif [[ "$char" == " " ]]; then
            if [[ "$prev_char" == "\\" ]]; then
                word="$word$char"
            elif [[ -n "$word" ]]; then
                _argc_completer_words+=( "$word" )
                word=""
            fi
        elif [[ "$char" == "'" || "$char" == '"' ]]; then
            word="$word$char"
            unbalance="$char"
        elif [[ "$char" == "\\" ]]; then
            if [[ "$prev_char" == "\\" ]]; then
                word="$word$char"
            fi
        else
            word="$word$char"
        fi
        prev_char="$char"
    done

    _argc_completer_words+=( "$word" )
}}

complete -F _argc_completer -o nospace -o nosort \
    argc {cmds}
"#)
}

fn generate_zsh_completions(cmds: &str) -> String {
    format!(r#"_argc_completer() {{
    local new_words
    _argc_completer_reassemble_words

    local candidates=() values=() displays=() colors display_value
    while IFS=$'\n' read -r line; do
        if [[ "$line" == "" ]]; then line=$'\0'; fi
        candidates+=( "$line" )
    done < <(argc --argc-compgen zsh $'\0' $new_words 2>/dev/null)
    for candidate in ${{candidates[@]}}; do
        IFS=$'\t' read -r value display color_key color <<< "$candidate"
        colors="$colors:=(#b)($color_key)([ ]## -- *)=0=$color=2:=(#b)($color_key)=0=$color"
        values+=( "${{value}}" )
        displays+=( "$display" )
    done
    zstyle ":completion:${{curcontext}}:*" list-colors "${{colors:1}}:=(#b)(-- *)=0=2"
    _describe "" displays values -Q -S '' -o nosort
}}

_argc_completer_reassemble_words() {{
    local i cword
    new_words=()
    for ((i=1; i<=$CURRENT; i++)); do
        cword="$words[$i]"
        if [[ "$cword" == "" ]]; then
            new_words+=( $'\0' )
        else
            if [[ "$cword" == *"\\"* ]]; then
                local j char next_char cword_len word
                cword_len="${{#cword}}"
                for ((j=0; j<$cword_len; j++)); do
                    char="${{cword:$j:1}}"
                    if [[ "$char" == "\\" ]]; then
                        next_char="${{cword:$((j+1)):1}}"
                        if [[ "$next_char" == "\\" ]]; then
                            word="$word$char"
                            j=$((j+1))
                        fi
                    else
                        word="$word$char"
                    fi
                done
                cword="$word"
            fi
            new_words+=( "$cword" )
        fi
    done
}}

compdef _argc_completer \
    argc {cmds}
"#)
}

fn generate_fish_completions(cmds: &str) -> String {
    format!(r#"function _argc_completer
    set -g _argc_completer_words
    _argc_completer_parse_line

    argc --argc-compgen fish "" $_argc_completer_words
end

function _argc_completer_parse_line
    set -l line (commandline -cp) 
    set -l word ''
    set -l unbalance ''
    set -l prev_char ''

    for i in (seq (string length -- $line))
        set -l char (string sub -s $i -l 1 -- $line)

        if test -n "$unbalance"
            set word "$word$char"
            if test "$unbalance" = "$char"
                set unbalance ''
            end
        else if test "$char" = ' '
            if test "$prev_char" = '\\'
                set word "$word$char"
            else if test -n "$word"
                set -a _argc_completer_words "$word"
                set word ''
            end
        else if test "$char" = "'" -o "$char" = '"'
            set word "$word$char"
            set unbalance "$char"
        else if test "$char" = "\\"
            if test "$prev_char" = "\\"
                set word "$word$char"
            end
        else
            set word "$word$char"
        end
        set prev_char "$char"
    end

    set -a _argc_completer_words "$word"
end

complete -c argc -f -a "(_argc_completer)"
{fish_cmds}
"#, fish_cmds = cmds.split_whitespace().map(|cmd| {
    format!("complete -c {} -f -a \"(_argc_completer)\"", cmd)
}).collect::<Vec<_>>().join("\n"))
}

fn generate_powershell_completions(cmds: &str) -> String {
    let cmd_registrations = cmds.split_whitespace().map(|cmd| {
        format!("Register-ArgumentCompleter -Native -CommandName {} -ScriptBlock $_argc_completer", cmd)
    }).collect::<Vec<_>>().join("\n");

    format!(r#"using namespace System.Management.Automation

$_argc_completer = {{
    param($wordToComplete, $commandAst, $cursorPosition)
    $words = @($commandAst.CommandElements | Where {{ $_.Extent.StartOffset -lt $cursorPosition }} | ForEach-Object {{
        $word =  $_.ToString() 
        if ($word.Length -gt 2) {{
            if (($word.StartsWith('"') -and $word.EndsWith('"')) -or ($word.StartsWith("'") -and $word.EndsWith("'"))) {{
                $word = $word.Substring(1, $word.Length - 2)
            }}
        }}
        return $word
    }})
    $emptyS = ''
    if ($PSVersionTable.PSVersion.Major -eq 5) {{
        $emptyS = '""'
    }}
    $lastElemIndex = -1
    if ($words.Count -lt $commandAst.CommandElements.Count) {{
        $lastElemIndex = $words.Count - 1
    }}
    if ($commandAst.CommandElements[$lastElemIndex].Extent.EndOffset -lt $cursorPosition) {{
        $words += $emptyS
    }}
    @((argc --argc-compgen powershell $emptyS $words) -split "`n") | ForEach-Object {{
        $parts = ($_ -split "`t")
        if ($parts[1] -eq "1") {{
            $value = $parts[0] + " "
        }} else {{
            $value = $parts[0]
        }}
        [System.Management.Automation.CompletionResult]::new($value, $parts[2], 'ParameterValue', $parts[3])
    }}
}}

Register-ArgumentCompleter -Native -CommandName argc -ScriptBlock $_argc_completer
{cmd_registrations}
"#)
}

fn generate_nushell_completions(cmds: &str) -> String {
