pub fn argc_compgen(shell: &str, script_path: &str, args: &[&str]) -> Result<(), String> {
    // Generate completion candidates
    // args is: [script_name, subcommand?, ..., current_word]

    use std::fs;
    use std::path::Path;

    let content = fs::read_to_string(script_path)
        .unwrap_or_default();

    let script_name = Path::new(script_path)
        .file_stem()
        .and_then(|s| s.to_str())
        .unwrap_or(script_path);

    let cmd = crate::parser::parse_script(&content, script_name);

    // Navigate to the right subcommand
    let current = args.last().copied().unwrap_or("");
    let preceding = if args.len() > 1 { &args[..args.len()-1] } else { &[] as &[&str] };

    let candidates = generate_candidates(&cmd, preceding, current, shell);

    for (value, describe) in &candidates {
        match shell {
            "bash" => println!("{} ", value),
            "fish" => {
                if describe.is_empty() {
                    println!("{}", value);
                } else {
                    println!("{}\t{}", value, describe);
                }
            }
            "zsh" => {
                // value  display:Description display_val color_key color
                let display = if describe.is_empty() {
                    format!("{}:{}", value, value)
                } else {
                    format!("{}:{}", value, describe)
                };
                println!("{} \t{}\t{}\t35", value, display, value);
            }
            "nushell" => {
                println!("{} \t{}", value, describe);
            }
            "powershell" => {
                println!("{}\t1\t{}\t{}\t35", value, value, describe);
            }
            "elvish" => {
                println!("{}\t1\t{}\t{}\tmagenta", value, value, describe);
            }
            "xonsh" => {
                println!("{}\t1\t{}\t{}", value, value, describe);
            }
            "tcsh" => {
                let desc_no_spaces = describe.replace(' ', "\u{2800}");
                let val_no_spaces = value.replace(' ', "\u{2800}");
                if describe.is_empty() {
                    println!("{}", val_no_spaces);
                } else {
                    println!("{}\u{2800}({})", val_no_spaces, desc_no_spaces);
                }
            }
            _ => println!("{}", value),
        }
    }

    Ok(())
}

fn generate_candidates(cmd: &crate::command::Command, preceding: &[&str], current: &str, shell: &str) -> Vec<(String, String)> {
    use crate::command::*;

    // Skip the script name (preceding[0])
    let args = if preceding.is_empty() { &[] as &[&str] } else { &preceding[1..] };

    // Navigate to the correct subcommand
    let target_cmd = navigate_to_subcmd(cmd, args);

    match target_cmd {
        Some(target) => {
            // If current starts with - or +, show options/flags
            if current.starts_with('-') || current.starts_with('+') {
                return get_option_candidates(target, current);
            }

            // If there are subcommands, show them + --help etc.
            if !target.subcommands.is_empty() {
                let mut candidates = Vec::new();
                for sub in &target.subcommands {
                    candidates.push((sub.name.clone(), sub.describe.lines().next().unwrap_or("").to_string()));
                    for alias in &sub.aliases {
                        // Don't show aliases in general list typically
                    }
                }
                candidates.push(("help".to_string(), "Show help for a command".to_string()));
                // Filter by current
                candidates.retain(|(v, _)| v.starts_with(current));
                return candidates;
            }

            // Leaf command - check if previous arg was an option expecting a value
            if let Some(prev) = preceding.last().copied() {
                if let Some(fo) = target.flag_options.iter().find(|f| {
                    f.long_name.as_deref() == Some(prev) || f.short_name.as_deref() == Some(prev)
                }) {
                    if !fo.is_flag {
                        // Show choices if available
                        if let Some(ref choice) = fo.choice {
                            match choice {
                                crate::command::ChoiceValue::Values(vals) => {
                                    return vals.iter()
                                        .filter(|v| v.starts_with(current))
                                        .map(|v| (v.clone(), String::new()))
                                        .collect();
                                }
                                _ => {}
                            }
                        }
                        // Return file candidates
                        return get_file_candidates(current);
                    }
                }
            }

            // Check positional choices
            if let Some(pos) = target.positionals.first() {
                if let Some(ref choice) = pos.choice {
                    match choice {
                        crate::command::ChoiceValue::Values(vals) => {
                            return vals.iter()
                                .filter(|v| v.starts_with(current))
                                .map(|v| (v.clone(), String::new()))
                                .collect();
                        }
                        _ => {}
                    }
                }
            }

            // Default: options first
            if current.starts_with('-') || current.starts_with('+') {
                return get_option_candidates(target, current);
            }

            // No specific candidates - return empty for subcommand or file candidates for positional
            if target.positionals.is_empty() && target.subcommands.is_empty() {
                return vec![];
            }

            vec![]
        }
        None => vec![],
    }
}

fn navigate_to_subcmd<'a>(cmd: &'a crate::command::Command, args: &[&str]) -> Option<&'a crate::command::Command> {
    if args.is_empty() {
        return Some(cmd);
    }

    let arg = args[0];

    // Null byte is empty string marker (for zsh)
    if arg == "\x00" || arg.is_empty() {
        return Some(cmd);
    }

    // If this arg is a subcommand name
    if let Some(sub) = cmd.subcommands.iter().find(|s| s.name == arg || s.aliases.iter().any(|a| a == arg)) {
        return navigate_to_subcmd(sub, &args[1..]);
    }

    // If this arg looks like an option, skip it and check if next is a value
    if arg.starts_with('-') || arg.starts_with('+') {
        // Try to figure out if this option takes a value
        let fo = cmd.flag_options.iter().find(|f| {
            let key = arg.split('=').next().unwrap_or(arg);
            f.long_name.as_deref() == Some(key) || f.short_name.as_deref() == Some(key)
        });

        if let Some(fo) = fo {
            if !fo.is_flag && !arg.contains('=') {
                // Skip the value too
                return navigate_to_subcmd(cmd, &args[2.min(args.len())..]);
            }
        }
        return navigate_to_subcmd(cmd, &args[1..]);
    }

    // Positional arg or unknown
    Some(cmd)
}

fn get_option_candidates(cmd: &crate::command::Command, current: &str) -> Vec<(String, String)> {
    let mut candidates = Vec::new();
    for fo in &cmd.flag_options {
        if let Some(ref ln) = fo.long_name {
            if ln.starts_with(current) {
                candidates.push((ln.clone(), fo.describe.lines().next().unwrap_or("").to_string()));
            }
        }
    }
    candidates
}

fn get_file_candidates(current: &str) -> Vec<(String, String)> {
    use std::fs;
    use std::path::Path;

    let (dir, prefix) = if current.contains('/') {
        let pos = current.rfind('/').unwrap();
        (&current[..=pos], &current[pos+1..])
    } else {
        (".", current)
    };

    let base_dir = if dir == "." { ".".to_string() } else { dir.to_string() };

    let mut candidates = Vec::new();

    if let Ok(entries) = fs::read_dir(&base_dir) {
        let mut names: Vec<String> = entries
            .filter_map(|e| e.ok())
            .filter_map(|e| {
                let name = e.file_name().to_string_lossy().to_string();
                if name.starts_with(prefix) {
                    let full = if dir == "." {
                        name.clone()
                    } else {
                        format!("{}{}", dir, name)
                    };
                    if e.path().is_dir() {
                        Some(format!("{}/", full))
                    } else {
                        Some(full)
                    }
                } else {
                    None
                }
            })
            .collect();
        names.sort();
        for name in names {
            candidates.push((name, String::new()));
        }
    }

    candidates
}

