use std::fs;
use std::path::Path;
use crate::command::*;
use crate::parser;

pub fn argc_mangen(script_path: &str, outdir: &str) -> Result<(), String> {
    let content = fs::read_to_string(script_path)
        .map_err(|e| format!("Error reading {}: {}", script_path, e))?;

    let script_name = Path::new(script_path)
        .file_stem()
        .and_then(|s| s.to_str())
        .unwrap_or(script_path);

    let cmd = parser::parse_script(&content, script_name);

    fs::create_dir_all(outdir)
        .map_err(|e| format!("Error creating dir {}: {}", outdir, e))?;

    generate_man_pages(&cmd, script_name, outdir, script_name)?;

    Ok(())
}

fn generate_man_pages(cmd: &Command, name: &str, outdir: &str, script_name: &str) -> Result<(), String> {
    let man_text = generate_man_page(cmd, name, script_name);
    let filename = format!("{}/{}.1", outdir, name);
    fs::write(&filename, &man_text)
        .map_err(|e| format!("Error writing {}: {}", filename, e))?;
    eprintln!("saved {}", filename);

    // Generate man pages for subcommands
    for sub in &cmd.subcommands {
        let sub_name = format!("{}-{}", name, sub.name);
        generate_man_pages(sub, &sub_name, outdir, script_name)?;
    }

    Ok(())
}

fn generate_man_page(cmd: &Command, name: &str, script_name: &str) -> String {
    let mut text = String::new();

    let version = cmd.version.as_deref().unwrap_or("0.0.0");
    let upper_name = name.to_uppercase().replace('-', "\\-");

    // TH header
    text.push_str(&format!(".TH {} 1  \"{} {}\" \n", 
        upper_name.replace('.', "_"),
        name, 
        version));

    // NAME section
    let escaped_name = name.replace('-', "\\-");
    let describe = cmd.describe.lines().next().unwrap_or("");
    if describe.is_empty() {
        text.push_str(&format!(".SH NAME\n{}\n", escaped_name));
    } else {
        text.push_str(&format!(".SH NAME\n{} \\- {}\n", escaped_name, man_escape(describe)));
    }

    // SYNOPSIS
    let synopsis = build_synopsis(cmd, name, script_name);
    text.push_str(&format!(".SH SYNOPSIS\n{}\n", synopsis));

    // SUBCOMMANDS (if any)
    if !cmd.subcommands.is_empty() {
        text.push_str(".SH SUBCOMMANDS\n");
        for sub in &cmd.subcommands {
            let sub_name = format!("{}-{}", name, sub.name);
            let escaped_sub = sub_name.replace('-', "\\-");
            let sub_desc = sub.describe.lines().next().unwrap_or("");
            text.push_str(&format!(".TP\n{}(1)\n", escaped_sub));
            if !sub_desc.is_empty() {
                text.push_str(&format!("{}\n", man_escape(sub_desc)));
            }
        }
    }

    // OPTIONS  
    let user_opts: Vec<_> = cmd.flag_options.iter()
        .filter(|f| !matches!(f.id.as_str(), "version"))
        .collect();

    if !user_opts.is_empty() || !cmd.positionals.is_empty() {
        text.push_str(".SH OPTIONS\n");

        // Positionals
        for pos in &cmd.positionals {
            let notation = if pos.required {
                format!("<\\fI{}\\fR>", pos.notation)
            } else {
                format!("[\\fI{}\\fR]", pos.notation)
            };
            text.push_str(&format!(".TP\n{}\n", notation));
            if !pos.describe.is_empty() {
                text.push_str(".br\n");
                text.push_str(&format!("{}\n", man_escape(&pos.describe)));
            }
        }

        // Options/flags
        for fo in &user_opts {
            let opt_str = render_man_option(fo);
            text.push_str(&format!(".TP\n{}\n", opt_str));
            if !fo.describe.is_empty() {
                text.push_str(".br\n");
                text.push_str(&format!("{}\n", man_escape(&fo.describe)));
            }
        }
    }

    text
}

fn build_synopsis(cmd: &Command, name: &str, script_name: &str) -> String {
    let parts: Vec<String> = name.split('-').collect();
    let display_name = parts.join(" ");

    if !cmd.subcommands.is_empty() {
        format!("\\fB{}\\fR <COMMAND>", display_name)
    } else {
        let mut s = format!("\\fB{}\\fR", display_name);

        let has_opts = cmd.flag_options.iter().any(|f| !matches!(f.id.as_str(), "help" | "version"));
        if has_opts {
            s.push_str(" [OPTIONS]");
        }

        for pos in &cmd.positionals {
            s.push_str(" ");
            if pos.required {
                s.push_str(&format!("<{}>", pos.notation));
            } else {
                s.push_str(&format!("[{}]", pos.notation));
            }
        }

        s
    }
}

fn render_man_option(fo: &FlagOption) -> String {
    let long = fo.long_name.as_deref().unwrap_or("");
    let short = fo.short_name.as_deref();
    let escaped_long = man_escape_option(long);

    if fo.is_flag {
        if let Some(s) = short {
            let escaped_short = man_escape_option(s);
            format!("\\fB{}\\fR, \\fB{}\\fR", escaped_short, escaped_long)
        } else {
            format!("\\fB{}\\fR", escaped_long)
        }
    } else {
        let notation_str = if fo.notations.is_empty() {
            format!("=\\fI{}\\fR", fo.id.to_uppercase())
        } else {
            let n = fo.notations.first().unwrap();
            format!("=\\fI{}\\fR", n)
        };

        if let Some(s) = short {
            let escaped_short = man_escape_option(s);
            format!("\\fB{}\\fR, \\fB{}\\fR{}", escaped_short, escaped_long, notation_str)
        } else {
            format!("\\fB{}\\fR{}", escaped_long, notation_str)
        }
    }
}

fn man_escape(s: &str) -> String {
    s.replace('-', "\\-")
     .replace('`', "\\&`")
}

fn man_escape_option(s: &str) -> String {
    s.replace('-', "\\-")
}
