    // Execute the Argcfile.sh with the given args
    let shell = crate::utils::get_shell_path();

    let cmd_args: Vec<String> = if args.len() > 1 {
        args[1..].to_vec()
    } else {
        vec![]
    };

    let status = process::Command::new(&shell)
        .arg(argcfile.to_str().unwrap_or(""))
        .args(&cmd_args)
        .status()
        .map_err(|e| format!("Error running {}: {}", shell, e))?;

    if !status.success() {
        process::exit(status.code().unwrap_or(1));
    }

    Ok(())
}

pub fn argc_create(recipes: &[&str]) -> Result<(), String> {
    let argcfile = std::env::current_dir()
        .map(|d| d.join("Argcfile.sh"))
        .unwrap_or_else(|_| Path::new("Argcfile.sh").to_path_buf());

    if argcfile.exists() {
        eprintln!("Already exist {}", argcfile.display());
        return Ok(());
    }

    let mut content = String::from("#!/usr/bin/env bash\n\nset -e\n\n");

    if recipes.is_empty() {
        content.push_str("# See more details at https://github.com/sigoden/argc\neval \"$(argc --argc-eval \"$0\" \"$@\")\"\n");
    } else {
        for recipe in recipes {
            content.push_str(&format!("# @cmd\n{}() {{\n    echo TODO {}\n}}\n\n", recipe, recipe));
        }
        content.push_str("# See more details at https://github.com/sigoden/argc\neval \"$(argc --argc-eval \"$0\" \"$@\")\"\n");
    }

    fs::write(&argcfile, &content)
        .map_err(|e| format!("Error creating Argcfile.sh: {}", e))?;

    eprintln!("Argcfile.sh has been successfully created.");
    Ok(())
}

pub fn argc_run(script_path: &str, args: &[String]) -> Result<(), String> {
    let shell = crate::utils::get_shell_path();

    let status = process::Command::new(&shell)
        .arg(script_path)
        .args(args)
        .status()
        .map_err(|e| format!("Error running {}: {}", script_path, e))?;

    if !status.success() {
        process::exit(status.code().unwrap_or(1));
    }

    Ok(())
}

pub fn argc_parallel(script_path: &str, args: &[String]) -> Result<(), String> {
    if args.is_empty() {
        eprintln!("Usage: argc --argc-parallel <SCRIPT> <ARGS>...");
        process::exit(1);
    }

    // Split args by ":::"  
    let groups: Vec<Vec<&str>> = split_by_triple_colon(args.iter().map(|s| s.as_str()).collect());

    // Run all groups in parallel
    let mut handles = Vec::new();

    for group in groups {
        if group.is_empty() { continue; }
        let script = script_path.to_string();
        let group_args: Vec<String> = group.iter().map(|s| s.to_string()).collect();
        let shell = crate::utils::get_shell_path();

        let handle = std::thread::spawn(move || {
            let _ = process::Command::new(&shell)
                .arg(&script)
                .args(&group_args)
                .status();
        });
        handles.push(handle);
    }

    for handle in handles {
        let _ = handle.join();
    }

    Ok(())
}

fn split_by_triple_colon(args: Vec<&str>) -> Vec<Vec<&str>> {
    let mut groups = Vec::new();
    let mut current = Vec::new();

    for arg in args {
        if arg == ":::" {
            if !current.is_empty() {
                groups.push(current.clone());
                current.clear();
            }
        } else {
            current.push(arg);
        }
    }

    if !current.is_empty() {
        groups.push(current);
    }

    groups
}

pub fn argc_script_path() -> Result<(), String> {
    match crate::utils::find_argcfile() {
        Some(path) => {
            println!("{}", path.display());
        }
        None => {
            eprintln!("Argcfile not found.");
        }
    }
    Ok(())
}

pub fn argc_shell_path() -> Result<(), String> {
    println!("{}", crate::utils::get_shell_path());
    Ok(())
}
