    match &fo.long_name {
        Some(n) => w.field_str("long_name", n),
        None => w.field_null("long_name"),
    }
    match &fo.short_name {
        Some(n) => w.field_str("short_name", n),
        None => w.field_null("short_name"),
    }
    w.field_str("describe", &fo.describe);
    w.field_bool("flag", fo.is_flag);
    w.field_str_arr("notations", &fo.notations);
    w.field_bool("required", fo.required);
    w.field_bool("multiple_values", fo.multiple_values);
    w.field_bool("multiple_occurs", fo.multiple_occurs);

    // num_args as [min, max]
    w.begin_field("num_args");
    w.write_raw(&format!("[\n        {},\n        {}\n      ]", fo.num_args.0, fo.num_args.1));

    match fo.delimiter {
        Some(c) => w.field_str("delimiter", &c.to_string()),
        None => w.field_null("delimiter"),
    }
    w.field_bool("terminated", fo.terminated);
    w.field_bool("prefixed", fo.prefixed);
    w.field_bool("assigned", fo.assigned);

    // default
    w.begin_field("default");
    write_default(w, &fo.default);

    // choice
    w.begin_field("choice");
    write_choice(w, &fo.choice);

    // env
    match &fo.env {
        Some(e) => w.field_str("env", e),
        None => w.field_null("env"),
    }
    w.field_bool("inherited", fo.inherited);
    w.end_obj();
}

fn write_positional(w: &mut JsonWriter, pos: &Positional) {
    w.begin_obj();
    w.field_str("id", &pos.id);
    w.field_str("describe", &pos.describe);
    w.field_str("notation", &pos.notation);
    w.field_bool("required", pos.required);
    w.field_bool("multiple", pos.multiple);
    match pos.delimiter {
        Some(c) => w.field_str("delimiter", &c.to_string()),
        None => w.field_null("delimiter"),
    }
    w.field_bool("terminated", pos.terminated);

    w.begin_field("default");
    write_default(w, &pos.default);

    w.begin_field("choice");
    write_choice(w, &pos.choice);

    match &pos.env {
        Some(e) => w.field_str("env", e),
        None => w.field_null("env"),
    }
    w.end_obj();
}

fn write_env(w: &mut JsonWriter, env: &EnvDef) {
    w.begin_obj();
    w.field_str("id", &env.id);
    w.field_str("describe", &env.describe);
    w.field_bool("required", env.required);

    w.begin_field("default");
    write_default(w, &env.default);

    w.begin_field("choice");
    write_choice(w, &env.choice);

    w.field_bool("inherited", env.inherited);
    w.end_obj();
}

fn write_default(w: &mut JsonWriter, default: &Option<DefaultValue>) {
    match default {
        None => w.write_raw("null"),
        Some(DefaultValue::Value(v)) => {
            w.write_raw(&format!("{{\n      \"type\": \"Value\",\n      \"value\": {}\n    }}", json_str(v)));
        }
        Some(DefaultValue::Fn(f)) => {
            w.write_raw(&format!("{{\n      \"type\": \"Fn\",\n      \"value\": {}\n    }}", json_str(f)));
        }
    }
}

fn write_choice(w: &mut JsonWriter, choice: &Option<ChoiceValue>) {
    match choice {
        None => w.write_raw("null"),
        Some(ChoiceValue::Values(vals)) => {
            let v: Vec<String> = vals.iter().map(|v| json_str(v)).collect();
            w.write_raw(&format!("{{\n      \"type\": \"Values\",\n      \"data\": [{}]\n    }}", v.join(", ")));
        }
        Some(ChoiceValue::Fn(f, validate)) => {
            w.write_raw(&format!("{{\n      \"type\": \"Fn\",\n      \"data\": [{}, {}]\n    }}", json_str(f), validate));
        }
    }
}

// Simple JSON writer
struct JsonWriter {
    buf: String,
    indent: usize,
    first_in_obj: Vec<bool>,
    first_in_arr: Vec<bool>,
}

impl JsonWriter {
    fn new() -> Self {
        JsonWriter {
            buf: String::new(),
            indent: 0,
            first_in_obj: vec![],
            first_in_arr: vec![],
        }
    }

    fn finish(self) -> String {
        self.buf
    }

    fn write_raw(&mut self, s: &str) {
        self.buf.push_str(s);
    }

    fn begin_obj(&mut self) {
        self.buf.push('{');
        self.indent += 1;
        self.first_in_obj.push(true);
    }

    fn end_obj(&mut self) {
        self.indent -= 1;
        let ind = "  ".repeat(self.indent);
        self.buf.push_str(&format!("\n{}}}", ind));
        self.first_in_obj.pop();
    }

    fn begin_arr(&mut self) {
        self.buf.push('[');
        self.indent += 1;
        self.first_in_arr.push(true);
    }

    fn end_arr(&mut self) {
        self.indent -= 1;
        let had_items = self.first_in_arr.last().copied().unwrap_or(true);
        self.first_in_arr.pop();
        if !had_items {
            let ind = "  ".repeat(self.indent);
            self.buf.push_str(&format!("\n{}]", ind));
        } else {
            self.buf.push(']');
        }
    }

    fn maybe_comma_and_newline(&mut self) {
        let is_first = self.first_in_obj.last().copied().unwrap_or(true);
        if !is_first {
            self.buf.push(',');
        }
        if let Some(last) = self.first_in_obj.last_mut() {
            *last = false;
        }
        let ind = "  ".repeat(self.indent);
        self.buf.push_str(&format!("\n{}", ind));
    }

    fn maybe_comma_arr(&mut self) {
        let is_first = self.first_in_arr.last().copied().unwrap_or(true);
        if !is_first {
            self.buf.push(',');
        }
        if let Some(last) = self.first_in_arr.last_mut() {
            *last = false;
        }
        let ind = "  ".repeat(self.indent);
        self.buf.push_str(&format!("\n{}", ind));
    }

    fn begin_field(&mut self, name: &str) {
        self.maybe_comma_and_newline();
        self.buf.push_str(&format!("{}: ", json_str(name)));
    }

    fn field_str(&mut self, name: &str, value: &str) {
        self.maybe_comma_and_newline();
        self.buf.push_str(&format!("{}: {}", json_str(name), json_str(value)));
    }

    fn field_null(&mut self, name: &str) {
        self.maybe_comma_and_newline();
        self.buf.push_str(&format!("{}: null", json_str(name)));
    }

    fn field_bool(&mut self, name: &str, value: bool) {
        self.maybe_comma_and_newline();
        self.buf.push_str(&format!("{}: {}", json_str(name), value));
    }

    fn field_str_arr(&mut self, name: &str, values: &[String]) {
        self.maybe_comma_and_newline();
        let items: Vec<String> = values.iter().map(|v| json_str(v)).collect();
        self.buf.push_str(&format!("{}: [{}]", json_str(name), items.join(", ")));
    }

    fn arr_item_begin(&mut self) {
        self.maybe_comma_arr();
    }
}

fn json_str(s: &str) -> String {
    let escaped = s.replace('\\', "\\\\")
        .replace('"', "\\\"")
        .replace('\n', "\\n")
        .replace('\r', "\\r")
        .replace('\t', "\\t");
    format!("\"{}\"", escaped)
}
