// Generate help text

use crate::command::*;

pub fn generate_help(cmd: &Command, all_args: &[String], _indent_level: usize) -> String {
    let width = crate::utils::get_term_width();

    // Determine the full command name from all_args
    let cmd_display = all_args.first().cloned().unwrap_or_default();

    let mut sections = Vec::new();

    // Description
    if !cmd.describe.is_empty() {
        let desc = wrap_text_at_width(&cmd.describe, width, 0);
        sections.push(desc);
    }

    // Usage line
    let usage = build_usage_line(cmd, &cmd_display);
    sections.push(format!("USAGE: {}", usage));

    // ARGS section (positionals) - only if there are positionals with descriptions
    let user_positionals: Vec<_> = cmd.positionals.iter().collect();
    if !user_positionals.is_empty() {
        let pos_section = build_positionals_section(&user_positionals, width);
        sections.push(format!("ARGS:\n{}", pos_section));
    }

    // OPTIONS section - only if there are user-defined options (not just help/version)
    let user_flags_opts: Vec<_> = cmd.flag_options.iter().collect();
    let has_user_opts = user_flags_opts.iter().any(|f| !matches!(f.id.as_str(), "help" | "version") || !user_flags_opts.iter().any(|f| !matches!(f.id.as_str(), "help" | "version")));

    // Show OPTIONS if there are any non-trivial flags/options OR if help has describe
    let show_options = {
        let has_non_builtin = user_flags_opts.iter().any(|f| !matches!(f.id.as_str(), "help" | "version"));
        let help_has_desc = user_flags_opts.iter().find(|f| f.id == "help").map(|f| !f.describe.is_empty()).unwrap_or(false);
        has_non_builtin || help_has_desc
    };

    if show_options {
        let opts_section = build_options_section(&user_flags_opts, width);
        sections.push(format!("OPTIONS:\n{}", opts_section));
    }

    // ENVIRONMENTS section
    if !cmd.envs.is_empty() {
        let envs_section = build_envs_section(&cmd.envs, width);
        sections.push(format!("ENVIRONMENTS:\n{}", envs_section));
    }

    // COMMANDS section
    if !cmd.subcommands.is_empty() {
        let cmds_section = build_commands_section(&cmd.subcommands, width);
        sections.push(format!("COMMANDS:\n{}", cmds_section));
    }

    // Join with empty line between sections
    let result = sections.join("\n\n");
    result
}

fn build_usage_line(cmd: &Command, cmd_display: &str) -> String {
    let mut parts = vec![cmd_display.to_string()];

    // Check for inherited flags (inherit-flag-options) - these are shown as optional options
    let has_inherited = cmd.flag_options.iter().any(|f| f.inherited);

    // Collect required options (non-positional, required)
    let required_opts: Vec<_> = cmd.flag_options.iter()
        .filter(|f| f.required && !f.is_flag && !matches!(f.id.as_str(), "help" | "version"))
        .collect();

    // Check for any user-defined options/flags
    let has_user_opts = cmd.flag_options.iter().any(|f| !matches!(f.id.as_str(), "help" | "version"));

    if !cmd.subcommands.is_empty() {
        // Command with subcommands
        if has_user_opts || has_inherited {
            parts.push("[OPTIONS]".to_string());
        }

        for fo in &required_opts {
            parts.push(render_required_option_usage(fo));
        }

        parts.push("<COMMAND>".to_string());
    } else {
        // Leaf command
        let has_optional_opts = has_user_opts && required_opts.len() < cmd.flag_options.iter().filter(|f| !matches!(f.id.as_str(), "help" | "version")).count();

        if has_optional_opts {
            parts.push("[OPTIONS]".to_string());
        }

        for fo in &required_opts {
            parts.push(render_required_option_usage(fo));
        }

        // Positionals
        for pos in &cmd.positionals {
            parts.push(render_positional_usage(pos));
        }
    }

    parts.join(" ")
}

fn render_required_option_usage(fo: &FlagOption) -> String {
    let name = fo.long_name.as_deref().or(fo.short_name.as_deref()).unwrap_or("");
    let notation = fo.notations.first().map(|n| n.as_str()).unwrap_or("VALUE");
    if fo.multiple_occurs {
        if fo.required {
            format!("{} <{}>...", name, notation)
        } else {
            format!("{} [{}]...", name, notation)
        }
    } else {
        format!("{} <{}>", name, notation)
    }
}

fn render_positional_usage(pos: &Positional) -> String {
    let notation = &pos.notation;
    if pos.terminated {
        if pos.required {
            format!("<{}>...", notation)
        } else {
            format!("[{}]...", notation)
        }
    } else if pos.required && pos.multiple {
        format!("<{}>...", notation)
    } else if pos.required {
        format!("<{}>", notation)
    } else if pos.multiple {
        format!("[{}]...", notation)
    } else {
        format!("[{}]", notation)
    }
}

fn build_positionals_section(positionals: &[&Positional], width: usize) -> String {
    let notations: Vec<String> = positionals.iter().map(|p| {
        if p.required {
            format!("<{}>", p.notation)
        } else {
            format!("[{}]", p.notation)
        }
    }).collect();

    let max_notation_len = notations.iter().map(|n| n.len()).max().unwrap_or(0);

    let col_width = max_notation_len.max(8);

    let mut lines = Vec::new();

    for (pos, notation) in positionals.iter().zip(notations.iter()) {
        let has_long_desc = pos.describe.contains('\n') || pos.describe.len() > 20;

        if pos.describe.is_empty() {
            lines.push(format!("  {}", notation));
        } else {
            let indent = 2 + col_width + 2;
            let indent_str = " ".repeat(indent);

            if notation.len() + 2 + col_width + 2 + pos.describe.len() > width && width > 0 {
                // Multi-line
                lines.push(format!("  {}", notation));
                let wrapped = wrap_text_with_indent(&pos.describe, width, indent);
                lines.push(format!("{}{}", indent_str, wrapped.replace('\n', &format!("\n{}", indent_str))));
            } else {
                let padding = " ".repeat(col_width - notation.len() + 2);
                let desc_wrapped = if width > indent {
                    wrap_text_with_indent(&pos.describe, width, indent)
                } else {
                    pos.describe.clone()
                };

                if desc_wrapped.contains('\n') {
                    let first = desc_wrapped.lines().next().unwrap_or("");
                    let rest: Vec<&str> = desc_wrapped.lines().skip(1).collect();
                    lines.push(format!("  {}{}{}", notation, padding, first));
