    let required_opts: Vec<_> = cmd.flag_options.iter()
        .filter(|f| f.required && !f.is_flag && !matches!(f.id.as_str(), "help" | "version"))
        .collect();

    // Check for any user-defined options/flags
    let has_user_opts = cmd.flag_options.iter().any(|f| !matches!(f.id.as_str(), "help" | "version"));

    if !cmd.subcommands.is_empty() {
        // Command with subcommands
        if has_user_opts || has_inherited {
            parts.push("[OPTIONS]".to_string());
        }

        for fo in &required_opts {
            parts.push(render_required_option_usage(fo));
        }

        parts.push("<COMMAND>".to_string());
    } else {
        // Leaf command
        let has_optional_opts = has_user_opts && required_opts.len() < cmd.flag_options.iter().filter(|f| !matches!(f.id.as_str(), "help" | "version")).count();

        if has_optional_opts {
            parts.push("[OPTIONS]".to_string());
        }

        for fo in &required_opts {
            parts.push(render_required_option_usage(fo));
        }

        // Positionals
        for pos in &cmd.positionals {
            parts.push(render_positional_usage(pos));
        }
    }

    parts.join(" ")
}

fn render_required_option_usage(fo: &FlagOption) -> String {
    let name = fo.long_name.as_deref().or(fo.short_name.as_deref()).unwrap_or("");
    let notation = fo.notations.first().map(|n| n.as_str()).unwrap_or("VALUE");
    if fo.multiple_occurs {
        if fo.required {
            format!("{} <{}>...", name, notation)
        } else {
            format!("{} [{}]...", name, notation)
        }
    } else {
        format!("{} <{}>", name, notation)
    }
}

fn render_positional_usage(pos: &Positional) -> String {
    let notation = &pos.notation;
    if pos.terminated {
        if pos.required {
            format!("<{}>...", notation)
        } else {
            format!("[{}]...", notation)
        }
    } else if pos.required && pos.multiple {
        format!("<{}>...", notation)
    } else if pos.required {
        format!("<{}>", notation)
    } else if pos.multiple {
        format!("[{}]...", notation)
    } else {
        format!("[{}]", notation)
    }
}

fn build_positionals_section(positionals: &[&Positional], width: usize) -> String {
    let notations: Vec<String> = positionals.iter().map(|p| {
        if p.required {
            format!("<{}>", p.notation)
        } else {
            format!("[{}]", p.notation)
        }
    }).collect();

    let max_notation_len = notations.iter().map(|n| n.len()).max().unwrap_or(0);

    let col_width = max_notation_len.max(8);

    let mut lines = Vec::new();

    for (pos, notation) in positionals.iter().zip(notations.iter()) {
        let has_long_desc = pos.describe.contains('\n') || pos.describe.len() > 20;

        if pos.describe.is_empty() {
            lines.push(format!("  {}", notation));
        } else {
            let indent = 2 + col_width + 2;
            let indent_str = " ".repeat(indent);

            if notation.len() + 2 + col_width + 2 + pos.describe.len() > width && width > 0 {
                // Multi-line
                lines.push(format!("  {}", notation));
                let wrapped = wrap_text_with_indent(&pos.describe, width, indent);
                lines.push(format!("{}{}", indent_str, wrapped.replace('\n', &format!("\n{}", indent_str))));
            } else {
                let padding = " ".repeat(col_width - notation.len() + 2);
                let desc_wrapped = if width > indent {
                    wrap_text_with_indent(&pos.describe, width, indent)
                } else {
                    pos.describe.clone()
                };

                if desc_wrapped.contains('\n') {
                    let first = desc_wrapped.lines().next().unwrap_or("");
                    let rest: Vec<&str> = desc_wrapped.lines().skip(1).collect();
                    lines.push(format!("  {}{}{}", notation, padding, first));
                    for r in rest {
                        lines.push(r.to_string());
                    }
                } else {
                    lines.push(format!("  {}{}{}", notation, padding, desc_wrapped));
                }
            }
        }
    }

    lines.join("\n")
}

fn build_options_section(flag_options: &[&FlagOption], width: usize) -> String {
    // Calculate alignment
    let option_strs: Vec<String> = flag_options.iter().map(|fo| render_option_left(fo)).collect();
    let max_left_len = option_strs.iter().map(|s| s.len()).max().unwrap_or(0);
    let col_width = max_left_len;

    let mut lines = Vec::new();

    for (fo, left_str) in flag_options.iter().zip(option_strs.iter()) {
        let right_str = build_option_right(fo);
        let has_long_desc = right_str.contains('\n') || (right_str.len() + left_str.len() + 4 > width);

        let indent = 2 + col_width + 2;

        if right_str.is_empty() {
            lines.push(format!("  {}", left_str));
        } else if has_long_desc && width > 0 {
            // Long description - put on next line
            lines.push(format!("  {}", left_str));
            let indent_str = " ".repeat(indent);
            let wrapped = wrap_text_with_indent(&right_str, width, indent);
            for (i, wline) in wrapped.lines().enumerate() {
                if i == 0 {
                    lines.push(format!("{}{}", indent_str, wline));
                } else {
                    lines.push(wline.to_string());
                }
            }
            lines.push(String::new());
        } else {
            let padding = " ".repeat(col_width - left_str.len() + 2);
            let right_wrapped = if width > indent {
                wrap_text_with_indent(&right_str, width, indent)
            } else {
                right_str.clone()
            };

            if right_wrapped.contains('\n') {
                let first = right_wrapped.lines().next().unwrap_or("");
                let rest: Vec<&str> = right_wrapped.lines().skip(1).collect();
                lines.push(format!("  {}{}{}", left_str, padding, first));
                for r in rest {
                    lines.push(r.to_string());
                }
            } else {
                lines.push(format!("  {}{}{}", left_str, padding, right_wrapped));
            }
        }
    }

    // Remove trailing empty lines
    while lines.last().map(|l| l.trim().is_empty()).unwrap_or(false) {
        lines.pop();
    }

    lines.join("\n")
}

fn render_option_left(fo: &FlagOption) -> String {
    let long = fo.long_name.as_deref().unwrap_or("");
    let short = fo.short_name.as_deref();

    let name_part = if let Some(s) = short {
        format!("{}, {}", s, long)
    } else {
        format!("    {}", long)
    };

    let notations_str = if fo.is_flag {
        if fo.multiple_occurs {
            "...".to_string()
        } else {
            String::new()
        }
    } else if fo.terminated {
        let n = fo.notations.first().map(|n| n.as_str()).unwrap_or("VALUE");
        let notation_upper = n.to_uppercase();
        format!(" <{}~>", notation_upper)
    } else if fo.assigned {
        let n = fo.notations.first().map(|n| n.as_str()).unwrap_or("VALUE");
        let notation_upper = n.to_uppercase();
        format!("=<{}>", notation_upper)
    } else if fo.prefixed {
        let n = fo.notations.first().map(|n| n.as_str()).unwrap_or("VALUE");
        let notation_upper = n.to_uppercase();
        if fo.multiple_occurs {
            format!(" [{}]...", notation_upper)
        } else {
            format!(" <{}>", notation_upper)
        }
    } else if fo.notations.is_empty() {
        String::new()
    } else if fo.multiple_occurs {
        let n = fo.notations.first().map(|n| n.as_str()).unwrap_or("VALUE");
        let notation_upper = n.to_uppercase();
        if fo.required {
            format!(" <{}>...", notation_upper)
        } else {
            format!(" [{}]...", notation_upper)
        }
    } else if fo.notations.len() == 1 {
        let n = &fo.notations[0];
        format!(" <{}>", n)
    } else {
        let parts: Vec<String> = fo.notations.iter().map(|n| format!("<{}>", n)).collect();
        format!(" {}", parts.join(" "))
    };

    format!("{}{}", name_part, notations_str)
}

fn build_option_right(fo: &FlagOption) -> String {
    let mut parts = Vec::new();

    // Base description
    let base_desc = fo.describe.lines().next().unwrap_or("").to_string();
    if !base_desc.is_empty() {
        parts.push(base_desc);
    }

    // Multi-line description continuation
    let rest_desc: Vec<&str> = fo.describe.lines().skip(1).collect();

    // Metadata
    let mut meta_parts = Vec::new();

    // Default value (only Value type, not Fn)
    if let Some(DefaultValue::Value(v)) = &fo.default {
        meta_parts.push(format!("[default: {}]", v));
    }

    // Possible values
    if let Some(ChoiceValue::Values(choices)) = &fo.choice {
        meta_parts.push(format!("[possible values: {}]", choices.join(", ")));
    }

    // Env
    if let Some(env) = &fo.env {
        meta_parts.push(format!("[env: {}]", env));
    }

    if !meta_parts.is_empty() {
        if parts.is_empty() {
            parts.push(meta_parts.join(" "));
        } else {
            let last = parts.last_mut().unwrap();
            *last = format!("{} {}", last, meta_parts.join(" "));
        }
    }

    // Add continuation lines
    let mut result = parts.join(" ");
    for rest_line in rest_desc {
        result.push('\n');
        result.push_str(rest_line);
    }

    result
}

fn build_envs_section(envs: &[EnvDef], width: usize) -> String {
    let max_id_len = envs.iter().map(|e| {
        e.id.len() + if e.required { 1 } else { 0 }
    }).max().unwrap_or(0);

    let col_width = max_id_len;

    let mut lines = Vec::new();

    for env in envs {
        let suffix = if env.required { "*" } else { "" };
        let id_str = format!("{}{}", env.id, suffix);

        let mut desc_parts = Vec::new();
        if !env.describe.is_empty() {
            desc_parts.push(env.describe.clone());
        }

        if let Some(DefaultValue::Value(v)) = &env.default {
            desc_parts.push(format!("[default: {}]", v));
        }

        if let Some(ChoiceValue::Values(choices)) = &env.choice {
            desc_parts.push(format!("[possible values: {}]", choices.join(", ")));
        }

        let desc = desc_parts.join(" ");

        if desc.is_empty() {
            lines.push(format!("  {}", id_str));
        } else {
            let padding = " ".repeat(col_width - id_str.len() + 2);
            lines.push(format!("  {}{}{}", id_str, padding, desc));
        }
    }

    lines.join("\n")
}

fn build_commands_section(subcommands: &[Command], width: usize) -> String {
    let max_name_len = subcommands.iter().map(|c| c.name.len()).max().unwrap_or(0);
    let col_width = max_name_len;

    let mut lines = Vec::new();

    for cmd in subcommands {
        let mut extra_info = Vec::new();
        if !cmd.aliases.is_empty() {
            extra_info.push(format!("[aliases: {}]", cmd.aliases.join(", ")));
        }
        if cmd.metadata.default_subcommand.is_some() {
            extra_info.push("[default]".to_string());
        }

        let first_desc = cmd.describe.lines().next().unwrap_or("");

        let desc = if !first_desc.is_empty() && !extra_info.is_empty() {
            format!("{} {}", first_desc, extra_info.join(" "))
        } else if !first_desc.is_empty() {
            first_desc.to_string()
        } else if !extra_info.is_empty() {
            extra_info.join(" ")
        } else {
            String::new()
        };

        if desc.is_empty() {
            lines.push(format!("  {}", cmd.name));
        } else {
            let padding = " ".repeat(col_width - cmd.name.len() + 2);
            let indent = 2 + col_width + 2;

            let desc_wrapped = if width > indent {
                wrap_text_with_indent(&desc, width, indent)
            } else {
                desc.clone()
            };

            if desc_wrapped.contains('\n') {
                let first = desc_wrapped.lines().next().unwrap_or("");
                let rest: Vec<&str> = desc_wrapped.lines().skip(1).collect();
                lines.push(format!("  {}{}{}", cmd.name, padding, first));
                for r in rest {
                    lines.push(r.to_string());
                }
            } else {
                lines.push(format!("  {}{}{}", cmd.name, padding, desc_wrapped));
            }
        }
    }

    lines.join("\n")
}

fn wrap_text_at_width(text: &str, width: usize, _indent: usize) -> String {
    if width == 0 {
        return text.to_string();
    }

    let mut result = Vec::new();

    for line in text.lines() {
        if line.len() <= width {
            result.push(line.to_string());
        } else {
            result.extend(wrap_single_line(line, width));
        }
    }

    result.join("\n")
}

fn wrap_text_with_indent(text: &str, width: usize, indent: usize) -> String {
    let available = if width > indent { width - indent } else { 40 };
    let indent_str = " ".repeat(indent);

    let mut result_lines = Vec::new();

    for (i, line) in text.lines().enumerate() {
        if line.len() <= available {
            result_lines.push(line.to_string());
        } else {
            let wrapped = wrap_single_line(line, available);
            for (j, wline) in wrapped.iter().enumerate() {
                if i == 0 && j == 0 {
                    result_lines.push(wline.clone());
                } else {
                    result_lines.push(format!("{}{}", indent_str, wline));
                }
            }
        }
    }

    result_lines.join("\n")
}

fn wrap_single_line(line: &str, width: usize) -> Vec<String> {
    if line.len() <= width {
        return vec![line.to_string()];
    }

    let mut lines = Vec::new();
    let mut current = String::new();

    for word in line.split(' ') {
        if current.is_empty() {
            current = word.to_string();
        } else if current.len() + 1 + word.len() <= width {
            current.push(' ');
            current.push_str(word);
        } else {
            lines.push(current.clone());
            current = word.to_string();
        }
    }

    if !current.is_empty() {
        lines.push(current);
    }

    if lines.is_empty() {
        vec![line.to_string()]
    } else {
        lines
    }
}
