// Generate bash eval output for --argc-eval

use std::collections::HashMap;
use std::fs;
use std::path::Path;
use crate::command::*;
use crate::parser;
use crate::utils;

pub fn argc_eval(script_path: &str, args: &[String]) -> Result<(), String> {
    let content = fs::read_to_string(script_path)
        .map_err(|e| format!("Error reading {}: {}", script_path, e))?;

    let script_name = Path::new(script_path)
        .file_stem()
        .and_then(|s| s.to_str())
        .unwrap_or(script_path);

    let cmd = parser::parse_script(&content, script_name);

    let all_args: Vec<String> = {
        let mut v = vec![script_name.to_string()];
        v.extend_from_slice(args);
        v
    };

    let mut state = EvalState::new(&all_args, script_name, &content);

    match eval_command(&cmd, &mut state, script_name) {
        Ok(()) => {
            print!("{}", state.generate_output());
        }
        Err(e) => {
            print_error(&e);
        }
    }

    Ok(())
}

fn print_error(msg: &str) {
    println!("command cat >&2 <<-'EOF' \n{}\nEOF\nexit 1", msg);
}

fn print_help_and_exit(help: &str) {
    let help_with_nl = if help.ends_with('\n') { help.to_string() } else { format!("{}\n", help) };
    println!("command cat >&2 <<-'EOF' \n{}EOF\nexit 0", help_with_nl);
    std::process::exit(0);
}

fn print_version_and_exit(name: &str, version: &str) {
    println!("command cat >&2 <<-'EOF' \n{} {}\nEOF\nexit 0", name, version);
    std::process::exit(0);
}

struct EvalState<'a> {
    all_args: &'a [String],
    script_name: &'a str,
    content: &'a str,
    vars: Vec<(String, VarValue)>,
    positionals: Vec<String>,
    fn_to_call: Option<String>,
    require_tools: Vec<String>,
    env_setup: Vec<String>,
    dotenv_file: Option<String>,
    dash_pos: Option<usize>,
}

#[derive(Clone, Debug)]
enum VarValue {
    Scalar(String),
    Array(Vec<String>),
}

impl<'a> EvalState<'a> {
    fn new(all_args: &'a [String], script_name: &'a str, content: &'a str) -> Self {
        EvalState {
            all_args,
            script_name,
            content,
            vars: vec![],
            positionals: vec![],
            fn_to_call: None,
            require_tools: vec![],
            env_setup: vec![],
            dotenv_file: None,
            dash_pos: None,
        }
    }

    fn get_var_scalar(&self, name: &str) -> Option<&str> {
        self.vars.iter().rev().find(|(k, _)| k == name)
            .and_then(|(_, v)| if let VarValue::Scalar(s) = v { Some(s.as_str()) } else { None })
    }

    fn is_set(&self, name: &str) -> bool {
        self.vars.iter().any(|(k, _)| k == name)
    }

    fn set_scalar(&mut self, name: String, val: String) {
        self.vars.push((name, VarValue::Scalar(val)));
    }

    fn set_array(&mut self, name: String, vals: Vec<String>) {
        self.vars.push((name, VarValue::Array(vals)));
    }

    fn append_to_array(&mut self, name: &str, vals: &[String]) {
        let existing: Vec<String> = self.vars.iter().rev()
            .find(|(k, _)| k == name)
            .and_then(|(_, v)| if let VarValue::Array(a) = v { Some(a.clone()) } else { None })
            .unwrap_or_default();
        self.vars.retain(|(k, _)| k != name);
        let mut new_arr = existing;
        new_arr.extend_from_slice(vals);
        self.vars.push((name.to_string(), VarValue::Array(new_arr)));
    }

    fn increment_counter(&mut self, name: &str) {
        let count = self.vars.iter().rev()
            .find(|(k, _)| k == name)
            .and_then(|(_, v)| if let VarValue::Scalar(s) = v { s.parse::<u32>().ok() } else { None })
            .unwrap_or(0);
        self.vars.retain(|(k, _)| k != name);
        self.vars.push((name.to_string(), VarValue::Scalar((count + 1).to_string())));
    }

    fn generate_output(&self) -> String {
        let mut out = String::new();

        // Build ARGC_VARS base64 content
        let mut assignments = String::new();
        for (name, val) in &self.vars {
            match val {
                VarValue::Scalar(s) => {
                    let q = utils::shell_quote(s);
                    assignments.push_str(&format!("{}={};", name, q));
                }
                VarValue::Array(arr) => {
                    let items: Vec<String> = arr.iter().map(|s| utils::shell_quote(s)).collect();
                    assignments.push_str(&format!("{}=( {} );", name, items.join(" ")));
                }
            }
        }

        // argc__args
        let args_q: Vec<String> = self.all_args.iter().map(|s| utils::shell_quote(s)).collect();
        assignments.push_str(&format!("argc__args=( {} );", args_q.join(" ")));

        // argc__fn
        if let Some(ref fn_name) = self.fn_to_call {
            assignments.push_str(&format!("argc__fn={};", fn_name));
        }

        // argc__positionals
        if self.positionals.is_empty() {
            assignments.push_str("argc__positionals=(  );");
        } else {
            let pos_q: Vec<String> = self.positionals.iter().map(|s| utils::shell_quote(s)).collect();
            assignments.push_str(&format!("argc__positionals=( {} );", pos_q.join(" ")));
        }

        let encoded = utils::base64_encode(assignments.as_bytes());
        out.push_str(&format!("export ARGC_VARS={}\n", encoded));

        // require_tools
        if !self.require_tools.is_empty() {
            out.push_str("_argc_require_tools() {\n    local tool missing_tools=()\n    for tool in \"$@\"; do\n        if ! command -v \"$tool\" >/dev/null 2>&1; then\n            missing_tools+=(\"$tool\")\n        fi\n    done\n    if [[ \"${#missing_tools[@]}\" -gt 0 ]]; then\n        echo \"error: missing tools: ${missing_tools[*]}\" >&2\n        exit 1\n    fi\n}\n");
            out.push_str(&format!("_argc_require_tools {}\n", self.require_tools.join(" ")));
            out.push('\n');
        }

        // dotenv
        if let Some(ref dotenv_file) = self.dotenv_file {
            out.push_str(&generate_dotenv_loader(dotenv_file));
        }

        // env setup
        for env_line in &self.env_setup {
            out.push_str(env_line);
            out.push('\n');
        }

        // Print variable assignments
        for (name, val) in &self.vars {
            match val {
                VarValue::Scalar(s) => {
                    let q = utils::shell_quote(s);
                    out.push_str(&format!("{}={}\n", name, q));
                }
                VarValue::Array(arr) => {
                    let items: Vec<String> = arr.iter().map(|s| utils::shell_quote(s)).collect();
                    out.push_str(&format!("{}=( {} )\n", name, items.join(" ")));
                }
            }
        }

        // argc__args
        out.push_str(&format!("argc__args=( {} )\n", args_q.join(" ")));

        // argc__fn
        if let Some(ref fn_name) = self.fn_to_call {
            out.push_str(&format!("argc__fn={}\n", fn_name));
        }

        // argc__positionals
        if self.positionals.is_empty() {
            out.push_str("argc__positionals=(  )\n");
        } else {
            let pos_q: Vec<String> = self.positionals.iter().map(|s| utils::shell_quote(s)).collect();
            out.push_str(&format!("argc__positionals=( {} )\n", pos_q.join(" ")));
        }

        // Function call
        if let Some(ref fn_name) = self.fn_to_call {
            if self.positionals.is_empty() {
                out.push_str(&format!("{}\n", fn_name));
            } else {
                let pos_q: Vec<String> = self.positionals.iter().map(|s| utils::shell_quote(s)).collect();
                out.push_str(&format!("{} {}\n", fn_name, pos_q.join(" ")));
            }
        }

        out
    }
}

fn generate_dotenv_loader(env_file: &str) -> String {
    format!("_argc_load_dotenv() {{\n    local env_file=\"$1\" env_vars=\"\"\n    if [[ -f \"$env_file\" ]]; then\n        while IFS='=' read -r key value; do\n            if [[ \"$key\" == $'#'* ]] || [[ -z \"$key\" ]]; then\n                continue\n            fi\n            if [[ -z \"${{!key+x}}\" ]]; then\n                env_vars=\"$env_vars $key=$value\"\n            fi\n        done < <(cat \"$env_file\"; echo \"\")\n        if [[ -n \"$env_vars\" ]]; then\n            eval \"export $env_vars\"\n        fi\n    fi\n}}\n_argc_load_dotenv {}\n", env_file)
}

// Main eval function - evaluates a command against the args
fn eval_command(
    cmd: &Command,
    state: &mut EvalState,
    cmd_path: &str,
) -> Result<(), String> {
    // Check dotenv
    if let Some(ref dotenv) = cmd.metadata.dotenv {
        let ef = if dotenv.is_empty() { ".env".to_string() } else { dotenv.clone() };
        state.dotenv_file = Some(ef);
    }

    // Collect require_tools for this command
    state.require_tools.extend(cmd.metadata.require_tools.clone());

    if !cmd.subcommands.is_empty() {
        eval_with_subcommands(cmd, state, cmd_path, 1)
    } else {
        eval_leaf_command(cmd, state, cmd_path, 1)
    }
}

fn eval_with_subcommands(
    cmd: &Command,
    state: &mut EvalState,
    cmd_path: &str,
    start_idx: usize,
) -> Result<(), String> {
    let all_args = state.all_args;
    let len = all_args.len();
    let cmd_name = cmd_path.split_whitespace().last().unwrap_or(cmd_path);

    let default_subcmd = cmd.subcommands.iter().find(|s| s.metadata.default_subcommand.is_some());

    let mut idx = start_idx;

    while idx < len {
        let arg = &all_args[idx];

        if arg == "--" {
            state.positionals.extend(all_args[idx+1..].iter().cloned());
            idx = len;
            break;
        }

        // Check help flag
        if is_help_flag(arg, cmd) {
            let help = crate::help::generate_help(cmd, cmd_path, 0);
            print_help_and_exit(&help);
        }

        // Check version flag
        if is_version_flag(arg, cmd) {
            let version = cmd.version.as_deref().unwrap_or("0.0.0");
            print_version_and_exit(cmd_name, version);
        }

        // Check for inherited/root flags
        if let Some(fo) = find_matching_fo(cmd, arg) {
            let fo = fo.clone();
            let n_consumed = handle_flag_option(&fo, arg, all_args, idx, state)?;
            idx += n_consumed;
            continue;
        }

        // Check for subcommand
        let arg_str = arg.as_str();
        if let Some(sub) = find_subcmd(cmd, arg_str) {
            let sub_clone = sub.clone();
            let new_path = format!("{} {}", cmd_path, sub_clone.name);
            state.require_tools.extend(sub_clone.metadata.require_tools.clone());
            if !sub_clone.subcommands.is_empty() {
                return eval_with_subcommands(&sub_clone, state, &new_path, idx + 1);
            } else {
                return eval_leaf_command(&sub_clone, state, &new_path, idx + 1);
            }
        }

        // Check "help" as subcommand
        if arg_str == "help" {
            let help_arg = all_args.get(idx + 1).map(|s| s.as_str()).unwrap_or("");
            if help_arg.is_empty() {
                let help = crate::help::generate_help(cmd, cmd_path, 0);
                print_help_and_exit(&help);
            } else if let Some(sub) = find_subcmd(cmd, help_arg) {
                let sub_clone = sub.clone();
                let sub_path = format!("{} {}", cmd_path, sub_clone.name);
                let help = crate::help::generate_help(&sub_clone, &sub_path, 0);
                print_help_and_exit(&help);
            } else {
                let subcmds = get_subcmd_list(cmd);
                return Err(format!("error: invalid value `{}` for `<command>`\n  [possible values: {}]",
                    help_arg, subcmds));
            }
        }

        // Use default subcommand if available
        if let Some(default) = default_subcmd {
            let default_clone = default.clone();
            let new_path = format!("{} {}", cmd_path, default_clone.name);
            state.require_tools.extend(default_clone.metadata.require_tools.clone());
            return eval_leaf_command(&default_clone, state, &new_path, idx);
        }

        // Error: subcommand required
        return Err(format!("error: `{}` requires a subcommand but '{}' is not one of them\n  [subcommands: {}]",
            cmd_name, arg, get_subcmd_list(cmd)));
    }

    // End of args without finding subcommand
    if let Some(default) = default_subcmd {
        let default_clone = default.clone();
        let new_path = format!("{} {}", cmd_path, default_clone.name);
        state.fn_to_call = default_clone.command_fn.clone();
        apply_defaults(&default_clone, state);
        validate_envs(&default_clone, state)?;
        return Ok(());
    }

    if let Some(ref fn_name) = cmd.command_fn {
        state.fn_to_call = Some(fn_name.clone());
        apply_defaults(cmd, state);
        validate_envs(cmd, state)?;
        return Ok(());
    }

    // Show help
    let help = crate::help::generate_help(cmd, cmd_path, 0);
    print_help_and_exit(&help);
    Ok(())
}

fn eval_leaf_command(
    cmd: &Command,
    state: &mut EvalState,
    cmd_path: &str,
    start_idx: usize,
) -> Result<(), String> {
    let all_args = state.all_args;
    let len = all_args.len();
    let combine_shorts = cmd.metadata.combine_shorts;

    let mut idx = start_idx;
    let mut option_set: HashMap<String, bool> = HashMap::new();

    while idx < len {
        let arg = &all_args[idx];

        if arg == "--" {
            state.dash_pos = Some(state.positionals.len());
            state.positionals.extend(all_args[idx+1..].iter().cloned());
            idx = len;
            break;
        }

        // Check help flag
        if is_help_flag(arg, cmd) {
            let help = crate::help::generate_help(cmd, cmd_path, 0);
            print_help_and_exit(&help);
        }

        // Check for matching flag/option
        if let Some(fo) = find_matching_fo(cmd, arg) {
            let fo = fo.clone();
            let n_consumed = handle_flag_option_checked(&fo, arg, all_args, idx, state, &mut option_set)?;
            idx += n_consumed;
            continue;
        }

        // Check for combined shorts
        if combine_shorts && is_potential_combined_short(arg) {
            if let Some(n) = try_parse_combined_short(arg, all_args, idx, cmd, state, &mut option_set)? {
                idx += n;
                continue;
            }
        }

        // Check if it looks like an unknown option
        if is_option_like(arg, cmd) {
            let key = arg.split('=').next().unwrap_or(arg);
            return Err(format!("error: unexpected argument `{}` found", key));
        }

        // Positional argument
        state.positionals.push(arg.clone());
        idx += 1;
    }

    // "help" as sole positional - show help
    if state.positionals.len() == 1 && state.positionals[0] == "help" && cmd.positionals.is_empty() {
        let help = crate::help::generate_help(cmd, cmd_path, 0);
        print_help_and_exit(&help);
    }

    // Set function name
    state.fn_to_call = cmd.command_fn.clone();

    // Apply defaults
    apply_defaults(cmd, state);

    // Validate positionals and set variables
    validate_and_set_positionals(cmd, state)?;

    // Validate envs
    validate_envs(cmd, state)?;

    // Check required options
    check_required_options(cmd, state)?;

    Ok(())
}

fn handle_flag_option(
    fo: &FlagOption,
    arg: &str,
    all_args: &[String],
    idx: usize,
    state: &mut EvalState,
) -> Result<usize, String> {
    let mut dummy = HashMap::new();
    handle_flag_option_checked(fo, arg, all_args, idx, state, &mut dummy)
}

fn handle_flag_option_checked(
    fo: &FlagOption,
    arg: &str,
    all_args: &[String],
    idx: usize,
    state: &mut EvalState,
    option_set: &mut HashMap<String, bool>,
) -> Result<usize, String> {
    let var_name = format!("argc_{}", fo.id);

    if fo.is_flag {
        if arg.contains('=') {
            let long = fo.long_name.as_deref().or(fo.short_name.as_deref()).unwrap_or("");
            return Err(format!("error: flag `{}` don't accept any value", long));
        }

        if fo.multiple_occurs {
            state.increment_counter(&var_name);
        } else {
            if option_set.contains_key(&fo.id) {
                let long = fo.long_name.as_deref().or(fo.short_name.as_deref()).unwrap_or("");
                return Err(format!("error: the argument `{}` cannot be used multiple times", long));
            }
            option_set.insert(fo.id.clone(), true);
            state.set_scalar(var_name, "1".to_string());
        }
        return Ok(1);
    }

    // Option with value
    if fo.assigned {
        if !arg.contains('=') {
            return Err(format!("error: incorrect number of values for `{}`", render_fo_name(fo)));
        }
        let value = arg.splitn(2, '=').nth(1).unwrap_or("");
        validate_fo_choice(fo, &[value])?;
        state.set_scalar(var_name, value.to_string());
        return Ok(1);
    }

    // Collect values
    let values = collect_values(fo, arg, all_args, idx)?;
    let n_consumed = 1 + values.len();

    validate_fo_choice(fo, &values.iter().map(|s| s.as_str()).collect::<Vec<_>>())?;

    if fo.multiple_occurs {
        state.append_to_array(&var_name, &values);
    } else if fo.multiple_values || fo.num_args.1 > 1 {
        state.set_array(var_name, values);
    } else {
        if option_set.contains_key(&fo.id) {
            let long = fo.long_name.as_deref().or(fo.short_name.as_deref()).unwrap_or("");
            return Err(format!("error: the argument `{}` cannot be used multiple times", long));
        }
        option_set.insert(fo.id.clone(), true);
        let val = values.into_iter().next().unwrap_or_default();
        state.set_scalar(var_name, val);
    }

    Ok(n_consumed)
}

fn collect_values(fo: &FlagOption, arg: &str, all_args: &[String], idx: usize) -> Result<Vec<String>, String> {
    let (min, max) = fo.num_args;

    // Value in arg itself (--foo=value)
    if arg.contains('=') {
        let value = arg.splitn(2, '=').nth(1).unwrap_or("");
        if min > 0 && value.is_empty() {
            return Err(format!("error: incorrect number of values for `{}`", render_fo_name(fo)));
        }
        let values = if let Some(delim) = fo.delimiter {
            value.split(delim).map(|s| s.to_string()).collect()
        } else {
            vec![value.to_string()]
        };
        return Ok(values);
    }

    let sign = fo.sign();
    let mut values = Vec::new();
    let mut next_idx = idx + 1;

    while next_idx < all_args.len() && values.len() < max {
        let next = &all_args[next_idx];

        // Stop if next is an option (unless sign is empty for terminated)
        if sign != "" && next.len() > 1 {
            if is_option_sign(next, sign) {
                break;
            }
        }

        values.push(next.clone());
        next_idx += 1;

        // For non-multi options, stop after getting enough
        if !fo.terminated && !fo.multiple_values && values.len() >= max {
            break;
        }
    }

    if values.len() < min {
        return Err(format!("error: incorrect number of values for `{}`", render_fo_name(fo)));
    }

    // Handle delimiter
    if let Some(delim) = fo.delimiter {
        let mut result = Vec::new();
        for v in &values {
            result.extend(v.split(delim).map(|s| s.to_string()));
        }
        return Ok(result);
    }

    Ok(values)
}

fn is_option_sign(arg: &str, sign: &str) -> bool {
    if sign == "+" {
        arg.starts_with('+') && !arg.starts_with("++")
    } else {
        arg.starts_with('-') && !arg.starts_with("---")
    }
}

fn validate_fo_choice(fo: &FlagOption, values: &[&str]) -> Result<(), String> {
    if let Some(ref choice) = fo.choice {
        match choice {
            ChoiceValue::Values(choices) => {
                let notation = fo.notations.first().unwrap_or(&fo.id);
                for val in values {
                    if !choices.iter().any(|c| c == val) {
                        return Err(format!("error: invalid value `{}` for `<{}>`\n  [possible values: {}]",
                            val, notation, choices.join(", ")));
                    }
                }
            }
            ChoiceValue::Fn(_, validate) => {
                // Validation deferred to bash runtime
                if !validate {
                    return Ok(());
                }
                // In eval mode, we can't run bash functions
            }
        }
    }
    Ok(())
}

fn render_fo_name(fo: &FlagOption) -> String {
    let long = fo.long_name.as_deref().or(fo.short_name.as_deref()).unwrap_or("");
    if fo.is_flag || fo.notations.is_empty() {
        return long.to_string();
    }

    let n = fo.notations.first().map(|s| s.as_str()).unwrap_or("VALUE");
    if fo.assigned {
        format!("{}=<{}>", long, n)
    } else if fo.terminated {
        format!("{} <{}~>", long, n)
    } else if fo.multiple_occurs {
        if fo.required {
            format!("{} <{}>...", long, n)
        } else {
            format!("{} [{}]...", long, n)
        }
    } else {
        format!("{} <{}>", long, n)
    }
}

fn apply_defaults(cmd: &Command, state: &mut EvalState) {
    for fo in &cmd.flag_options {
        if matches!(fo.id.as_str(), "help" | "version") || fo.is_flag { continue; }
        let var_name = format!("argc_{}", fo.id);
        if !state.is_set(&var_name) {
            if let Some(ref default) = fo.default {
                let val = match default {
                    DefaultValue::Value(v) => v.clone(),
                    DefaultValue::Fn(f) => format!("`{}`", f),
                };
                state.set_scalar(var_name, val);
            }
        }
    }
}

fn validate_and_set_positionals(cmd: &Command, state: &mut EvalState) -> Result<(), String> {
    if cmd.positionals.is_empty() {
        if !state.positionals.is_empty() {
            // Unexpected positional?
            // Only error if no terminated option consumed everything
        }
        return Ok(());
    }

    let pos_defs = &cmd.positionals;
    let pos_args = &state.positionals;

    let matches = match_positionals(pos_defs, pos_args, state.dash_pos)?;

    for (i, pos_def) in pos_defs.iter().enumerate() {
        let var_name = format!("argc_{}", pos_def.id.replace("...", "___").replace('-', "_").replace('.', "_"));

        if let Some((start, count)) = matches.get(i).copied().flatten() {
            if pos_def.multiple {
                let vals: Vec<String> = pos_args[start..start+count].to_vec();
                let vals = if let Some(delim) = pos_def.delimiter {
                    vals.iter().flat_map(|v| v.split(delim).map(|s| s.to_string())).collect()
                } else {
                    vals
                };
                state.set_array(var_name, vals);
            } else {
                let val = pos_args.get(start).cloned().unwrap_or_default();
                state.set_scalar(var_name, val);
            }
        } else {
            if pos_def.required {
                let notation = &pos_def.notation;
                // Check for multiple required too
                if pos_def.multiple {
                    return Err(format!("error: the following required arguments were not provided:\n  <{}>...", notation));
                } else {
                    return Err(format!("error: the following required arguments were not provided:\n  <{}>", notation));
                }
            } else if let Some(ref default) = pos_def.default {
                let val = match default {
                    DefaultValue::Value(v) => v.clone(),
                    DefaultValue::Fn(f) => format!("`{}`", f),
                };
                state.set_scalar(var_name, val);
            }
        }
    }

    // Check for extra positionals
    if let Some(Some((start, _))) = matches.get(pos_defs.len()) {
        if let Some(extra) = pos_args.get(*start) {
            return Err(format!("error: unexpected argument `{}` found", extra));
        }
    }

    Ok(())
}

fn match_positionals(
    defs: &[Positional],
    args: &[String],
    dash_pos: Option<usize>,
) -> Result<Vec<Option<(usize, usize)>>, String> {
    let n_defs = defs.len();
    let n_args = args.len();
    let mut result: Vec<Option<(usize, usize)>> = vec![None; n_defs + 1];

    if n_args == 0 {
        return Ok(result);
    }

    let has_multi = defs.iter().any(|d| d.multiple);

    if !has_multi {
        for (i, _def) in defs.iter().enumerate() {
            if i < n_args {
                result[i] = Some((i, 1));
            }
        }
        if n_args > n_defs {
            result[n_defs] = Some((n_defs, n_args - n_defs));
        }
        return Ok(result);
    }

    // Complex matching
    let mut arg_idx = 0usize;

    for (def_idx, def) in defs.iter().enumerate() {
        if arg_idx >= n_args {
            break;
        }

        if def.multiple {
            // With dash_pos: two multi args can be split by --
            let two_multi = n_defs == 2 && def_idx == 0 && defs[1].multiple;
            if two_multi && dash_pos.map(|p| p > 0).unwrap_or(false) {
                let dp = dash_pos.unwrap();
                result[0] = Some((0, dp));
                result[1] = Some((dp, n_args - dp));
                return Ok(result);
            }

            let remaining_needed: usize = defs[def_idx+1..].iter()
                .filter(|d| !d.multiple)
                .count()
                + defs[def_idx+1..].iter()
                .filter(|d| d.multiple && d.required)
                .count();

            let available = n_args - arg_idx;
            let to_take = available.saturating_sub(remaining_needed);
            let actual_take = to_take.max(if def.required { 1 } else { 0 });

            if actual_take > 0 {
                result[def_idx] = Some((arg_idx, actual_take));
                arg_idx += actual_take;
            }
        } else {
            result[def_idx] = Some((arg_idx, 1));
            arg_idx += 1;
        }
    }

    if arg_idx < n_args {
        result[n_defs] = Some((arg_idx, n_args - arg_idx));
    }

    Ok(result)
}

fn validate_envs(cmd: &Command, state: &mut EvalState) -> Result<(), String> {
    let mut missing = Vec::new();
    let mut setup = Vec::new();

    for env_def in &cmd.envs {
        let val = std::env::var(&env_def.id).ok();

        if val.is_none() {
            if let Some(ref default) = env_def.default {
                match default {
                    DefaultValue::Value(v) => {
                        setup.push(format!("export {}={}", env_def.id, v));
                    }
                    DefaultValue::Fn(f) => {
                        setup.push(format!("export {}=\"$({})\"", env_def.id, f));
                    }
                }
            } else if env_def.required {
                missing.push(env_def.id.clone());
            }
        } else if let Some(val) = val {
            // Validate choice
            if let Some(ChoiceValue::Values(ref choices)) = env_def.choice {
                if !choices.contains(&val) {
                    // output error in bash format - defer to runtime
                }
            }
        }
    }

    if !missing.is_empty() {
        let items: Vec<String> = missing.iter().map(|e| format!("  {}", e)).collect();
        return Err(format!("error: the following required environments were not provided:\n{}", items.join("\n")));
    }

    state.env_setup.extend(setup);
    Ok(())
}

fn check_required_options(cmd: &Command, state: &mut EvalState) -> Result<(), String> {
    let mut missing = Vec::new();

    for fo in &cmd.flag_options {
        if !fo.required || matches!(fo.id.as_str(), "help" | "version") { continue; }
        let var_name = format!("argc_{}", fo.id);
        if !state.is_set(&var_name) {
            missing.push(render_fo_name(fo));
        }
    }

    if !missing.is_empty() {
        let items: Vec<String> = missing.iter().map(|n| format!("  {}", n)).collect();
        return Err(format!("error: the following required arguments were not provided:\n{}", items.join("\n")));
    }

    Ok(())
}

fn find_matching_fo<'a>(cmd: &'a Command, arg: &str) -> Option<&'a FlagOption> {
    let key = arg.split('=').next().unwrap_or(arg);

    cmd.flag_options.iter().find(|fo| {
        if fo.prefixed {
            // Prefixed option: check if arg starts with the base prefix
            let prefix = fo.long_name.as_deref().unwrap_or("");
            // For -X- prefixed, check if arg starts with -X but is longer
            let base = prefix.trim_end_matches('-');
            key.starts_with(base) && key.len() > base.len()
        } else {
            let ln_match = fo.long_name.as_deref().map(|n| n == key).unwrap_or(false);
            let sn_match = fo.short_name.as_deref().map(|n| n == key).unwrap_or(false);
            ln_match || sn_match
        }
    })
}

fn find_subcmd<'a>(cmd: &'a Command, name: &str) -> Option<&'a Command> {
    cmd.subcommands.iter().find(|s| s.name == name || s.aliases.iter().any(|a| a == name))
}

fn get_subcmd_list(cmd: &Command) -> String {
    let names: Vec<String> = cmd.subcommands.iter().flat_map(|s| {
        let mut v = vec![s.name.clone()];
        v.extend(s.aliases.iter().cloned());
        v
    }).collect();
    names.join(", ")
}

fn is_help_flag(arg: &str, cmd: &Command) -> bool {
    let key = arg.split('=').next().unwrap_or(arg);
    cmd.flag_options.iter().find(|f| f.id == "help").map(|f| {
        f.long_name.as_deref() == Some(key) || f.short_name.as_deref() == Some(key)
    }).unwrap_or(false)
}

fn is_version_flag(arg: &str, cmd: &Command) -> bool {
    let key = arg.split('=').next().unwrap_or(arg);
    cmd.flag_options.iter().find(|f| f.id == "version").map(|f| {
        f.long_name.as_deref() == Some(key) || f.short_name.as_deref() == Some(key)
    }).unwrap_or(false)
}

fn is_option_like(arg: &str, cmd: &Command) -> bool {
    let key = arg.split('=').next().unwrap_or(arg);
    // Check if it looks like an option flag
    let is_dash = key.starts_with('-') && key.len() > 1 && !key.starts_with("---");
    let is_plus = key.starts_with('+') && key.len() > 1;
    (is_dash || is_plus) && !key.chars().skip(1).next().map(|c| c.is_numeric()).unwrap_or(false)
}

fn is_potential_combined_short(arg: &str) -> bool {
    arg.starts_with('-') && !arg.starts_with("--") && arg.len() > 2
}

fn try_parse_combined_short(
    arg: &str,
    all_args: &[String],
    idx: usize,
    cmd: &Command,
    state: &mut EvalState,
    option_set: &mut HashMap<String, bool>,
) -> Result<Option<usize>, String> {
    let chars_str = &arg[1..];

    // Check if all chars are valid short flags
    for c in chars_str.chars() {
        let short = format!("-{}", c);
        let found = cmd.flag_options.iter().any(|fo| {
            fo.short_name.as_deref() == Some(&short) && fo.is_flag
        });
        if !found {
            return Ok(None);
        }
    }

    // Parse each char as a flag
    for c in chars_str.chars() {
        let short = format!("-{}", c);
        if let Some(fo) = cmd.flag_options.iter().find(|fo| fo.short_name.as_deref() == Some(&short)) {
            let fo_clone = fo.clone();
            handle_flag_option_checked(&fo_clone, &short, all_args, idx, state, option_set)?;
        }
    }

    Ok(Some(1))
}
