            self.buf.push_str(&format!("[{}]", items.join(", ")));
        }
    }

    // Write num_args pair
    pub fn write_num_args(&mut self, min: usize, max: usize) {
        self.buf.push_str("[\n");
        self.buf.push_str(&format!("{}  {},\n", self.ind(), min));
        self.buf.push_str(&format!("{}  {}\n", self.ind(), max));
        self.buf.push_str(&format!("{}]", self.ind()));
    }

    // Begin a JSON object (increases indent)
    pub fn begin_obj(&mut self) {
        self.buf.push_str("{\n");
        self.indent += 1;
    }

    // End a JSON object (decreases indent)
    pub fn end_obj(&mut self) {
        self.indent -= 1;
        self.buf.push_str(&format!("{}}}", self.ind()));
