use std::fs;
use std::path::Path;
use crate::command::*;

pub fn argc_export(script_path: &str, outpath: Option<&str>) -> Result<(), String> {
    let content = fs::read_to_string(script_path)
        .map_err(|e| format!("Error reading {}: {}", script_path, e))?;

    let script_name = Path::new(script_path)
        .file_stem()
        .and_then(|s| s.to_str())
        .unwrap_or(script_path);

    let cmd = crate::parser::parse_script(&content, script_name);

    let json = format_cmd_json(&cmd, true, 0);

    if let Some(out) = outpath {
        fs::write(out, &json).map_err(|e| format!("Error writing {}: {}", out, e))?;
    } else {
        println!("{}", json);
    }

    Ok(())
}

fn json_str(s: &str) -> String {
    let escaped = s.replace('\\', "\\\\")
        .replace('"', "\\\"")
        .replace('\n', "\\n")
        .replace('\r', "\\r")
        .replace('\t', "\\t");
    format!("\"{}\"", escaped)
}

fn format_cmd_json(cmd: &Command, is_root: bool, indent: usize) -> String {
    let i1 = "  ".repeat(indent + 1);
    let i0 = "  ".repeat(indent);

    let mut fields = Vec::new();

    fields.push(format!("{}\"name\": {}", i1, json_str(&cmd.name)));
    fields.push(format!("{}\"describe\": {}", i1, json_str(&cmd.describe)));

    let ver = cmd.version.as_deref().map(|v| format!("\"{}\"", v)).unwrap_or("null".to_string());
    fields.push(format!("{}\"version\": {}", i1, ver));

    // aliases - always multiline if non-empty
    let aliases_json = format_str_arr_multiline(&cmd.aliases, indent + 1);
    fields.push(format!("{}\"aliases\": {}", i1, aliases_json));

    // flag_options
    let fo_json = format_fo_arr(&cmd.flag_options, indent + 1);
    fields.push(format!("{}\"flag_options\": {}", i1, fo_json));

    // positionals
    let pos_json = format_pos_arr(&cmd.positionals, indent + 1);
    fields.push(format!("{}\"positionals\": {}", i1, pos_json));

    // envs
    let env_json = format_env_arr(&cmd.envs, indent + 1);
    fields.push(format!("{}\"envs\": {}", i1, env_json));

    // subcommands
    let sub_json = format_sub_arr(&cmd.subcommands, indent + 1);
