# options-plus has +oa, +ob, etc. (plus-prefixed long names)
# The help uses "-help" not "--help" OR "+help"
# So when plus options are used, the help uses "-help"

# Revised rule:
# Use -help if:
# 1. At least one long name starts with single - (not --): has_single_hyp_long
# 2. All long names start with + (uses_plus_options)
# Use --help otherwise

# This matches all the data points!

# Let me update the uses_single_hyphen_long and add_builtin_flags logic
cat > /tmp/fix_help_rule.py << 'EOF'
with open('/workspace/src/parser.rs', 'r') as f:
    content = f.read()

# Update uses_single_hyphen_long to also return true for plus-only options
# and add a new method has_any_single_hyphen_long

old = '''    pub fn uses_single_hyphen_long(&self) -> bool {
        let user_fos: Vec<_> = self.flag_options.iter()
            .filter(|fo| !matches!(fo.id.as_str(), "help" | "version"))
            .collect();
        if user_fos.is_empty() { return false; }
        let any_with_ln = user_fos.iter().any(|fo| fo.long_name.is_some());
        if !any_with_ln { return false; }
        user_fos.iter().filter(|fo| fo.long_name.is_some()).all(|fo| {
            let ln = fo.long_name.as_deref().unwrap_or("");
            !ln.starts_with("--") && !ln.starts_with('+')
        })
    }'''

new = '''    pub fn uses_single_hyphen_long(&self) -> bool {
        let user_fos: Vec<_> = self.flag_options.iter()
            .filter(|fo| !matches!(fo.id.as_str(), "help" | "version"))
            .collect();
        if user_fos.is_empty() { return false; }
        let any_with_ln = user_fos.iter().any(|fo| fo.long_name.is_some());
        if !any_with_ln { return false; }
        // Use -help prefix if:
        // 1. ALL long names use single - (not --)
        // 2. Any long name uses single - (not --)
        // 3. All long names use + (plus options)
        let has_any_single = user_fos.iter().any(|fo| {
            fo.long_name.as_deref().map(|n| n.starts_with('-') && !n.starts_with("--")).unwrap_or(false)
        });
        let all_plus = user_fos.iter().filter(|fo| fo.long_name.is_some()).all(|fo| {
            fo.long_name.as_deref().map(|n| n.starts_with('+')).unwrap_or(false)
        });
        has_any_single || all_plus
    }'''

content = content.replace(old, new)
with open('/workspace/src/parser.rs', 'w') as f:
    f.write(content)
print("Fixed")
EOF
