# The alignment logic uses max_left_len = max of all render_option_left results
# render_option_left for "-c":
# short = None, long = "-c"
# name_part = "    -c" (4 spaces + "-c") = 6 chars
# notations = " <C>" -> 4 chars
# total: "    -c <C>" = 10 chars? No...
# 
# Wait, let me check my render_option_left for -c:
# short = None, long = "-c"
# name_part = "    " + long = "    -c"
# But wait: long = "-c" starts with single hyphen NOT double!
# So the "    " prefix should only be for double-hyphen options!

# The issue: I'm using "    " (4 spaces) as the placeholder for missing short name
# But for SINGLE-hyphen options without a short, the placement is different

# Looking at the expected:
# "--oa" (double-hyphen, no short): "      --oa" (6 spaces) = "  " base + "    " placeholder  
# "-c" (single-hyphen, no short): "  -c" (2 spaces) = just "  " base + "-c"
# "-h, -help" (single-hyphen long): "  -h,  -help" = "  -h, " + " -help"
# "  -b, --ob" (short + double-hyphen): "  " + "-b, --ob"

# So the rule is:
# - If long_name starts with "--": add "    " placeholder when no short (for alignment with short column)
# - If long_name starts with "-" (single-hyphen): treat as if it's a short-style name
# - For "+"-prefix: similar to single-hyphen

# The format should be:
# short_name is None AND long_name starts with "--": 
#   "    " + "--long" + notation  (placeholder for "-x, " = 4 chars)
# short_name is None AND long_name starts with "-":
#   "-long" + notation  (no extra indent beyond the 2-space base)
# short_name is present AND long_name starts with "--":
#   "-s, --long" + notation
# short_name is present AND long_name starts with "-" (single):
#   "-s,  -long" + notation (double space between comma and long)

# The "double space" for single-hyphen is interesting!
# "  -h,  -help" has "-h, " then " -help"
# So single-hyphen long names get an extra space after ", "

# This is probably because: when aligned with "--" options, "-" is one char shorter
# so adding an extra space makes them align better

# Let me now fix render_option_left

cat > /tmp/fix_opt_display.py << 'EOF'
with open('/workspace/src/help.rs', 'r') as f:
    content = f.read()

old = '''fn render_option_left(fo: &FlagOption) -> String {
    let long = fo.long_name.as_deref().unwrap_or("");
    let short = fo.short_name.as_deref();

    let name_part = if let Some(s) = short {
        format!("{}, {}", s, long)
    } else {
        format!("    {}", long)
    };'''

new = '''fn render_option_left(fo: &FlagOption) -> String {
    let long = fo.long_name.as_deref().unwrap_or("");
    let short = fo.short_name.as_deref();

    // Determine separator between short and long names
    // Single-hyphen long names use double space: "-h,  -help"  
    // Double-hyphen long names use single space: "-h, --help"
    let name_part = if let Some(s) = short {
        if long.starts_with("--") {
            format!("{}, {}", s, long)
        } else {
            // Single hyphen or plus: use double space
            format!("{},  {}", s, long)
        }
    } else if long.starts_with("--") {
        // Double-hyphen without short: indent with "    " (4 spaces) 
        format!("    {}", long)
    } else {
        // Single-hyphen or plus without short: no extra indent
        long.to_string()
    };'''

content = content.replace(old, new)
with open('/workspace/src/help.rs', 'w') as f:
    f.write(content)
print("Fixed render_option_left")
EOF
