        if pos.describe.is_empty() {
            lines.push(format!("  {}", notation));
        } else if use_next_line {
            // Next-line style with fixed 10-space indent
            lines.push(format!("  {}", notation));
            let wrapped = if width > fixed_indent {
                wrap_text_with_indent(&pos.describe, width, fixed_indent)
            } else {
                pos.describe.clone()
            };
            for (i, wline) in wrapped.lines().enumerate() {
                if i == 0 || wline.starts_with(&fixed_indent_str as &str) {
                    if i == 0 {
                        lines.push(format!("{}{}", fixed_indent_str, wline));
                    } else {
                        lines.push(wline.to_string());
                    }
                } else {
                    lines.push(format!("{}{}", fixed_indent_str, wline));
                }
