    let max_id_len = envs.iter().map(|e| {
        e.id.len() + if e.required { 1 } else { 0 }
    }).max().unwrap_or(0);

    let col_width = max_id_len;

    let mut lines = Vec::new();

    for env in envs {
        let suffix = if env.required { "*" } else { "" };
        let id_str = format!("{}{}", env.id, suffix);

        let mut desc_parts = Vec::new();
        if !env.describe.is_empty() {
            desc_parts.push(env.describe.clone());
        }

        if let Some(ChoiceValue::Values(choices)) = &env.choice {
            desc_parts.push(format!("[possible values: {}]", choices.join(", ")));
        }

        if let Some(DefaultValue::Value(v)) = &env.default {
            desc_parts.push(format!("[default: {}]", v));
        }

        let desc = desc_parts.join(" ");

        if desc.is_empty() {
            lines.push(format!("  {}", id_str));
        } else {
            let padding = " ".repeat(col_width.saturating_sub(id_str.len()) + 2);
            lines.push(format!("  {}{}{}", id_str, padding, desc));
        }
    }

    lines.join("\n")
}

