    let col_width = max_name_len;

    let mut lines = Vec::new();

    for cmd in subcommands {
        let mut extra_info = Vec::new();
        if !cmd.aliases.is_empty() {
            extra_info.push(format!("[aliases: {}]", cmd.aliases.join(", ")));
        }
        if cmd.metadata.default_subcommand.is_some() {
            extra_info.push("[default]".to_string());
        }

        let first_desc = cmd.describe.lines().next().unwrap_or("");

        let desc = if !first_desc.is_empty() && !extra_info.is_empty() {
            format!("{} {}", first_desc, extra_info.join(" "))
        } else if !first_desc.is_empty() {
            first_desc.to_string()
        } else if !extra_info.is_empty() {
            extra_info.join(" ")
        } else {
            String::new()
        };

        if desc.is_empty() {
            lines.push(format!("  {}", cmd.name));
        } else {
            let padding = " ".repeat(col_width.saturating_sub(cmd.name.len()) + 2);
            let indent = 2 + col_width + 2;

            let desc_wrapped = if width > indent {
                wrap_text_with_indent(&desc, width, indent)
            } else {
                desc.clone()
            };

            if desc_wrapped.contains('\n') {
                let first = desc_wrapped.lines().next().unwrap_or("");
                let rest: Vec<&str> = desc_wrapped.lines().skip(1).collect();
                lines.push(format!("  {}{}{}", cmd.name, padding, first));
                for r in rest {
                    lines.push(r.to_string());
                }
            } else {
                lines.push(format!("  {}{}{}", cmd.name, padding, desc_wrapped));
            }
        }
    }

    lines.join("\n")
}

fn wrap_text_at_width(text: &str, width: usize, _indent: usize) -> String {
    if width == 0 {
        return text.to_string();
    }

    let mut result = Vec::new();

    for line in text.lines() {
        if line.len() <= width {
            result.push(line.to_string());
        } else {
            result.extend(wrap_single_line(line, width));
        }
    }

    result.join("\n")
}

fn wrap_text_with_indent(text: &str, width: usize, indent: usize) -> String {
    let available = if width > indent { width - indent } else { 40 };
    let indent_str = " ".repeat(indent);

    let mut result_lines = Vec::new();

    for (i, line) in text.lines().enumerate() {
        if line.len() <= available {
            result_lines.push(line.to_string());
        } else {
            let wrapped = wrap_single_line(line, available);
            for (j, wline) in wrapped.iter().enumerate() {
                if i == 0 && j == 0 {
                    result_lines.push(wline.clone());
                } else {
                    result_lines.push(format!("{}{}", indent_str, wline));
                }
            }
        }
    }

    result_lines.join("\n")
}

fn wrap_single_line(line: &str, width: usize) -> Vec<String> {
    if line.len() <= width {
        return vec![line.to_string()];
    }

    let mut lines = Vec::new();
    let mut current = String::new();

    for word in line.split(' ') {
        if current.is_empty() {
            current = word.to_string();
        } else if current.len() + 1 + word.len() <= width {
            current.push(' ');
            current.push_str(word);
        } else {
            lines.push(current.clone());
            current = word.to_string();
        }
    }

    if !current.is_empty() {
        lines.push(current);
    }

    if lines.is_empty() {
        vec![line.to_string()]
    } else {
        lines
    }
}
