    defs: &[Positional],
    args: &[String],
    dash_pos: Option<usize>,
) -> Result<Vec<Option<(usize, usize)>>, String> {
    let n_defs = defs.len();
    let n_args = args.len();
    let mut result: Vec<Option<(usize, usize)>> = vec![None; n_defs + 1];

    if n_args == 0 {
        return Ok(result);
    }

    let has_multi = defs.iter().any(|d| d.multiple);

    if !has_multi {
        for (i, _def) in defs.iter().enumerate() {
            if i < n_args {
                result[i] = Some((i, 1));
            }
        }
        if n_args > n_defs {
            result[n_defs] = Some((n_defs, n_args - n_defs));
        }
        return Ok(result);
    }

    // Handle dash separator for two multi args
    let two_multi = n_defs == 2 && defs[0].multiple && defs[1].multiple;
    if two_multi {
        if let Some(dp) = dash_pos {
            if dp > 0 {
                result[0] = Some((0, dp));
                if dp < n_args {
                    result[1] = Some((dp, n_args - dp));
                }
                return Ok(result);
            }
        }
    }

    // Determine how many args each position needs as minimum
    // Strategy: from right, each optional multi needs 1 (if available), first multi takes rest
    // Special: first optional multi gets at least 1 if any args available and nothing allocated yet

    let mut arg_idx = 0;

    for (def_idx, def) in defs.iter().enumerate() {
        if arg_idx >= n_args {
            break;
        }

        if def.multiple {
            // Count how many subsequent optional multis need 1 each
            let subsequent_optional_count = defs[def_idx+1..].iter()
                .filter(|d| d.multiple && !d.required)
                .count();
            // Count subsequent required (non-multi and required-multi) that need 1 each
            let subsequent_required_count = defs[def_idx+1..].iter()
                .filter(|d| !d.multiple || d.required)
                .count();
            let subsequent_min = subsequent_optional_count + subsequent_required_count;

            let available = n_args - arg_idx;

            let to_take = if def.required {
                // Required multi: take at least 1, excess goes to it
                available.saturating_sub(subsequent_min).max(1)
            } else {
                // Optional multi: take excess
                let excess = available.saturating_sub(subsequent_min);
                if excess > 0 {
                    excess
                } else if arg_idx == 0 && available > 0 {
                    // If this is the first arg position and nothing else allocated,
                    // we should give something here rather than skip
                    // But only if there won't be enough for required subsequent
                    if subsequent_required_count > 0 && available <= subsequent_required_count {
                        0  // skip this optional multi
                    } else {
                        1  // take 1 minimum for first optional multi
                    }
                } else {
                    0
                }
            };

            if to_take > 0 {
                result[def_idx] = Some((arg_idx, to_take));
                arg_idx += to_take;
            }
        } else {
            result[def_idx] = Some((arg_idx, 1));
            arg_idx += 1;
        }
    }

    if arg_idx < n_args {
        result[n_defs] = Some((arg_idx, n_args - arg_idx));
    }

