# The issue: organize_nested_commands is called ONCE on root
# It moves directly-nested commands (like builder::ls -> under builder)
# But for deeply nested (builder::imagetools::create), the parent is builder::imagetools
# which might NOT be in root.subcommands at the time of processing!
# 
# The order matters! If builder::imagetools is processed BEFORE builder::imagetools::create,
# it gets moved to root.subcommands -> under builder FIRST
# Then when builder::imagetools::create is processed, it needs to find "builder::imagetools"
# but find_and_insert looks for "builder" then "imagetools" by fn_name

# Let me check: find_and_insert(root, ["builder", "imagetools"], create_cmd):
# path[0] = "builder"
# root.subcommands.iter_mut().find(|c| c.command_fn == Some("builder"))
# This finds the builder command (fn_name = "builder")
# Then find_and_insert(builder, ["imagetools"], create_cmd):
# path[0] = "imagetools"
# builder.subcommands.iter_mut().find(|c| c.command_fn == Some("imagetools"))
# This looks for command_fn == "imagetools"
# BUT after the first pass, builder::imagetools was renamed and its command_fn = "builder::imagetools"!
# So command_fn == "imagetools" fails!
# 
# The fix: when searching for parent by fn_name, use the LAST component, not the full path

# Actually the issue is simpler: nested_cmds contains builder::imagetools with:
# path = ["builder"]
# cmd.name = "imagetools"
# cmd.command_fn = Some("builder::imagetools")  <- still has full path!
# 
# When we insert imagetools under builder:
# builder.subcommands.push(imagetools_cmd)
# 
# Then when processing builder::imagetools::create:
# parent_path = ["builder", "imagetools"]
# find_and_insert(root, ["builder", "imagetools"], create_cmd)
# Finds builder (command_fn = "builder") OK
# Then find_and_insert(builder, ["imagetools"], create_cmd)
# Looking for command_fn == "imagetools" but imagetools has command_fn = "builder::imagetools"!
# 
# FIX: in find_and_insert, match by last component of fn_name, not exact match

cat > /tmp/fix_nested.py << 'EOF'
with open('/workspace/src/parser.rs', 'r') as f:
    content = f.read()

old = '''fn find_and_insert(parent: &mut Command, path: &[String], cmd: Command) {
    if path.is_empty() {
        parent.subcommands.push(cmd);
        return;
    }
    let target_fn = &path[0];
    if let Some(child) = parent.subcommands.iter_mut().find(|c| c.command_fn.as_deref() == Some(target_fn.as_str())) {
        find_and_insert(child, &path[1..], cmd);
    } else {
        // Error
        eprintln!("error: {}(?) lack of parent command", 
            cmd.command_fn.as_deref().unwrap_or(""));
    }
}'''

new = '''fn find_and_insert(parent: &mut Command, path: &[String], cmd: Command) {
    if path.is_empty() {
        parent.subcommands.push(cmd);
        return;
    }
    let target_name = &path[0];
    // Find by exact fn_name match OR by the command name (last component of fn_name)
    let found = parent.subcommands.iter_mut().find(|c| {
        c.command_fn.as_deref() == Some(target_name.as_str()) ||
        c.name == target_name.as_str() ||
        c.command_fn.as_deref().map(|f| f.split("::").last() == Some(target_name.as_str())).unwrap_or(false)
    });
    if let Some(child) = found {
        find_and_insert(child, &path[1..], cmd);
    } else {
        // Error
        let fn_str = cmd.command_fn.as_deref().unwrap_or("");
        println!("echo 'Error: {}(line ?) lack of parent command'", fn_str);
        println!("exit 1");
        std::process::exit(1);
    }
}'''

